import React, { useState } from 'react';
import { Plus, MoreHorizontal, Calendar, Flag } from 'lucide-react';
import { Task, TaskStatus } from '../types';
import { MOCK_TASKS } from '../constants';

const KanbanColumn: React.FC<{ 
  title: string; 
  status: TaskStatus; 
  tasks: Task[];
  color: string;
  onMoveTask: (id: number, status: TaskStatus) => void; 
}> = ({ title, status, tasks, color, onMoveTask }) => {
  return (
    <div className="flex-1 min-w-[300px] bg-gray-100 rounded-xl p-4 flex flex-col h-full">
      <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 ${color}`}>
        <h3 className="font-bold text-gray-700 flex items-center gap-2">
          {title}
          <span className="bg-gray-200 text-gray-600 px-2 py-0.5 rounded-full text-xs">{tasks.length}</span>
        </h3>
        <button className="text-gray-400 hover:text-gray-600">
          <MoreHorizontal className="w-5 h-5" />
        </button>
      </div>

      <div className="space-y-3 overflow-y-auto flex-1 pr-1">
        {tasks.map(task => (
          <div 
            key={task.id} 
            className="bg-white p-4 rounded-lg shadow-sm border border-gray-200 hover:shadow-md transition-shadow cursor-pointer group"
          >
            <div className="flex justify-between items-start mb-2">
              <span className={`w-8 h-1 rounded-full mb-2`} style={{ backgroundColor: task.color }}></span>
              <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                 {/* Quick actions mock */}
                 {status !== TaskStatus.DONE && (
                   <button 
                    onClick={() => onMoveTask(task.id, TaskStatus.DONE)}
                    className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded hover:bg-green-200"
                   >Done</button>
                 )}
              </div>
            </div>

            <h4 className="font-semibold text-gray-800 mb-1">{task.title}</h4>
            <p className="text-sm text-gray-500 mb-3 line-clamp-2">{task.description}</p>

            <div className="flex items-center justify-between text-xs text-gray-400 border-t pt-3">
              <div className="flex items-center gap-2">
                {task.dueDate && (
                    <span className="flex items-center gap-1 text-red-400">
                        <Calendar className="w-3 h-3" /> {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                    </span>
                )}
              </div>
              <span className={`flex items-center gap-1 ${task.priority === 'alta' ? 'text-red-500 font-bold' : ''}`}>
                <Flag className="w-3 h-3" /> {task.priority}
              </span>
            </div>
          </div>
        ))}
      </div>

      <button className="mt-3 w-full py-2 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:border-blue-400 hover:text-blue-500 transition-colors flex items-center justify-center gap-2">
        <Plus className="w-4 h-4" /> Nova Tarefa
      </button>
    </div>
  );
};

const Kanban: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>(MOCK_TASKS);

  const moveTask = (id: number, newStatus: TaskStatus) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: newStatus } : t));
  };

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Gerenciador de Tarefas</h1>
          <p className="text-gray-500">Acompanhe o progresso das obrigações contábeis.</p>
        </div>
        <div className="flex gap-3">
          <select className="bg-white border border-gray-300 rounded-lg px-4 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
            <option>Todas as Empresas</option>
            <option>Tech Solutions</option>
            <option>Padaria do João</option>
          </select>
          <button className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors">
            <Plus className="w-4 h-4" /> Nova Tarefa
          </button>
        </div>
      </div>

      <div className="flex gap-6 overflow-x-auto pb-4 h-full">
        <KanbanColumn 
          title="Pendente" 
          status={TaskStatus.PENDING} 
          tasks={tasks.filter(t => t.status === TaskStatus.PENDING)}
          color="border-yellow-400"
          onMoveTask={moveTask}
        />
        <KanbanColumn 
          title="Em Andamento" 
          status={TaskStatus.IN_PROGRESS} 
          tasks={tasks.filter(t => t.status === TaskStatus.IN_PROGRESS)}
          color="border-blue-400"
          onMoveTask={moveTask}
        />
        <KanbanColumn 
          title="Concluída" 
          status={TaskStatus.DONE} 
          tasks={tasks.filter(t => t.status === TaskStatus.DONE)}
          color="border-green-400"
          onMoveTask={moveTask}
        />
      </div>
    </div>
  );
};

export default Kanban;

import React, { useState, useEffect } from 'react';
import { Smartphone, RefreshCw, CheckCircle2 } from 'lucide-react';

const WhatsAppConnect: React.FC = () => {
  const [status, setStatus] = useState<'disconnected' | 'connecting' | 'connected'>('disconnected');
  const [qrCode, setQrCode] = useState<string | null>(null);

  // Simulation of QR Code fetching
  useEffect(() => {
    if (status === 'disconnected') {
      // Mock QR Code (placeholder image)
      setQrCode('https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=WhatsApp-Mock-Connection');
    }
  }, [status]);

  const handleSimulateConnection = () => {
    setStatus('connecting');
    setTimeout(() => {
      setStatus('connected');
    }, 2000);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-8">
      <div className="text-center">
        <h1 className="text-2xl font-bold text-gray-800 mb-2">Conexão WhatsApp</h1>
        <p className="text-gray-500 max-w-md">Escaneie o QR Code para conectar o sistema ao seu WhatsApp e habilitar o envio automático de mensagens.</p>
      </div>

      <div className="bg-white p-8 rounded-2xl shadow-lg border border-gray-100 flex flex-col items-center">
        {status === 'connected' ? (
          <div className="text-center py-10">
            <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <CheckCircle2 className="w-10 h-10 text-green-600" />
            </div>
            <h3 className="text-xl font-bold text-gray-800">Conectado com Sucesso!</h3>
            <p className="text-gray-500 mt-2">O serviço está pronto para enviar mensagens.</p>
            <button 
              onClick={() => setStatus('disconnected')}
              className="mt-6 text-red-500 text-sm hover:underline"
            >
              Desconectar
            </button>
          </div>
        ) : (
          <>
            <div className="relative group">
              {status === 'connecting' && (
                <div className="absolute inset-0 bg-white/80 backdrop-blur-sm flex items-center justify-center z-10">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-600"></div>
                </div>
              )}
              <div className="border-4 border-gray-800 rounded-xl p-2 bg-white">
                {qrCode ? (
                  <img src={qrCode} alt="WhatsApp QR Code" className="w-64 h-64" />
                ) : (
                  <div className="w-64 h-64 bg-gray-100 flex items-center justify-center text-gray-400">
                    Carregando QR...
                  </div>
                )}
              </div>
            </div>

            <div className="mt-8 space-y-4 w-full max-w-sm">
              <div className="flex items-start gap-3 text-sm text-gray-600">
                <span className="flex-shrink-0 w-6 h-6 bg-gray-100 rounded-full flex items-center justify-center font-bold">1</span>
                <p>Abra o WhatsApp no seu celular</p>
              </div>
              <div className="flex items-start gap-3 text-sm text-gray-600">
                <span className="flex-shrink-0 w-6 h-6 bg-gray-100 rounded-full flex items-center justify-center font-bold">2</span>
                <p>Toque em <strong>Menu</strong> ou <strong>Configurações</strong> e selecione <strong>Aparelhos Conectados</strong></p>
              </div>
              <div className="flex items-start gap-3 text-sm text-gray-600">
                <span className="flex-shrink-0 w-6 h-6 bg-gray-100 rounded-full flex items-center justify-center font-bold">3</span>
                <p>Toque em <strong>Conectar um aparelho</strong> e aponte a câmera para esta tela</p>
              </div>
            </div>

            <button 
              onClick={handleSimulateConnection}
              className="mt-6 flex items-center gap-2 text-blue-600 hover:text-blue-700 text-sm font-medium"
            >
              <RefreshCw className="w-4 h-4" /> Atualizar Código
            </button>
          </>
        )}
      </div>

      <div className="flex items-center gap-2 text-sm text-gray-400">
        <Smartphone className="w-4 h-4" />
        <span>Mantenha seu celular conectado à internet</span>
      </div>
    </div>
  );
};

export default WhatsAppConnect;

