// Holidays (Month-Day format)
const HOLIDAYS = [
  '01-01', // New Year's Day
  '04-21', // Tiradentes
  '05-01', // Labor Day
  '09-07', // Independence Day
  '10-12', // Our Lady of Aparecida
  '11-02', // All Souls' Day
  '11-15', // Republic Proclamation Day
  '12-25'  // Christmas
];

export const formatarData = (date: Date): string => {
  const dia = String(date.getDate()).padStart(2, '0');
  const mes = String(date.getMonth() + 1).padStart(2, '0');
  const ano = date.getFullYear();
  return `${dia}/${mes}/${ano}`;
};

export const isDiaUtil = (date: Date): boolean => {
  const diaSemana = date.getDay(); // 0=Sunday, 6=Saturday
  if (diaSemana === 0 || diaSemana === 6) {
    return false;
  }

  const diaMes = `${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  if (HOLIDAYS.includes(diaMes)) {
    return false;
  }

  return true;
};

export const calcularQuintoDiaUtil = (mes: number, ano: number): string => {
  // Logic: Next month (handling December -> January)
  let mesSeguinte = mes + 1;
  let anoSeguinte = ano;
  if (mesSeguinte > 12) {
      mesSeguinte = 1;
      anoSeguinte++;
  }

  let dia = 1;
  let diasUteisEncontrados = 0;
  let finalDate = null;

  while (diasUteisEncontrados < 5) {
      const date = new Date(anoSeguinte, mesSeguinte - 1, dia);
      if (isDiaUtil(date)) {
          diasUteisEncontrados++;
          finalDate = date;
      }

      if (diasUteisEncontrados < 5) {
          dia++;
      }
  }

  return finalDate ? formatarData(finalDate) : '';
};

export const calcularVencimentoComRegra = (mes: number, ano: number, diaVencimento: number, regra: 'antecipado' | 'postergado'): string => {
  let mesSeguinte = mes + 1;
  let anoSeguinte = ano;
  if (mesSeguinte > 12) {
      mesSeguinte = 1;
      anoSeguinte++;
  }

  let date = new Date(anoSeguinte, mesSeguinte - 1, diaVencimento);

  if (!isDiaUtil(date)) {
      if (regra === 'antecipado') {
          while (!isDiaUtil(date)) {
              date.setDate(date.getDate() - 1);
          }
      } else if (regra === 'postergado') {
          while (!isDiaUtil(date)) {
              date.setDate(date.getDate() + 1);
          }
      }
  }

  return formatarData(date);
};

export const calcularUltimoDiaUtil = (mes: number, ano: number): string => {
  let mesSeguinte = mes + 1;
  let anoSeguinte = ano;
  if (mesSeguinte > 12) {
      mesSeguinte = 1;
      anoSeguinte++;
  }

  // Last day of next month
  const ultimoDia = new Date(anoSeguinte, mesSeguinte, 0).getDate();
  let date = new Date(anoSeguinte, mesSeguinte - 1, ultimoDia);

  while (!isDiaUtil(date)) {
      date.setDate(date.getDate() - 1);
  }

  return formatarData(date);
};

export const calcularTodosVencimentos = (competencia: string) => {
  if (!competencia || !competencia.includes('/')) return {};

  const [mesStr, anoStr] = competencia.split('/');
  const mes = parseInt(mesStr);
  const ano = parseInt(anoStr);

  if (isNaN(mes) || isNaN(ano)) return {};

  return {
      'Contracheque': calcularQuintoDiaUtil(mes, ano),
      'Folha de Pagamento': calcularQuintoDiaUtil(mes, ano), // Often same as Contracheque logic
      'FGTS': calcularVencimentoComRegra(mes, ano, 20, 'antecipado'),
      'INSS': calcularVencimentoComRegra(mes, ano, 20, 'antecipado'),
      'Simples Nacional': calcularVencimentoComRegra(mes, ano, 20, 'postergado'),
      'Parcelamento': calcularUltimoDiaUtil(mes, ano),
      'Honorários': calcularVencimentoComRegra(mes, ano, 10, 'postergado'), // Example rule
  };
};

