import React, { useState, useEffect } from 'react';
import { Upload as UploadIcon, X, FileText, Calendar, AlertCircle } from 'lucide-react';
import { MOCK_COMPANIES, DOCUMENT_CATEGORIES } from '../constants';
import { calcularTodosVencimentos } from '../utils/dateHelpers';
import { UploadedFile } from '../types';

interface UploadProps {
  preFillData?: {
    companyId: number;
    competence: string;
  } | null;
}

const Upload: React.FC<UploadProps> = ({ preFillData }) => {
  const [competence, setCompetence] = useState('');
  const [selectedCompanyId, setSelectedCompanyId] = useState<number | string>('');
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [calculatedDates, setCalculatedDates] = useState<Record<string, string>>({});
  const [isDragging, setIsDragging] = useState(false);

  useEffect(() => {
    // If pre-fill data exists, use it
    if (preFillData) {
      setCompetence(preFillData.competence);
      setSelectedCompanyId(preFillData.companyId);
    } else {
      // Set current competence default if not provided
      const now = new Date();
      const mm = String(now.getMonth() + 1).padStart(2, '0');
      const yyyy = now.getFullYear();
      setCompetence(`${mm}/${yyyy}`);
    }
  }, [preFillData]);

  useEffect(() => {
    // Recalculate dates when competence changes
    if (competence.match(/^\d{2}\/\d{4}$/)) {
        const dates = calcularTodosVencimentos(competence);
        setCalculatedDates(dates);

        // Update existing files dates if they have a category that matches a rule
        setFiles(prev => prev.map(f => {
            if (dates[f.category]) {
                return { ...f, dueDate: dates[f.category] };
            }
            return f;
        }));
    }
  }, [competence]);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    processFiles(Array.from(e.dataTransfer.files));
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      processFiles(Array.from(e.target.files));
    }
  };

  const processFiles = (fileList: File[]) => {
    const newFiles: UploadedFile[] = fileList.map(file => {
      const nameLower = file.name.toLowerCase();
      let category = '';
      let dueDate = '';

      // Simple heuristic for category guessing
      if (nameLower.includes('contracheque')) category = 'Contracheque';
      else if (nameLower.includes('fgts')) category = 'FGTS';
      else if (nameLower.includes('inss')) category = 'INSS';
      else if (nameLower.includes('simples')) category = 'Simples Nacional';
      else if (nameLower.includes('folha')) category = 'Folha de Pagamento';
      else if (nameLower.includes('honor')) category = 'Honorários';
      else if (nameLower.includes('fiscais') || nameLower.includes('nota')) category = 'Notas Fiscais';

      if (category && calculatedDates[category]) {
          dueDate = calculatedDates[category];
      }

      return {
        name: file.name,
        size: file.size,
        category: category || DOCUMENT_CATEGORIES[0],
        dueDate: dueDate,
        file: file
      };
    });

    setFiles(prev => [...prev, ...newFiles]);
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const updateFileCategory = (index: number, newCategory: string) => {
    setFiles(prev => prev.map((f, i) => {
        if (i === index) {
            const newDate = calculatedDates[newCategory] || f.dueDate;
            return { ...f, category: newCategory, dueDate: newDate };
        }
        return f;
    }));
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Upload de Documentos</h1>
          <p className="text-gray-500">Envie arquivos e o sistema calculará os vencimentos automaticamente.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Settings Card */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-fit">
            <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2">
                <AlertCircle className="w-5 h-5 text-blue-500" /> Informações Básicas
            </h3>

            <div className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Empresa</label>
                    <select 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                        value={selectedCompanyId}
                        onChange={e => setSelectedCompanyId(e.target.value)}
                    >
                        <option value="">Selecione uma empresa...</option>
                        {MOCK_COMPANIES.map(c => (
                            <option key={c.id} value={c.id}>{c.name} ({c.docNumber})</option>
                        ))}
                    </select>
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Competência (MM/AAAA)</label>
                    <input 
                        type="text"
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                        placeholder="MM/AAAA"
                        value={competence}
                        onChange={e => {
                            let val = e.target.value.replace(/\D/g, '');
                            if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                            setCompetence(val);
                        }}
                    />
                    <p className="text-xs text-gray-500 mt-1">Ao alterar a competência, os vencimentos serão recalculados.</p>
                </div>
            </div>
        </div>

        {/* Dropzone */}
        <div 
            className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center transition-colors
                ${isDragging ? 'border-blue-500 bg-blue-50' : 'border-gray-300 hover:border-blue-400 bg-gray-50'}`}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
        >
            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
                <UploadIcon className="w-8 h-8 text-blue-600" />
            </div>
            <h3 className="text-lg font-semibold text-gray-800">Arraste arquivos aqui</h3>
            <p className="text-gray-500 mb-4">ou clique para selecionar do computador</p>
            <input 
                type="file" 
                multiple 
                className="hidden" 
                id="file-input"
                onChange={handleFileSelect}
            />
            <label 
                htmlFor="file-input"
                className="bg-blue-600 text-white px-6 py-2 rounded-lg cursor-pointer hover:bg-blue-700 transition-colors"
            >
                Selecionar Arquivos
            </label>
        </div>
      </div>

      {files.length > 0 && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-4 border-b border-gray-100 bg-gray-50">
                  <h3 className="font-bold text-gray-700">Arquivos Selecionados ({files.length})</h3>
              </div>
              <div className="p-4 space-y-3">
                  {files.map((file, idx) => (
                      <div key={idx} className="flex flex-col md:flex-row gap-4 p-4 border border-gray-200 rounded-lg bg-white items-start md:items-center">
                          <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2 mb-1">
                                  <FileText className="w-4 h-4 text-gray-400" />
                                  <span className="font-medium text-gray-800 truncate">{file.name}</span>
                              </div>
                              <span className="text-xs text-gray-500">{formatSize(file.size)}</span>
                          </div>

                          <div className="flex-1 w-full md:w-auto">
                              <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Categoria</label>
                              <select 
                                className="w-full text-sm border-gray-300 rounded px-2 py-1.5 border"
                                value={file.category}
                                onChange={(e) => updateFileCategory(idx, e.target.value)}
                              >
                                  {DOCUMENT_CATEGORIES.map(cat => (
                                      <option key={cat} value={cat}>{cat}</option>
                                  ))}
                              </select>
                          </div>

                          <div className="w-full md:w-40">
                              <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Vencimento</label>
                              <div className="relative">
                                <Calendar className="w-3 h-3 absolute left-2 top-1/2 -translate-y-1/2 text-gray-400" />
                                <input 
                                    type="text" 
                                    className="w-full text-sm border-gray-300 rounded pl-7 px-2 py-1.5 border"
                                    value={file.dueDate}
                                    placeholder="DD/MM/AAAA"
                                    onChange={(e) => {
                                        const newFiles = [...files];
                                        newFiles[idx].dueDate = e.target.value;
                                        setFiles(newFiles);
                                    }}
                                />
                              </div>
                          </div>

                          <button 
                            onClick={() => removeFile(idx)}
                            className="text-gray-400 hover:text-red-500 p-2"
                          >
                              <X className="w-5 h-5" />
                          </button>
                      </div>
                  ))}
              </div>
              <div className="p-4 border-t border-gray-100 flex justify-end">
                  <button className="bg-green-600 text-white px-8 py-3 rounded-lg hover:bg-green-700 shadow-lg shadow-green-900/20 font-medium flex items-center gap-2">
                      <UploadIcon className="w-5 h-5" /> Enviar Todos
                  </button>
              </div>
          </div>
      )}
    </div>
  );
};

export default Upload;

import React, { useState } from 'react';
import { Upload, CalendarCheck, Search, FileText, Check, X, Play, Settings as SettingsIcon } from 'lucide-react';
import { MOCK_COMPANIES, DOCUMENT_CATEGORIES } from '../constants';
import { UserSettings } from '../types';

interface DocumentsProps {
  userSettings: UserSettings;
  onNavigateToUpload: (companyId: number, competence: string) => void;
}

const Documents: React.FC<DocumentsProps> = ({ userSettings, onNavigateToUpload }) => {
  const [competence, setCompetence] = useState('09/2023');
  const [activeCompetence, setActiveCompetence] = useState('09/2023'); // Drives the matrix

  const [localPath, setLocalPath] = useState('');
  const [processing, setProcessing] = useState(false);

  // Filters
  const [selectedCompanies, setSelectedCompanies] = useState<string[]>([]);
  const [selectedCategories, setSelectedCategories] = useState<string[]>([]);

  // Status Matrix State: "companyId-category" -> 'sent' | 'pending'
  const [docStatuses, setDocStatuses] = useState<Record<string, 'sent' | 'pending'>>({});

  // Use visible categories from settings, fall back to all if empty
  const defaultVisibleCategories = userSettings.visibleDocumentCategories.length > 0 
    ? userSettings.visibleDocumentCategories 
    : DOCUMENT_CATEGORIES.slice(0, 8);

  const handleProcess = () => {
      setProcessing(true);
      setTimeout(() => setProcessing(false), 2000);
  };

  // Company Filter Logic
  const toggleCompanySelection = (id: string) => {
    setSelectedCompanies(prev => 
      prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]
    );
  };
  const toggleSelectAllCompanies = () => {
    if (selectedCompanies.length === MOCK_COMPANIES.length) {
      setSelectedCompanies([]);
    } else {
      setSelectedCompanies(MOCK_COMPANIES.map(c => String(c.id)));
    }
  };

  // Category Filter Logic (Same logic as Companies)
  const toggleCategorySelection = (cat: string) => {
    setSelectedCategories(prev => 
      prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]
    );
  };
  const toggleSelectAllCategories = () => {
    if (selectedCategories.length === defaultVisibleCategories.length) {
      setSelectedCategories([]);
    } else {
      setSelectedCategories(defaultVisibleCategories);
    }
  };

  const getFilteredCategories = () => {
     if (selectedCategories.length > 0) return selectedCategories;
     return defaultVisibleCategories;
  };

  const getFilteredCompanies = () => {
      if (selectedCompanies.length > 0) {
          return MOCK_COMPANIES.filter(c => selectedCompanies.includes(String(c.id)));
      }
      return MOCK_COMPANIES;
  };

  // Toggle Document Status
  const toggleStatus = (companyId: number, category: string) => {
      const key = `${companyId}-${category}`;
      setDocStatuses(prev => {
          const currentStatus = prev[key] || ((companyId + category.length) % 3 !== 0 ? 'sent' : 'pending'); // Mock default logic
          return {
              ...prev,
              [key]: currentStatus === 'sent' ? 'pending' : 'sent'
          };
      });
  };

  const getStatus = (companyId: number, category: string) => {
      const key = `${companyId}-${category}`;
      if (docStatuses[key]) return docStatuses[key];
      // Mock random default status if not in state
      return (companyId + category.length) % 3 !== 0 ? 'sent' : 'pending';
  };

  const handleSearchCompetence = (e: React.FormEvent) => {
      e.preventDefault();
      setActiveCompetence(competence);
  };

  return (
    <div className="space-y-6">

      {/* Competence Selection Card */}
      <div className="bg-white rounded-xl shadow-sm border-0 overflow-hidden mb-4">
        <div className="bg-blue-600 text-white py-3 px-6">
            <h5 className="mb-0 flex items-center gap-2 font-bold">
                <CalendarCheck className="w-5 h-5" /> Verificar Documentos por Competência (Normal)
            </h5>
        </div>
        <div className="p-6">
            <form onSubmit={handleSearchCompetence}>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1">
                        <label htmlFor="competencia" className="block text-sm font-semibold text-gray-700 mb-2">Digite a competência (MM/AAAA)</label>
                        <div className="relative">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">
                                <CalendarCheck className="w-5 h-5" />
                            </span>
                            <input 
                                type="text" 
                                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500" 
                                id="competencia" 
                                placeholder="Ex: 05/2023" 
                                value={competence}
                                onChange={(e) => {
                                    let val = e.target.value.replace(/\D/g, '');
                                    if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                                    setCompetence(val);
                                }}
                                required 
                            />
                        </div>
                    </div>
                    <div className="flex-1 md:flex-none md:w-48">
                        <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition-colors flex items-center justify-center gap-2 font-medium">
                            <Search className="w-4 h-4" /> Verificar
                        </button>
                    </div>
                </div>
            </form>
        </div>
      </div>

      {/* Automatic Processing Card */}
      <div className="bg-white rounded-xl shadow-sm border border-blue-100 overflow-hidden">
        <div className="bg-blue-50 p-4 border-b border-blue-100 flex items-center gap-2 text-blue-800">
            <SettingsIcon className="w-5 h-5" />
            <h3 className="font-bold">Processamento Automático</h3>
        </div>
        <div className="p-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="lg:col-span-1">
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Caminho do Diretório</label>
                    <div className="input-group flex items-center border border-gray-300 rounded-lg overflow-hidden bg-white">
                         <span className="px-3 text-gray-400 bg-gray-50 border-r py-2"><FileText className="w-4 h-4" /></span>
                         <input 
                            type="text" 
                            className="flex-1 px-3 py-2 outline-none text-sm"
                            placeholder="C:\Documentos\..."
                            value={localPath}
                            onChange={(e) => setLocalPath(e.target.value)}
                         />
                    </div>
                </div>

                {/* Company Filter */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Filtrar Empresas</label>
                  <div className="relative group">
                    <button className="w-full text-left border border-gray-300 rounded-lg px-3 py-2 text-sm bg-white flex justify-between items-center">
                      <span className="truncate">
                        {selectedCompanies.length === 0 ? 'Todas as Empresas' : `${selectedCompanies.length} selecionadas`}
                      </span>
                    </button>
                    <div className="absolute top-full left-0 w-full mt-1 bg-white border border-gray-200 rounded-lg shadow-lg z-20 hidden group-hover:block hover:block p-2 max-h-48 overflow-y-auto">
                        <label className="flex items-center gap-2 p-1 hover:bg-gray-50 rounded cursor-pointer border-b mb-1 pb-1">
                          <input 
                            type="checkbox" 
                            className="rounded text-blue-600"
                            checked={selectedCompanies.length === MOCK_COMPANIES.length}
                            onChange={toggleSelectAllCompanies}
                          />
                          <span className="text-sm font-bold text-gray-700">Selecionar Todas</span>
                        </label>
                        {MOCK_COMPANIES.map(c => (
                          <label key={c.id} className="flex items-center gap-2 p-1 hover:bg-gray-50 rounded cursor-pointer">
                            <input 
                              type="checkbox" 
                              className="rounded text-blue-600"
                              checked={selectedCompanies.includes(String(c.id))}
                              onChange={() => toggleCompanySelection(String(c.id))}
                            />
                            <span className="text-sm text-gray-600 truncate">{c.name}</span>
                          </label>
                        ))}
                    </div>
                  </div>
                </div>

                {/* Category Filter (Multi-select) */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Filtrar Categorias</label>
                  <div className="relative group">
