                                 <input 
                                    type="checkbox" 
                                    className="w-4 h-4 text-blue-600 rounded"
                                    checked={scheduleChannels.email}
                                    onChange={(e) => setScheduleChannels({...scheduleChannels, email: e.target.checked})}
