import React, { useState, useRef } from 'react';
import { Search, Plus, MoreVertical, Building2, User, Copy, Check, X, Upload } from 'lucide-react';
import { MOCK_COMPANIES } from '../constants';
import { Company } from '../types';
import * as XLSX from 'xlsx';

const Companies: React.FC = () => {
  const [companies, setCompanies] = useState<Company[]>(MOCK_COMPANIES);
  const [copiedId, setCopiedId] = useState<number | null>(null);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newCompany, setNewCompany] = useState<Partial<Company>>({
    name: '',
    docNumber: '',
    type: 'CNPJ',
    email: '',
    whatsapp: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleCopy = (doc: string, id: number) => {
    const cleanDoc = doc.replace(/\D/g, '');
    navigator.clipboard.writeText(cleanDoc);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCompany.name || !newCompany.docNumber) return;

    const companyToAdd: Company = {
        id: Date.now(),
        name: newCompany.name || '',
        docNumber: newCompany.docNumber || '',
        type: (newCompany.type as any) || 'CNPJ',
        email: newCompany.email || '',
        whatsapp: newCompany.whatsapp || ''
    };

    setCompanies([...companies, companyToAdd]);
    setIsModalOpen(false);
    setNewCompany({ name: '', docNumber: '', type: 'CNPJ', email: '', whatsapp: '' });
  };

  const handleImportClick = () => {
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      // Get data as array of arrays to handle columns by index
      const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1 });

      // Remove header row if it exists (assuming row 0 is header)
      // You might want to add a check here, but we'll assume row 0 is header for now
      const rows = data.slice(1);

      const importedCompanies: Company[] = [];

      rows.forEach((row) => {
        // Col 0: Doc, Col 1: Name, Col 2: Email, Col 3: Whatsapp, Col 4: Type
        if (row.length < 2) return; // Skip empty rows

        const docNumberRaw = String(row[0] || '');
        const name = String(row[1] || '');
        const email = String(row[2] || '');
        const whatsapp = String(row[3] || '');
        let typeRaw = String(row[4] || '').toUpperCase().trim();

        // Normalize Type
        let type: 'CNPJ' | 'CPF' | 'MEI' = 'CNPJ';
        if (typeRaw === 'MEI') type = 'MEI';
        else if (typeRaw === 'CPF') type = 'CPF';

        if (docNumberRaw && name) {
          importedCompanies.push({
            id: Date.now() + Math.random(),
            docNumber: docNumberRaw,
            name: name,
            email: email,
            whatsapp: whatsapp,
            type: type
          });
        }
      });

      if (importedCompanies.length > 0) {
        setCompanies(prev => [...prev, ...importedCompanies]);
        alert(`${importedCompanies.length} empresas importadas com sucesso!`);
      } else {
        alert("Nenhuma empresa válida encontrada no arquivo.");
      }

      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Empresas</h1>
          <p className="text-gray-500">Gerencie o cadastro de empresas e clientes.</p>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          {/* Hidden File Input */}
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept=".xlsx, .xls, .csv" 
            className="hidden" 
          />

          <button 
            onClick={handleImportClick}
            className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg hover:bg-gray-50 transition-colors flex items-center gap-2"
          >
            <Upload className="w-4 h-4" /> Importar Excel
          </button>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors"
          >
            <Plus className="w-4 h-4" /> Nova Empresa
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        {/* Filters */}
        <div className="p-4 border-b border-gray-100 flex gap-4">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input 
              type="text" 
              placeholder="Buscar por nome, CNPJ ou email..." 
              className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>
          <select className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
            <option value="">Todos os Tipos</option>
            <option value="CNPJ">CNPJ</option>
            <option value="MEI">MEI</option>
            <option value="CPF">CPF</option>
          </select>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 text-gray-600 font-medium">
              <tr>
                <th className="px-6 py-4">Tipo (Copiar)</th>
                <th className="px-6 py-4">Documento</th>
                <th className="px-6 py-4">Razão Social / Nome</th>
                <th className="px-6 py-4">Contato</th>
                <th className="px-6 py-4 text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {companies.map((company) => (
                <tr key={company.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4">
                     <button 
                      onClick={() => handleCopy(company.docNumber, company.id)}
                      className={`flex items-center gap-1 px-2 py-1 rounded border transition-colors text-xs font-medium
                        ${copiedId === company.id 
                            ? 'bg-green-100 text-green-700 border-green-200' 
                            : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                     >
                        {copiedId === company.id ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                        {copiedId === company.id ? 'Copiado!' : 'Copiar'}
                     </button>
                  </td>
                  <td className="px-6 py-4 font-mono text-gray-600">{company.docNumber}</td>
                   <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded bg-blue-100 text-blue-600 flex items-center justify-center">
                        {company.type === 'CPF' ? <User className="w-4 h-4" /> : <Building2 className="w-4 h-4" />}
                      </div>
                      <span className="font-semibold text-gray-900">{company.name}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-gray-900">{company.email}</span>
                      <span className="text-gray-500 text-xs">{company.whatsapp}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2">
                        <button className="text-blue-600 hover:text-blue-800 text-xs font-medium border border-blue-200 px-2 py-1 rounded hover:bg-blue-50">Editar</button>
                        <button className="text-red-500 hover:text-red-700 text-xs font-medium border border-red-200 px-2 py-1 rounded hover:bg-red-50">Excluir</button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* New Company Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl w-full max-w-md">
             <div className="p-4 border-b border-gray-100 flex justify-between items-center">
                <h3 className="font-bold text-gray-800">Nova Empresa</h3>
                <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                   <X className="w-5 h-5" />
                </button>
             </div>
             <form onSubmit={handleSaveCompany} className="p-6 space-y-4">
                <div>
                   <label className="block text-sm font-semibold text-gray-700 mb-1">Razão Social / Nome*</label>
                   <input 
                      type="text" 
                      className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                      value={newCompany.name}
                      onChange={(e) => setNewCompany({...newCompany, name: e.target.value})}
                      required
                   />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Tipo*</label>
                    <select 
                      className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none"
                      value={newCompany.type}
                      onChange={(e) => setNewCompany({...newCompany, type: e.target.value as any})}
                    >
                      <option value="CNPJ">CNPJ</option>
                      <option value="MEI">MEI</option>
                      <option value="CPF">CPF</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Documento*</label>
                    <input 
                        type="text" 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                        value={newCompany.docNumber}
                        onChange={(e) => setNewCompany({...newCompany, docNumber: e.target.value})}
                        required
                    />
                  </div>
                </div>

                <div>
                   <label className="block text-sm font-semibold text-gray-700 mb-1">E-mail</label>
                   <input 
                      type="email" 
                      className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                      value={newCompany.email}
                      onChange={(e) => setNewCompany({...newCompany, email: e.target.value})}
                   />
                </div>

                <div>
                   <label className="block text-sm font-semibold text-gray-700 mb-1">WhatsApp</label>
                   <input 
                      type="text" 
                      className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                      value={newCompany.whatsapp}
                      onChange={(e) => setNewCompany({...newCompany, whatsapp: e.target.value})}
                   />
                </div>

                <div className="flex justify-end gap-3 mt-6">
                    <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg">Cancelar</button>
                    <button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Salvar</button>
                </div>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

