  onSave: (task: Task) => void;
  onDelete?: (taskId: number) => void;
}

const COLORS = [
  { value: '#FF6B6B', label: 'Vermelho' },
  { value: '#4ECDC4', label: 'Verde Água' },
  { value: '#45B7D1', label: 'Azul Claro' },
  { value: '#FFA07A', label: 'Salmão' },
  { value: '#98D8C8', label: 'Verde Menta' },
  { value: '#F7DC6F', label: 'Amarelo Claro' },
  { value: '#BB8FCE', label: 'Lavanda' },
  { value: '#85C1E9', label: 'Azul Céu' },
  { value: '#F8C471', label: 'Laranja Claro' },
  { value: '#D7BDE2', label: 'Lilás' }
];

const TaskModal: React.FC<TaskModalProps> = ({ isOpen, onClose, task, onSave, onDelete }) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    priority: TaskPriority.MEDIUM,
    status: TaskStatus.PENDING,
    color: COLORS[0].value,
    dueDate: '',
    recurrence: 'nenhuma',
    dayOfWeek: 'segunda',
    recurrenceDate: '',
    companyId: undefined,
  });

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        priority: TaskPriority.MEDIUM,
        status: TaskStatus.PENDING,
        color: COLORS[0].value,
        dueDate: '',
        recurrence: 'nenhuma',
        dayOfWeek: 'segunda',
        recurrenceDate: '',
      });
    }
  }, [task, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ ...formData, id: task?.id || Date.now() } as Task);
    onClose();
  };

  const handleDelete = () => {
    if (task && onDelete) {
        if(window.confirm("Tem certeza que deseja excluir esta tarefa?")) {
            onDelete(task.id);
            onClose();
        }
    }
  };

  const companiesNormal = MOCK_COMPANIES.filter(c => c.type !== 'MEI');
  const companiesMei = MOCK_COMPANIES.filter(c => c.type === 'MEI');

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
