import { Company, Task, Document } from '../types';

const API_URL = '/api';

export const api = {
  // Companies
  getCompanies: async (): Promise<Company[]> => {
    const res = await fetch(`${API_URL}/companies`);
    if (!res.ok) throw new Error('Failed to fetch companies');
    return res.json();
  },

  saveCompany: async (company: Partial<Company>): Promise<{ success: boolean; id: number }> => {
    const res = await fetch(`${API_URL}/companies`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(company),
    });
    return res.json();
  },

  deleteCompany: async (id: number): Promise<void> => {
    await fetch(`${API_URL}/companies/${id}`, { method: 'DELETE' });
  },

  // Document Status
  getDocumentStatuses: async (competence: string): Promise<any[]> => {
    const res = await fetch(`${API_URL}/documents/status?competence=${competence}`);
    return res.json();
  },

  updateDocumentStatus: async (companyId: number, category: string, competence: string, status: string): Promise<void> => {
    await fetch(`${API_URL}/documents/status`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ companyId, category, competence, status }),
    });
  },

  // WhatsApp
  getWhatsAppStatus: async (): Promise<{ status: string; qr: string | null; info?: any }> => {
    const res = await fetch(`${API_URL}/whatsapp/status`);
    return res.json();
  },

  disconnectWhatsApp: async (): Promise<void> => {
    await fetch(`${API_URL}/whatsapp/disconnect`, { method: 'POST' });
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Search, Plus, Building2, User, Copy, Check, X, Upload, Pencil, Trash, Loader2 } from 'lucide-react';
import { Company } from '../types';
import { api } from '../services/api';
import * as XLSX from 'xlsx';

const Companies: React.FC = () => {
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);
  const [copiedId, setCopiedId] = useState<number | null>(null);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [newCompany, setNewCompany] = useState<Partial<Company>>({
    name: '',
    docNumber: '',
    type: 'CNPJ',
    email: '',
    whatsapp: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load Companies from API
  const loadCompanies = async () => {
      setLoading(true);
      try {
          const data = await api.getCompanies();
          setCompanies(data);
      } catch (error) {
          console.error("Erro ao carregar empresas:", error);
      } finally {
          setLoading(false);
      }
  };

  useEffect(() => {
      loadCompanies();
  }, []);

  const handleCopy = (doc: string, id: number) => {
    const cleanDoc = doc.replace(/\D/g, '');
    navigator.clipboard.writeText(cleanDoc);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleEditCompany = (company: Company) => {
    setNewCompany({
        name: company.name,
        docNumber: company.docNumber,
        type: company.type,
        email: company.email,
        whatsapp: company.whatsapp
    });
    setEditingId(company.id);
    setIsModalOpen(true);
  };

  const handleDeleteCompany = async (id: number) => {
    if (window.confirm('Tem certeza que deseja excluir esta empresa?')) {
        try {
            await api.deleteCompany(id);
            setCompanies(prev => prev.filter(c => c.id !== id));
        } catch (error) {
            alert('Erro ao excluir empresa.');
        }
    }
  };

  const handleSaveCompany = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCompany.name || !newCompany.docNumber) return;

    try {
        const payload = {
            id: editingId || undefined,
            name: newCompany.name,
            docNumber: newCompany.docNumber,
            type: newCompany.type,
            email: newCompany.email,
            whatsapp: newCompany.whatsapp
        };

        await api.saveCompany(payload);
        await loadCompanies(); // Reload to get fresh data/IDs

        setIsModalOpen(false);
        setEditingId(null);
        setNewCompany({ name: '', docNumber: '', type: 'CNPJ', email: '', whatsapp: '' });
    } catch (error) {
        alert('Erro ao salvar empresa.');
    }
  };

  const handleOpenNewModal = () => {
      setEditingId(null);
      setNewCompany({ name: '', docNumber: '', type: 'CNPJ', email: '', whatsapp: '' });
      setIsModalOpen(true);
  };

  const handleImportClick = () => {
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1 });
      const rows = data.slice(1);

      let importedCount = 0;
      for (const row of rows) {
        if (row.length < 2) continue;
        const docNumberRaw = String(row[0] || '');
        const name = String(row[1] || '');
        const email = String(row[2] || '');
        const whatsapp = String(row[3] || '');
        let typeRaw = String(row[4] || '').toUpperCase().trim();
        let type: 'CNPJ' | 'CPF' | 'MEI' = 'CNPJ';
        if (typeRaw === 'MEI') type = 'MEI';
        else if (typeRaw === 'CPF') type = 'CPF';

        if (docNumberRaw && name) {
            try {
                await api.saveCompany({
                    name, docNumber: docNumberRaw, email, whatsapp, type
                });
                importedCount++;
            } catch (e) {
                console.error("Falha ao importar linha", row);
            }
        }
      }

      if (importedCount > 0) {
        alert(`${importedCount} empresas importadas com sucesso!`);
        loadCompanies();
      } else {
        alert("Nenhuma empresa válida encontrada no arquivo.");
      }

      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsBinaryString(file);
  };

  if (loading) {
      return <div className="flex justify-center items-center h-64"><Loader2 className="w-8 h-8 animate-spin text-blue-600" /></div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Empresas</h1>
          <p className="text-gray-500">Gerencie o cadastro de empresas e clientes.</p>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          {/* Hidden File Input */}
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept=".xlsx, .xls, .csv" 
            className="hidden" 
          />

          <button 
            onClick={handleImportClick}
            className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg hover:bg-gray-50 transition-colors flex items-center gap-2"
          >
            <Upload className="w-4 h-4" /> Importar Excel
          </button>
          <button 
            onClick={handleOpenNewModal}
            className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors"
          >
            <Plus className="w-4 h-4" /> Nova Empresa
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        {/* Filters */}
        <div className="p-4 border-b border-gray-100 flex gap-4">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input 
              type="text" 
              placeholder="Buscar por nome, CNPJ ou email..." 
              className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>
          <select className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
            <option value="">Todos os Tipos</option>
            <option value="CNPJ">CNPJ</option>
            <option value="MEI">MEI</option>
            <option value="CPF">CPF</option>
          </select>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 text-gray-600 font-medium">
              <tr>
                <th className="px-6 py-4">Tipo (Copiar)</th>
                <th className="px-6 py-4">Documento</th>
                <th className="px-6 py-4">Razão Social / Nome</th>
                <th className="px-6 py-4">Contato</th>
                <th className="px-6 py-4 text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {companies.map((company) => (
                <tr key={company.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4">
                     <button 
                      onClick={() => handleCopy(company.docNumber, company.id)}
                      className={`flex items-center gap-1 px-2 py-1 rounded border transition-colors text-xs font-medium
                        ${copiedId === company.id 
                            ? 'bg-green-100 text-green-700 border-green-200' 
                            : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                     >
                        {copiedId === company.id ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                        {copiedId === company.id ? 'Copiado!' : 'Copiar'}
                     </button>
                  </td>
                  <td className="px-6 py-4 font-mono text-gray-600">{company.docNumber}</td>
                   <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded bg-blue-100 text-blue-600 flex items-center justify-center">
                        {company.type === 'CPF' ? <User className="w-4 h-4" /> : <Building2 className="w-4 h-4" />}
