import { Company, Task, Document } from '../types';

const API_URL = '/api';

export const api = {
  // Companies
  getCompanies: async (): Promise<Company[]> => {
    const res = await fetch(`${API_URL}/companies`);
    if (!res.ok) throw new Error('Failed to fetch companies');
    return res.json();
  },

  saveCompany: async (company: Partial<Company>): Promise<{ success: boolean; id: number }> => {
    const res = await fetch(`${API_URL}/companies`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(company),
    });
    return res.json();
  },

  deleteCompany: async (id: number): Promise<void> => {
    await fetch(`${API_URL}/companies/${id}`, { method: 'DELETE' });
  },

  // Tasks (Kanban)
  getTasks: async (): Promise<Task[]> => {
    const res = await fetch(`${API_URL}/tasks`);
    if (!res.ok) throw new Error('Failed to fetch tasks');
    return res.json();
  },

  saveTask: async (task: Partial<Task>): Promise<{ success: boolean; id: number }> => {
    const res = await fetch(`${API_URL}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(task),
    });
    return res.json();
  },

  deleteTask: async (id: number): Promise<void> => {
    await fetch(`${API_URL}/tasks/${id}`, { method: 'DELETE' });
  },

  // Document Status
  getDocumentStatuses: async (competence: string): Promise<any[]> => {
    const res = await fetch(`${API_URL}/documents/status?competence=${competence}`);
    return res.json();
  },

  updateDocumentStatus: async (companyId: number, category: string, competence: string, status: string): Promise<void> => {
    await fetch(`${API_URL}/documents/status`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ companyId, category, competence, status }),
    });
  },

  // WhatsApp
  getWhatsAppStatus: async (): Promise<{ status: string; qr: string | null; info?: any }> => {
    const res = await fetch(`${API_URL}/whatsapp/status`);
    return res.json();
  },

  disconnectWhatsApp: async (): Promise<void> => {
    await fetch(`${API_URL}/whatsapp/disconnect`, { method: 'POST' });
  }
};

import React, { useState, useEffect } from 'react';
import { Plus, MoreHorizontal, Calendar, Flag, Trash, CheckSquare, X, Loader2 } from 'lucide-react';
import { Task, TaskStatus } from '../types';
import TaskModal from './TaskModal';
import { api } from '../services/api';

interface KanbanColumnProps { 
  title: string; 
  status: TaskStatus; 
  tasks: Task[];
  color: string;
  onMoveTask: (id: number, status: TaskStatus) => void;
  onEditTask: (task: Task) => void;
  activeMenu: string | null;
  onToggleMenu: (menu: string | null) => void;
  onClearColumn: (status: TaskStatus) => void;
  onEnableSelection: () => void;
  selectionMode: boolean;
  selectedTasks: number[];
  onToggleSelection: (id: number) => void;
}

const KanbanColumn: React.FC<KanbanColumnProps> = ({ 
  title, 
  status, 
  tasks, 
  color, 
  onMoveTask, 
  onEditTask,
  activeMenu,
  onToggleMenu,
  onClearColumn,
  onEnableSelection,
  selectionMode,
  selectedTasks,
  onToggleSelection
}) => {

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData("taskId");
    if (taskId) {
        onMoveTask(Number(taskId), status);
    }
  };

  const menuId = `menu-${status}`;

  return (
    <div 
        className="flex-1 min-w-[300px] bg-gray-100 rounded-xl p-4 flex flex-col h-full transition-colors"
        onDragOver={handleDragOver}
        onDrop={handleDrop}
    >
      <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 ${color} relative`}>
        <h3 className="font-bold text-gray-700 flex items-center gap-2">
          {title}
          <span className="bg-gray-200 text-gray-600 px-2 py-0.5 rounded-full text-xs">{tasks.length}</span>
        </h3>

        <div className="relative">
            <button 
                onClick={(e) => { e.stopPropagation(); onToggleMenu(activeMenu === menuId ? null : menuId); }}
                className="text-gray-400 hover:text-gray-600 p-1 rounded hover:bg-gray-200"
            >
                <MoreHorizontal className="w-5 h-5" />
            </button>

            {activeMenu === menuId && (
                <div className="absolute right-0 top-full mt-1 w-48 bg-white rounded-lg shadow-lg border border-gray-100 z-20 py-1 overflow-hidden">
                    <button 
                        onClick={() => { onEnableSelection(); onToggleMenu(null); }}
                        className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2"
                    >
                        <CheckSquare className="w-4 h-4" /> Selecionar Tarefas
                    </button>
                    <button 
                        onClick={() => { onClearColumn(status); onToggleMenu(null); }}
                        className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 flex items-center gap-2"
                    >
                        <Trash className="w-4 h-4" /> Limpar Coluna
                    </button>
                </div>
            )}
        </div>
      </div>

      <div className="space-y-3 overflow-y-auto flex-1 pr-1">
        {tasks.map(task => (
          <div 
            key={task.id} 
            draggable={!selectionMode}
            onDragStart={(e) => {
                e.dataTransfer.setData("taskId", String(task.id));
                e.dataTransfer.effectAllowed = "move";
            }}
            onClick={() => selectionMode ? onToggleSelection(task.id) : onEditTask(task)}
            className={`bg-white p-4 rounded-lg shadow-sm border hover:shadow-md transition-all cursor-pointer group relative
                ${selectionMode && selectedTasks.includes(task.id) ? 'border-blue-500 ring-1 ring-blue-500 bg-blue-50' : 'border-gray-200'}
                ${!selectionMode ? 'hover:-translate-y-1 active:cursor-grabbing' : ''}
            `}
          >
            {/* Selection Checkbox Overlay */}
            {selectionMode && (
                <div className="absolute top-3 right-3 z-10">
                    <div className={`w-5 h-5 rounded border flex items-center justify-center
                        ${selectedTasks.includes(task.id) ? 'bg-blue-600 border-blue-600' : 'bg-white border-gray-300'}
                    `}>
                        {selectedTasks.includes(task.id) && <CheckSquare className="w-3 h-3 text-white" />}
                    </div>
                </div>
            )}

            <div className="flex justify-between items-start mb-2">
              <span className={`w-8 h-1 rounded-full mb-2`} style={{ backgroundColor: task.color }}></span>
              {!selectionMode && (
                  <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                    {status !== TaskStatus.DONE && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); onMoveTask(task.id, TaskStatus.DONE); }}
                            className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded hover:bg-green-200"
                        >Done</button>
                    )}
                  </div>
              )}
            </div>

            <h4 className="font-semibold text-gray-800 mb-1">{task.title}</h4>
            <p className="text-sm text-gray-500 mb-3 line-clamp-2">{task.description}</p>

            <div className="flex items-center justify-between text-xs text-gray-400 border-t pt-3">
              <div className="flex items-center gap-2">
                {task.dueDate && (
                    <span className="flex items-center gap-1 text-red-400">
                        <Calendar className="w-3 h-3" /> {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                    </span>
                )}
              </div>
              <span className={`flex items-center gap-1 ${task.priority === 'alta' ? 'text-red-500 font-bold' : ''}`}>
                <Flag className="w-3 h-3" /> {task.priority}
              </span>
            </div>
          </div>
        ))}

        {tasks.length === 0 && (
            <div className="text-center py-8 border-2 border-dashed border-gray-200 rounded-lg text-gray-400 text-sm">
                Solte tarefas aqui
            </div>
        )}
      </div>

      {!selectionMode && (
          <button 
            onClick={() => onEditTask(null as any)}
            className="mt-3 w-full py-2 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:border-blue-400 hover:text-blue-500 transition-colors flex items-center justify-center gap-2"
          >
            <Plus className="w-4 h-4" /> Nova Tarefa
          </button>
      )}
    </div>
  );
};

const Kanban: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);

  // Menu & Selection State
  const [activeMenuColumn, setActiveMenuColumn] = useState<string | null>(null);
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedTasks, setSelectedTasks] = useState<number[]>([]);

  // Load Tasks
  const loadTasks = async () => {
    try {
      const data = await api.getTasks();
      setTasks(data);
    } catch (e) {
      console.error("Erro ao carregar tarefas", e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTasks();
  }, []);

  const moveTask = async (id: number, newStatus: TaskStatus) => {
    // Optimistic Update
    const originalTasks = [...tasks];
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: newStatus } : t));

    try {
      const task = tasks.find(t => t.id === id);
      if (task) {
         await api.saveTask({ ...task, status: newStatus });
      }
    } catch (e) {
      console.error("Falha ao mover tarefa", e);
      setTasks(originalTasks); // Revert
    }
  };

  const handleEditTask = (task: Task | null) => {
    setEditingTask(task);
    setIsModalOpen(true);
  };

  const handleSaveTask = async (task: Task) => {
    try {
      await api.saveTask(task);
      setIsModalOpen(false);
      loadTasks(); // Reload to get IDs/Updates
    } catch (e) {
      alert("Erro ao salvar tarefa");
    }
  };

  const handleDeleteTask = async (taskId: number) => {
    try {
      await api.deleteTask(taskId);
      setTasks(prev => prev.filter(t => t.id !== taskId));
    } catch (e) {
      alert("Erro ao excluir tarefa");
    }
  };

  // Bulk Actions
  const handleClearColumn = async (status: TaskStatus) => {
      if(window.confirm(`Tem certeza que deseja excluir TODAS as tarefas da coluna "${status}"?`)) {
          const tasksToDelete = tasks.filter(t => t.status === status);
          for (const t of tasksToDelete) {
             await api.deleteTask(t.id);
          }
          loadTasks();
      }
  };

  const handleToggleSelection = (id: number) => {
      setSelectedTasks(prev => 
        prev.includes(id) ? prev.filter(tid => tid !== id) : [...prev, id]
      );
  };

  const handleBulkDelete = async () => {
      if(selectedTasks.length === 0) return;
      if(window.confirm(`Excluir as ${selectedTasks.length} tarefas selecionadas?`)) {
          for (const id of selectedTasks) {
             await api.deleteTask(id);
          }
          setSelectedTasks([]);
          setSelectionMode(false);
          loadTasks();
      }
  };

  const handleCancelSelection = () => {
      setSelectionMode(false);
      setSelectedTasks([]);
  };

  if (loading) {
     return <div className="h-[800px] flex items-center justify-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600" /></div>;
  }

  return (
    <div className="h-[800px] flex flex-col relative" onClick={() => setActiveMenuColumn(null)}>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Gerenciador de Tarefas</h1>
          <p className="text-gray-500">Acompanhe o progresso das obrigações contábeis.</p>
        </div>
        <div className="flex gap-3">
          <select className="bg-white border border-gray-300 rounded-lg px-4 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
            <option>Todas as Empresas</option>
            {/* Can populate dynamically if needed */}
          </select>
          <button 
            onClick={() => handleEditTask(null)}
            className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors"
          >
            <Plus className="w-4 h-4" /> Nova Tarefa
          </button>
        </div>
      </div>

      <div className="flex gap-6 overflow-x-auto pb-4 h-full">
        <KanbanColumn 
          title="Pendente" 
          status={TaskStatus.PENDING} 
          tasks={tasks.filter(t => t.status === TaskStatus.PENDING)}
          color="border-yellow-400"
          onMoveTask={moveTask}
          onEditTask={handleEditTask}
          activeMenu={activeMenuColumn}
          onToggleMenu={setActiveMenuColumn}
          onClearColumn={handleClearColumn}
          onEnableSelection={() => setSelectionMode(true)}
          selectionMode={selectionMode}
          selectedTasks={selectedTasks}
          onToggleSelection={handleToggleSelection}
        />
        <KanbanColumn 
          title="Em Andamento" 
          status={TaskStatus.IN_PROGRESS} 
          tasks={tasks.filter(t => t.status === TaskStatus.IN_PROGRESS)}
          color="border-blue-400"
          onMoveTask={moveTask}
          onEditTask={handleEditTask}
          activeMenu={activeMenuColumn}
          onToggleMenu={setActiveMenuColumn}
          onClearColumn={handleClearColumn}
          onEnableSelection={() => setSelectionMode(true)}
          selectionMode={selectionMode}
          selectedTasks={selectedTasks}
          onToggleSelection={handleToggleSelection}
        />
        <KanbanColumn 
          title="Concluída" 
          status={TaskStatus.DONE} 
          tasks={tasks.filter(t => t.status === TaskStatus.DONE)}
          color="border-green-400"
          onMoveTask={moveTask}
          onEditTask={handleEditTask}
          activeMenu={activeMenuColumn}
          onToggleMenu={setActiveMenuColumn}
          onClearColumn={handleClearColumn}
          onEnableSelection={() => setSelectionMode(true)}
          selectionMode={selectionMode}
          selectedTasks={selectedTasks}
          onToggleSelection={handleToggleSelection}
        />
      </div>

      <TaskModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        task={editingTask} 
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
      />

      {/* Bulk Action Bar */}
      {selectionMode && (
          <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-gray-900 text-white px-6 py-3 rounded-xl shadow-xl flex items-center gap-6 z-30 animate-in slide-in-from-bottom-5">
              <span className="font-semibold">{selectedTasks.length} tarefas selecionadas</span>
              <div className="h-4 w-px bg-gray-600"></div>
              <button 
                onClick={handleBulkDelete}
                disabled={selectedTasks.length === 0}
                className="flex items-center gap-2 text-red-400 hover:text-red-300 disabled:opacity-50"
              >
                  <Trash className="w-4 h-4" /> Excluir Selecionadas
              </button>
              <button 
                onClick={handleCancelSelection}
                className="text-gray-400 hover:text-white"
              >
                  <X className="w-5 h-5" />
              </button>
          </div>
      )}
    </div>
  );
};

export default Kanban;

import 'dotenv/config';
import express from 'express';
import { createRequire } from 'module';
const require = createRequire(import.meta.url);
import path from 'path';
import { fileURLToPath } from 'url';
import cors from 'cors';
import pkg from 'whatsapp-web.js';
const { Client, LocalAuth } = pkg;
import QRCode from 'qrcode';
import fs from 'fs';
import sqlite3 from 'sqlite3';
import { v4 as uuidv4 } from 'uuid';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const port = process.env.PORT || 3000;

// Configuração de diretórios para persistência no Docker
const DATA_DIR = process.env.DATA_PATH || path.join(__dirname, 'data');
const UPLOADS_DIR = path.join(DATA_DIR, 'uploads');
const AUTH_DIR = path.join(DATA_DIR, 'whatsapp_auth');
const DB_PATH = path.join(DATA_DIR, 'consultas.db');

// Garantir que diretórios existam
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
if (!fs.existsSync(UPLOADS_DIR)) fs.mkdirSync(UPLOADS_DIR, { recursive: true });
if (!fs.existsSync(AUTH_DIR)) fs.mkdirSync(AUTH_DIR, { recursive: true });

const db = new sqlite3.Database(DB_PATH);

db.serialize(() => {
  // Tabelas Originais do seu sistema de Prospecção
  db.run(`CREATE TABLE IF NOT EXISTS consulta (
    id TEXT PRIMARY KEY,
    filename TEXT,
    total INTEGER,
    processed INTEGER,
    status TEXT,
    start_time TEXT,
    end_time TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS campaign (
    id TEXT PRIMARY KEY,
    name TEXT,
    description TEXT,
    initial_message TEXT,
    ai_persona TEXT,
    status TEXT,
    created_at TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS resultado (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    consulta_id TEXT,
    campaign_id TEXT,
    inscricao_estadual TEXT,
    cnpj TEXT,
    razao_social TEXT,
    nome_fantasia TEXT,
    unidade_fiscalizacao TEXT,
    logradouro TEXT,
    bairro_distrito TEXT,
    municipio TEXT,
    uf TEXT,
    cep TEXT,
    telefone TEXT,
    wa_id TEXT,
    email TEXT,
    atividade_economica_principal TEXT,
    condicao TEXT,
    forma_pagamento TEXT,
    situacao_cadastral TEXT,
    data_situacao_cadastral TEXT,
    motivo_situacao_cadastral TEXT,
    nome_contador TEXT,
    status TEXT,
    campaign_status TEXT DEFAULT 'pending',
    last_contacted TEXT,
    ai_active INTEGER DEFAULT 1, 
    FOREIGN KEY(consulta_id) REFERENCES consulta(id),
    FOREIGN KEY(campaign_id) REFERENCES campaign(id)
  )`);

  // --- NOVAS TABELAS PARA O CONTÁBIL MANAGER PRO ---

  // Tabela de Empresas (Cadastro fixo do sistema)
  db.run(`CREATE TABLE IF NOT EXISTS companies (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    docNumber TEXT,
    type TEXT,
    email TEXT,
    whatsapp TEXT
  )`);

  // Tabela de Tarefas (Kanban)
  db.run(`CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    status TEXT,
    priority TEXT,
    color TEXT,
    dueDate TEXT,
    companyId INTEGER,
    recurrence TEXT,
    dayOfWeek TEXT,
    recurrenceDate TEXT,
    targetCompanyType TEXT
  )`);

  // Tabela de Status dos Documentos (Matriz)
  db.run(`CREATE TABLE IF NOT EXISTS document_status (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    companyId INTEGER,
    category TEXT,
    competence TEXT,
    status TEXT,
    UNIQUE(companyId, category, competence)
  )`);
});

// --- SISTEMA DE LOGS EM MEMÓRIA (RAM) ---
const memoryLogs = [];

function logSystem(type, source, message, meta = {}) {
    const timestamp = new Date().toISOString();
    console.log(`[${type.toUpperCase()}] ${message}`);

    memoryLogs.unshift({
        id: uuidv4(),
        timestamp,
        type,
        source,
        message,
        meta: JSON.stringify(meta)
    });

    if (memoryLogs.length > 200) {
        memoryLogs.pop();
    }
}

// Configuração do Cliente WhatsApp para Docker (Puppeteer)
// Importante: No Docker precisamos apontar para o executável do Chromium instalado
const client = new Client({
  authStrategy: new LocalAuth({ dataPath: AUTH_DIR }),
  puppeteer: {
    headless: true,
    executablePath: process.env.PUPPETEER_EXECUTABLE_PATH || undefined,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-accelerated-2d-canvas',
      '--no-first-run',
      '--no-zygote',
      '--disable-gpu'
    ],
  },
  webVersionCache: {
    type: "remote",
    remotePath: "https://raw.githubusercontent.com/wppconnect-team/wa-version/main/html/2.2412.54.html",
  }
});

let qrCodeData = null;
let clientReady = false;

client.on('qr', (qr) => {
    QRCode.toDataURL(qr, (err, url) => {
        qrCodeData = url;
        logSystem('info', 'whatsapp', 'Novo QR Code gerado');
    });
});

client.on('ready', () => { 
    clientReady = true; 
    qrCodeData = null; // Clear QR code on success
    logSystem('info', 'whatsapp', 'Cliente WhatsApp conectado e pronto'); 
});

client.on('disconnected', () => {
    clientReady = false;
    logSystem('warning', 'whatsapp', 'Cliente WhatsApp desconectado');
});

client.initialize().catch((err) => {
    console.error("Erro ao inicializar WhatsApp:", err);
});

app.use(cors());
app.use(express.json());
// Serve static files from React build
app.use(express.static(path.join(__dirname, 'dist'))); 

// --- API ENDPOINTS PARA O CONTÁBIL MANAGER PRO ---

// 1. Empresas (CRUD)
app.get('/api/companies', (req, res) => {
    db.all('SELECT * FROM companies ORDER BY name ASC', (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json(rows);
    });
});

app.post('/api/companies', (req, res) => {
    const { id, name, docNumber, type, email, whatsapp } = req.body;

    if (id) {
        // Update
        const sql = `UPDATE companies SET name = ?, docNumber = ?, type = ?, email = ?, whatsapp = ? WHERE id = ?`;
        db.run(sql, [name, docNumber, type, email, whatsapp, id], function(err) {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id });
        });
    } else {
        // Create
        const sql = `INSERT INTO companies (name, docNumber, type, email, whatsapp) VALUES (?, ?, ?, ?, ?)`;
        db.run(sql, [name, docNumber, type, email, whatsapp], function(err) {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id: this.lastID });
        });
    }
});

app.delete('/api/companies/:id', (req, res) => {
    db.run('DELETE FROM companies WHERE id = ?', [req.params.id], (err) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
    });
});

// 2. Tarefas (CRUD)
app.get('/api/tasks', (req, res) => {
    db.all('SELECT * FROM tasks', (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json(rows);
    });
});

app.post('/api/tasks', (req, res) => {
    const task = req.body;

    // Check if ID is a valid database ID (integer) or needs insertion
    if (task.id && typeof task.id === 'number' && task.id < 1000000000000) { 
         const sql = `UPDATE tasks SET title=?, description=?, status=?, priority=?, color=?, dueDate=?, companyId=?, recurrence=?, dayOfWeek=?, recurrenceDate=?, targetCompanyType=? WHERE id=?`;
         db.run(sql, [task.title, task.description, task.status, task.priority, task.color, task.dueDate, task.companyId, task.recurrence, task.dayOfWeek, task.recurrenceDate, task.targetCompanyType, task.id], function(err) {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id: task.id });
         });
    } else {
         const sql = `INSERT INTO tasks (title, description, status, priority, color, dueDate, companyId, recurrence, dayOfWeek, recurrenceDate, targetCompanyType) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
         db.run(sql, [task.title, task.description, task.status, task.priority, task.color, task.dueDate, task.companyId, task.recurrence, task.dayOfWeek, task.recurrenceDate, task.targetCompanyType], function(err) {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id: this.lastID });
         });
    }
});

app.delete('/api/tasks/:id', (req, res) => {
    db.run('DELETE FROM tasks WHERE id = ?', [req.params.id], (err) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
    });
});

// 3. Status de Documentos (Matriz)
app.get('/api/documents/status', (req, res) => {
    const { competence } = req.query;
    let sql = 'SELECT * FROM document_status';
    const params = [];

    if (competence) {
        sql += ' WHERE competence = ?';
        params.push(competence);
    }

    db.all(sql, params, (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json(rows);
    });
});

app.post('/api/documents/status', (req, res) => {
    const { companyId, category, competence, status } = req.body;
    const sql = `INSERT INTO document_status (companyId, category, competence, status) 
                 VALUES (?, ?, ?, ?) 
                 ON CONFLICT(companyId, category, competence) 
                 DO UPDATE SET status = excluded.status`;

    db.run(sql, [companyId, category, competence, status], (err) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
    });
});

// 4. WhatsApp Status (Expor QR Code Real)
app.get('/api/whatsapp/status', (req, res) => {
    res.json({ 
        status: clientReady ? 'connected' : 'disconnected', 
        qr: qrCodeData,
        info: clientReady && client.info ? {
            pushname: client.info.pushname,
            wid: client.info.wid,
            platform: client.info.platform
        } : null
    });
});

app.post('/api/whatsapp/disconnect', async (req, res) => {
    try {
        await client.logout();
        await client.initialize(); // Restart to generate new QR
        res.json({ success: true });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

app.get('/api/logs', (req, res) => res.json(memoryLogs));

// Handle React Routing - serve index.html for unknown routes
app.get('*', (req, res) => {
    if (!req.path.startsWith('/api')) {
        res.sendFile(path.join(__dirname, 'dist', 'index.html'));
    }
});

app.listen(port, () => console.log(`Server running at http://localhost:${port}`));

