const require = createRequire(import.meta.url);
import path from 'path';
import { fileURLToPath } from 'url';
import cors from 'cors';
import pkg from 'whatsapp-web.js';
const { Client, LocalAuth } = pkg;
import QRCode from 'qrcode';
import fs from 'fs';
import sqlite3 from 'sqlite3';
import { v4 as uuidv4 } from 'uuid';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const port = process.env.PORT || 3000;

// Configuração de diretórios para persistência no Docker
const DATA_DIR = process.env.DATA_PATH || path.join(__dirname, 'data');
const UPLOADS_DIR = path.join(DATA_DIR, 'uploads');
const AUTH_DIR = path.join(DATA_DIR, 'whatsapp_auth');
const DB_PATH = path.join(DATA_DIR, 'consultas.db');

console.log(`[INIT] Diretório de Dados: ${DATA_DIR}`);
console.log(`[INIT] Banco de Dados: ${DB_PATH}`);

// Garantir que diretórios existam
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
if (!fs.existsSync(UPLOADS_DIR)) fs.mkdirSync(UPLOADS_DIR, { recursive: true });
if (!fs.existsSync(AUTH_DIR)) fs.mkdirSync(AUTH_DIR, { recursive: true });

const db = new sqlite3.Database(DB_PATH);

db.serialize(() => {
  // Tabelas Originais do seu sistema de Prospecção
  db.run(`CREATE TABLE IF NOT EXISTS consulta (
    id TEXT PRIMARY KEY,
    filename TEXT,
    total INTEGER,
    processed INTEGER,
    status TEXT,
    start_time TEXT,
    end_time TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS campaign (
    id TEXT PRIMARY KEY,
    name TEXT,
    description TEXT,
    initial_message TEXT,
    ai_persona TEXT,
    status TEXT,
    created_at TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS resultado (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    consulta_id TEXT,
    campaign_id TEXT,
    inscricao_estadual TEXT,
    cnpj TEXT,
    razao_social TEXT,
    nome_fantasia TEXT,
    unidade_fiscalizacao TEXT,
    logradouro TEXT,
    bairro_distrito TEXT,
    municipio TEXT,
    uf TEXT,
    cep TEXT,
    telefone TEXT,
    wa_id TEXT,
    email TEXT,
    atividade_economica_principal TEXT,
    condicao TEXT,
    forma_pagamento TEXT,
    situacao_cadastral TEXT,
    data_situacao_cadastral TEXT,
    motivo_situacao_cadastral TEXT,
    nome_contador TEXT,
    status TEXT,
    campaign_status TEXT DEFAULT 'pending',
    last_contacted TEXT,
    ai_active INTEGER DEFAULT 1, 
    FOREIGN KEY(consulta_id) REFERENCES consulta(id),
    FOREIGN KEY(campaign_id) REFERENCES campaign(id)
  )`);

  // --- NOVAS TABELAS PARA O CONTÁBIL MANAGER PRO ---

  // Tabela de Empresas (Cadastro fixo do sistema)
  db.run(`CREATE TABLE IF NOT EXISTS companies (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    docNumber TEXT,
    type TEXT,
    email TEXT,
    whatsapp TEXT
  )`);

  // Tabela de Tarefas (Kanban)
  db.run(`CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    status TEXT,
    priority TEXT,
    color TEXT,
    dueDate TEXT,
    companyId INTEGER,
    recurrence TEXT,
    dayOfWeek TEXT,
    recurrenceDate TEXT,
    targetCompanyType TEXT
  )`);

  // Tabela de Status dos Documentos (Matriz)
  db.run(`CREATE TABLE IF NOT EXISTS document_status (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    companyId INTEGER,
    category TEXT,
    competence TEXT,
    status TEXT,
    UNIQUE(companyId, category, competence)
  )`);
});

// --- SISTEMA DE LOGS EM MEMÓRIA (RAM) ---
const memoryLogs = [];

function logSystem(type, source, message, meta = {}) {
    const timestamp = new Date().toISOString();
    console.log(`[${type.toUpperCase()}] ${message}`);

    memoryLogs.unshift({
        id: uuidv4(),
        timestamp,
        type,
        source,
        message,
        meta: JSON.stringify(meta)
    });

    if (memoryLogs.length > 200) {
        memoryLogs.pop();
    }
}

// Configuração do Cliente WhatsApp para Docker (Puppeteer)
// Importante: No Docker precisamos apontar para o executável do Chromium instalado
const puppeteerExecutablePath = process.env.PUPPETEER_EXECUTABLE_PATH || undefined;
console.log(`[INIT] Puppeteer Executable Path: ${puppeteerExecutablePath || 'Padrão (Local)'}`);

const client = new Client({
  authStrategy: new LocalAuth({ dataPath: AUTH_DIR }),
  puppeteer: {
    headless: true,
    executablePath: puppeteerExecutablePath,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-accelerated-2d-canvas',
      '--no-first-run',
      '--no-zygote',
      '--disable-gpu'
    ],
  },
  webVersionCache: {
    type: "remote",
    remotePath: "https://raw.githubusercontent.com/wppconnect-team/wa-version/main/html/2.2412.54.html",
  }
});

let qrCodeData = null;
let clientReady = false;

client.on('qr', (qr) => {
    QRCode.toDataURL(qr, (err, url) => {
        qrCodeData = url;
        logSystem('info', 'whatsapp', 'Novo QR Code gerado');
    });
});

client.on('ready', () => { 
    clientReady = true; 
    qrCodeData = null; // Clear QR code on success
    logSystem('info', 'whatsapp', 'Cliente WhatsApp conectado e pronto'); 
});

client.on('disconnected', () => {
    clientReady = false;
    logSystem('warning', 'whatsapp', 'Cliente WhatsApp desconectado');
});

client.initialize().catch((err) => {
    console.error("Erro ao inicializar WhatsApp:", err);
});

app.use(cors());
app.use(express.json());
// Serve static files from React build
app.use(express.static(path.join(__dirname, 'dist'))); 

// --- API ENDPOINTS PARA O CONTÁBIL MANAGER PRO ---

// 1. Empresas (CRUD)
app.get('/api/companies', (req, res) => {
    db.all('SELECT * FROM companies ORDER BY name ASC', (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json(rows);
    });
});

app.post('/api/companies', (req, res) => {
    const { id, name, docNumber, type, email, whatsapp } = req.body;

    if (id) {
        // Update
        const sql = `UPDATE companies SET name = ?, docNumber = ?, type = ?, email = ?, whatsapp = ? WHERE id = ?`;
        db.run(sql, [name, docNumber, type, email, whatsapp, id], function(err) {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id });
        });
    } else {
        // Create
        const sql = `INSERT INTO companies (name, docNumber, type, email, whatsapp) VALUES (?, ?, ?, ?, ?)`;
        db.run(sql, [name, docNumber, type, email, whatsapp], function(err) {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id: this.lastID });
        });
    }
});

app.delete('/api/companies/:id', (req, res) => {
    db.run('DELETE FROM companies WHERE id = ?', [req.params.id], (err) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
    });
});

// 2. Tarefas (CRUD)
app.get('/api/tasks', (req, res) => {
    db.all('SELECT * FROM tasks', (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json(rows);
    });
});

app.post('/api/tasks', (req, res) => {
    const task = req.body;

    // Check if ID is a valid database ID (integer) or needs insertion
    if (task.id && typeof task.id === 'number' && task.id < 1000000000000) { 
         const sql = `UPDATE tasks SET title=?, description=?, status=?, priority=?, color=?, dueDate=?, companyId=?, recurrence=?, dayOfWeek=?, recurrenceDate=?, targetCompanyType=? WHERE id=?`;
         db.run(sql, [task.title, task.description, task.status, task.priority, task.color, task.dueDate, task.companyId, task.recurrence, task.dayOfWeek, task.recurrenceDate, task.targetCompanyType, task.id], function(err) {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id: task.id });
         });
    } else {
         const sql = `INSERT INTO tasks (title, description, status, priority, color, dueDate, companyId, recurrence, dayOfWeek, recurrenceDate, targetCompanyType) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
         db.run(sql, [task.title, task.description, task.status, task.priority, task.color, task.dueDate, task.companyId, task.recurrence, task.dayOfWeek, task.recurrenceDate, task.targetCompanyType], function(err) {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id: this.lastID });
         });
    }
});

app.delete('/api/tasks/:id', (req, res) => {
    db.run('DELETE FROM tasks WHERE id = ?', [req.params.id], (err) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
    });
});

// 3. Status de Documentos (Matriz)
app.get('/api/documents/status', (req, res) => {
    const { competence } = req.query;
    let sql = 'SELECT * FROM document_status';
    const params = [];

    if (competence) {
        sql += ' WHERE competence = ?';
        params.push(competence);
    }

    db.all(sql, params, (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json(rows);
    });
});

app.post('/api/documents/status', (req, res) => {
    const { companyId, category, competence, status } = req.body;
    const sql = `INSERT INTO document_status (companyId, category, competence, status) 
                 VALUES (?, ?, ?, ?) 
                 ON CONFLICT(companyId, category, competence) 
                 DO UPDATE SET status = excluded.status`;

    db.run(sql, [companyId, category, competence, status], (err) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
    });
});

// 4. WhatsApp Status (Expor QR Code Real)
app.get('/api/whatsapp/status', (req, res) => {
    res.json({ 
        status: clientReady ? 'connected' : 'disconnected', 
        qr: qrCodeData,
        info: clientReady && client.info ? {
            pushname: client.info.pushname,
            wid: client.info.wid,
            platform: client.info.platform
        } : null
    });
});

app.post('/api/whatsapp/disconnect', async (req, res) => {
    try {
        await client.logout();
        await client.initialize(); // Restart to generate new QR
        res.json({ success: true });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

app.get('/api/logs', (req, res) => res.json(memoryLogs));

// Handle React Routing - serve index.html for unknown routes
app.get('*', (req, res) => {
    if (!req.path.startsWith('/api')) {
        res.sendFile(path.join(__dirname, 'dist', 'index.html'));
    }
});

app.listen(port, () => console.log(`Server running at http://localhost:${port}`));

import React, { useState } from 'react';
import { Send as SendIcon, Mail, MessageCircle, FileText, Trash, Clock, Check, Info, ArrowLeft, X, CheckSquare, Calendar } from 'lucide-react';
import { Document, Company } from '../types';
import { MOCK_COMPANIES } from '../constants';

interface SendProps {
  documents: Document[];
  onSendDocuments: (ids: number[]) => void;
  onNavigateToDocuments: () => void;
}

const Send: React.FC<SendProps> = ({ documents, onSendDocuments, onNavigateToDocuments }) => {
  const [competence, setCompetence] = useState('09/2023');
  const [subject, setSubject] = useState('Folha de Pagamento');
  const [message, setMessage] = useState('Segue em anexo os seguintes documentos:');

  // Instant Send State
  const [sendEmail, setSendEmail] = useState(true);
  const [sendWhatsapp, setSendWhatsapp] = useState(false);

  // Selection State
  const [selectedDocs, setSelectedDocs] = useState<number[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  // Scheduling State
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');
  const [scheduleChannels, setScheduleChannels] = useState({ email: true, whatsapp: false });

  // Filter documents: pending AND matches competence
  const pendingDocs = documents.filter(doc => 
    doc.status === 'pending' && 
    doc.competence === competence
  );

  // Group by Company
  const docsByCompany = pendingDocs.reduce((acc, doc) => {
    if (!acc[doc.companyId]) {
      acc[doc.companyId] = [];
    }
    acc[doc.companyId].push(doc);
    return acc;
  }, {} as Record<number, Document[]>);

  const getCompanyDetails = (id: number) => MOCK_COMPANIES.find(c => c.id === id);

  const toggleDocSelection = (id: number) => {
    setSelectedDocs(prev => 
      prev.includes(id) ? prev.filter(d => d !== id) : [...prev, id]
    );
  };

  const toggleCompanySelection = (companyId: number, companyDocs: Document[]) => {
    const allSelected = companyDocs.every(d => selectedDocs.includes(d.id));
    if (allSelected) {
      // Deselect all for this company
      const idsToRemove = companyDocs.map(d => d.id);
      setSelectedDocs(prev => prev.filter(id => !idsToRemove.includes(id)));
    } else {
      // Select all for this company
      const idsToAdd = companyDocs.map(d => d.id);
      setSelectedDocs(prev => [...new Set([...prev, ...idsToAdd])]);
    }
  };

  const toggleSelectGlobal = () => {
      const allPendingIds = pendingDocs.map(d => d.id);
      const allSelected = allPendingIds.length > 0 && allPendingIds.every(id => selectedDocs.includes(id));

      if (allSelected) {
          setSelectedDocs([]);
      } else {
          setSelectedDocs(allPendingIds);
      }
  };

  const handleSend = () => {
    if (selectedDocs.length === 0) {
      alert('Selecione pelo menos um documento para enviar.');
      return;
    }
    if (!sendEmail && !sendWhatsapp) {
      alert('Selecione pelo menos um método de envio (E-mail ou WhatsApp).');
      return;
    }

    setIsProcessing(true);
    setTimeout(() => {
      onSendDocuments(selectedDocs);
      setIsProcessing(false);
      setSelectedDocs([]);
      alert('Documentos enviados com sucesso!');
    }, 1500);
  };

  const handleOpenSchedule = () => {
     if (selectedDocs.length === 0) {
      alert('Selecione pelo menos um documento para agendar.');
      return;
    }
    // Initialize modal state
    setScheduleChannels({ email: sendEmail, whatsapp: sendWhatsapp });
    setShowScheduleModal(true);
  };

  const confirmSchedule = () => {
      if (!scheduleDate) {
          alert("Por favor, selecione uma data e hora.");
          return;
      }
      if (!scheduleChannels.email && !scheduleChannels.whatsapp) {
          alert("Selecione pelo menos um canal de envio.");
          return;
      }

      setShowScheduleModal(false);

      // Simulate Backend Schedule Creation
      console.log("Agendamento Criado:", {
          documents: selectedDocs,
          date: scheduleDate,
          channels: scheduleChannels,
          smtpUser: "EMAIL_USER_ENV_VAR", // Simulated
          smtpPass: "EMAIL_PASS_ENV_VAR"  // Simulated
      });

      alert(`Agendamento realizado com sucesso para ${scheduleDate}!`);
      setSelectedDocs([]);
      setScheduleDate('');
  }

  const allPendingIds = pendingDocs.map(d => d.id);
  const isGlobalSelected = allPendingIds.length > 0 && allPendingIds.every(id => selectedDocs.includes(id));

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
            <SendIcon className="w-6 h-6 text-blue-600" /> Envio de Documentos
            <span className="text-base font-normal text-gray-500">- Competência: {competence}</span>
        </h2>
      </div>

      <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-lg flex items-center gap-2">
         <MessageCircle className="w-5 h-5" /> 
         Status WhatsApp: <span className="text-green-600 font-bold">Conectado</span>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
         <div className="bg-gray-50 p-4 border-b border-gray-100">
             <h5 className="font-bold text-gray-700 flex items-center gap-2">
                 <Mail className="w-5 h-5" /> Configuração do Envio
             </h5>
         </div>
         <div className="p-6">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-4">
                 <div>
                     <label className="block text-sm font-semibold text-gray-700 mb-1">Assunto do E-mail*</label>
                     <div className="flex">
                         <span className="px-3 bg-gray-100 border border-r-0 border-gray-300 rounded-l-lg flex items-center text-gray-500">
                             <Check className="w-4 h-4" />
                         </span>
                         <input 
                            type="text" 
                            className="w-full border border-gray-300 rounded-r-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                            value={subject}
                            onChange={(e) => setSubject(e.target.value)}
                         />
                     </div>
                 </div>
                 <div>
                     <label className="block text-sm font-semibold text-gray-700 mb-1">Competência</label>
                     <div className="flex">
                         <span className="px-3 bg-gray-100 border border-r-0 border-gray-300 rounded-l-lg flex items-center text-gray-500">
                             <Clock className="w-4 h-4" />
                         </span>
                         <input 
                            type="text" 
                            className="w-full border border-gray-300 rounded-r-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                            value={competence}
                            onChange={(e) => {
                                let val = e.target.value.replace(/\D/g, '');
                                if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                                setCompetence(val);
                            }}
                         />
                     </div>
                 </div>
             </div>
             <div>
                 <label className="block text-sm font-semibold text-gray-700 mb-1">Mensagem*</label>
                 <textarea 
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 h-24 outline-none focus:ring-2 focus:ring-blue-500"
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                 />
             </div>
         </div>
      </div>

      <div className="mb-4">
          <div className="flex justify-between items-center border-b pb-2 mb-4">
              <h4 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                  <FileText className="w-6 h-6 text-blue-600" /> Documentos Pendentes
              </h4>
              {pendingDocs.length > 0 && (
                  <button 
                    onClick={toggleSelectGlobal}
                    className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors
                        ${isGlobalSelected ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
                  >
                      <CheckSquare className="w-4 h-4" />
                      {isGlobalSelected ? 'Desmarcar Todos' : 'Selecionar Todos (Geral)'}
                  </button>
              )}
          </div>

          {Object.keys(docsByCompany).length === 0 ? (
              <div className="bg-blue-50 text-blue-700 p-4 rounded-lg flex items-center gap-2">
                  <Info className="w-5 h-5" /> Não há documentos pendentes para envio nesta competência.
                  <button onClick={onNavigateToDocuments} className="font-bold hover:underline">Voltar</button>
              </div>
          ) : (
              Object.entries(docsByCompany).map(([companyIdStr, companyDocsRaw]) => {
                  const companyId = Number(companyIdStr);
                  const companyDocs = companyDocsRaw as Document[];
                  const company = getCompanyDetails(companyId);
                  const allSelected = companyDocs.every(d => selectedDocs.includes(d.id));

                  return (
                      <div key={companyId} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden mb-4">
                          <div className="bg-blue-600 text-white p-4 flex justify-between items-center">
                              <div>
                                  <h5 className="font-bold text-lg">{company?.name || 'Empresa Desconhecida'}</h5>
                                  <div className="text-sm opacity-90 flex gap-3">
                                      <span className="flex items-center gap-1"><Mail className="w-3 h-3" /> {company?.email}</span>
                                      <span className="flex items-center gap-1"><MessageCircle className="w-3 h-3" /> {company?.whatsapp}</span>
                                  </div>
                              </div>
                              <label className="flex items-center gap-2 cursor-pointer bg-blue-700 px-3 py-1 rounded hover:bg-blue-800 transition-colors">
                                  <input 
                                    type="checkbox" 
                                    className="rounded text-blue-600 w-4 h-4"
                                    checked={allSelected}
                                    onChange={() => toggleCompanySelection(companyId, companyDocs)}
                                  />
                                  <span className="text-sm font-medium">Selecionar todos</span>
                              </label>
                          </div>
                          <div className="p-0">
                              <table className="w-full text-sm">
                                  <thead className="bg-gray-50 text-gray-600">
                                      <tr>
                                          <th className="px-4 py-3 w-10">
                                              {/* Toggle All Placeholder */}
                                          </th>
                                          <th className="px-4 py-3 text-left">Documento</th>
                                          <th className="px-4 py-3 text-left">Categoria</th>
                                          <th className="px-4 py-3 text-left">Vencimento</th>
                                          <th className="px-4 py-3 text-center">Status</th>
                                          <th className="px-4 py-3 text-center">Ações</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100">
                                      {companyDocs.map(doc => (
                                          <tr key={doc.id} className="hover:bg-gray-50 transition-colors">
                                              <td className="px-4 py-3 text-center">
                                                  <input 
                                                    type="checkbox" 
                                                    className="rounded text-blue-600 w-4 h-4"
                                                    checked={selectedDocs.includes(doc.id)}
                                                    onChange={() => toggleDocSelection(doc.id)}
                                                  />
                                              </td>
                                              <td className="px-4 py-3 font-medium text-gray-800 flex items-center gap-2">
                                                  <FileText className="w-4 h-4 text-blue-500" />
                                                  {doc.name || 'Sem nome'}
                                              </td>
                                              <td className="px-4 py-3">
                                                  <span className="px-2 py-1 bg-gray-100 rounded text-xs text-gray-600 font-medium">
                                                      {doc.category}
                                                  </span>
                                              </td>
                                              <td className="px-4 py-3 text-gray-600">
                                                  {doc.dueDate ? <span className="bg-gray-50 px-2 py-1 rounded border">{doc.dueDate}</span> : <span className="text-gray-400">Não informado</span>}
                                              </td>
                                              <td className="px-4 py-3 text-center">
                                                  <span className="bg-yellow-100 text-yellow-700 px-2 py-1 rounded text-xs font-bold uppercase">
                                                      Pendente
                                                  </span>
                                              </td>
                                              <td className="px-4 py-3 text-center">
                                                  <button className="text-red-500 hover:bg-red-50 p-1 rounded transition-colors" title="Remover">
                                                      <Trash className="w-4 h-4" />
                                                  </button>
                                              </td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      </div>
                  );
              })
          )}
      </div>

      {Object.keys(docsByCompany).length > 0 && (
          <>
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden mb-4">
                <div className="bg-gray-50 p-4 border-b border-gray-100">
                    <h5 className="font-bold text-gray-700 flex items-center gap-2">
                        <SendIcon className="w-5 h-5" /> Opções de Envio Imediato
                    </h5>
                </div>
                <div className="p-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <label className="flex items-center gap-3 p-3 border rounded-lg cursor-pointer hover:bg-gray-50 transition-colors">
                            <input 
                                type="checkbox" 
