import React, { useState, useEffect } from 'react';
import { Upload as UploadIcon, X, FileText, Calendar, AlertCircle, Loader2 } from 'lucide-react';
import { DOCUMENT_CATEGORIES } from '../constants';
import { calcularTodosVencimentos } from '../utils/dateHelpers';
import { UploadedFile, Company } from '../types';
import { api } from '../services/api';

interface UploadProps {
  preFillData?: {
    companyId: number;
    competence: string;
  } | null;
  onUploadSuccess: (files: UploadedFile[], companyId: number, competence: string) => void;
}

const Upload: React.FC<UploadProps> = ({ preFillData, onUploadSuccess }) => {
  const [competence, setCompetence] = useState('');
  const [selectedCompanyId, setSelectedCompanyId] = useState<number | string>('');
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [calculatedDates, setCalculatedDates] = useState<Record<string, string>>({});
  const [isDragging, setIsDragging] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  // New state for API companies
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loadingCompanies, setLoadingCompanies] = useState(false);

  useEffect(() => {
    // Load companies from API
    setLoadingCompanies(true);
    api.getCompanies()
        .then(data => setCompanies(data))
        .catch(err => console.error("Erro ao buscar empresas", err))
        .finally(() => setLoadingCompanies(false));

    // If pre-fill data exists, use it
    if (preFillData) {
      setCompetence(preFillData.competence);
      setSelectedCompanyId(preFillData.companyId);
    } else {
      // Set current competence default if not provided
      const now = new Date();
      const mm = String(now.getMonth() + 1).padStart(2, '0');
      const yyyy = now.getFullYear();
      setCompetence(`${mm}/${yyyy}`);
    }
  }, [preFillData]);

  useEffect(() => {
    // Recalculate dates when competence changes
    if (competence.match(/^\d{2}\/\d{4}$/)) {
        const dates = calcularTodosVencimentos(competence);
        setCalculatedDates(dates);

        // Update existing files dates if they have a category that matches a rule
        setFiles(prev => prev.map(f => {
            if (dates[f.category]) {
                return { ...f, dueDate: dates[f.category] };
            }
            return f;
        }));
    }
  }, [competence]);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    processFiles(Array.from(e.dataTransfer.files));
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      processFiles(Array.from(e.target.files));
    }
  };

  const processFiles = (fileList: File[]) => {
    const newFiles: UploadedFile[] = fileList.map(file => {
      const nameLower = file.name.toLowerCase();
      let category = '';
      let dueDate = '';

      // Simple heuristic for category guessing
      if (nameLower.includes('contracheque')) category = 'Contracheque';
      else if (nameLower.includes('fgts')) category = 'FGTS';
      else if (nameLower.includes('inss')) category = 'INSS';
      else if (nameLower.includes('simples')) category = 'Simples Nacional';
      else if (nameLower.includes('folha')) category = 'Folha de Pagamento';
      else if (nameLower.includes('honor')) category = 'Honorários';
      else if (nameLower.includes('fiscais') || nameLower.includes('nota')) category = 'Notas Fiscais';

      if (category && calculatedDates[category]) {
          dueDate = calculatedDates[category];
      }

      return {
        name: file.name,
        size: file.size,
        category: category || DOCUMENT_CATEGORIES[0],
        dueDate: dueDate,
        file: file
      };
    });

    setFiles(prev => [...prev, ...newFiles]);
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const updateFileCategory = (index: number, newCategory: string) => {
    setFiles(prev => prev.map((f, i) => {
        if (i === index) {
            const newDate = calculatedDates[newCategory] || f.dueDate;
            return { ...f, category: newCategory, dueDate: newDate };
        }
        return f;
    }));
  };

  const handleUploadClick = () => {
    if (!selectedCompanyId || !competence) {
        alert('Selecione uma empresa e uma competência');
        return;
    }

    onUploadSuccess(files, Number(selectedCompanyId), competence);

    setFiles([]);
    setIsSuccess(true);
    setTimeout(() => setIsSuccess(false), 3000);
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Upload de Documentos</h1>
          <p className="text-gray-500">Envie arquivos e o sistema calculará os vencimentos automaticamente.</p>
        </div>
      </div>

      {isSuccess && (
        <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded relative" role="alert">
            <strong className="font-bold">Sucesso!</strong>
            <span className="block sm:inline"> Arquivos enviados com sucesso para a aba de Envio.</span>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Settings Card */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-fit">
            <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2">
                <AlertCircle className="w-5 h-5 text-blue-500" /> Informações Básicas
            </h3>

            <div className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2">
                        Empresa 
                        {loadingCompanies && <Loader2 className="w-3 h-3 animate-spin" />}
                    </label>
                    <select 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-100"
                        value={selectedCompanyId}
                        onChange={e => setSelectedCompanyId(e.target.value)}
                        disabled={loadingCompanies}
                    >
                        <option value="">Selecione uma empresa...</option>
                        {companies.map(c => (
                            <option key={c.id} value={c.id}>{c.name} ({c.docNumber})</option>
                        ))}
                    </select>
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Competência (MM/AAAA)</label>
                    <input 
                        type="text"
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                        placeholder="MM/AAAA"
                        value={competence}
                        onChange={e => {
                            let val = e.target.value.replace(/\D/g, '');
                            if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                            setCompetence(val);
                        }}
                    />
                    <p className="text-xs text-gray-500 mt-1">Ao alterar a competência, os vencimentos serão recalculados.</p>
                </div>
            </div>
        </div>

        {/* Dropzone */}
        <div 
            className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center transition-colors
                ${isDragging ? 'border-blue-500 bg-blue-50' : 'border-gray-300 hover:border-blue-400 bg-gray-50'}`}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
        >
            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
                <UploadIcon className="w-8 h-8 text-blue-600" />
            </div>
            <h3 className="text-lg font-semibold text-gray-800">Arraste arquivos aqui</h3>
            <p className="text-gray-500 mb-4">ou clique para selecionar do computador</p>
            <input 
                type="file" 
                multiple 
                className="hidden" 
                id="file-input"
                onChange={handleFileSelect}
            />
            <label 
                htmlFor="file-input"
                className="bg-blue-600 text-white px-6 py-2 rounded-lg cursor-pointer hover:bg-blue-700 transition-colors"
            >
                Selecionar Arquivos
            </label>
        </div>
      </div>

      {files.length > 0 && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-4 border-b border-gray-100 bg-gray-50">
                  <h3 className="font-bold text-gray-700">Arquivos Selecionados ({files.length})</h3>
              </div>
              <div className="p-4 space-y-3">
                  {files.map((file, idx) => (
                      <div key={idx} className="flex flex-col md:flex-row gap-4 p-4 border border-gray-200 rounded-lg bg-white items-start md:items-center">
                          <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2 mb-1">
                                  <FileText className="w-4 h-4 text-gray-400" />
                                  <span className="font-medium text-gray-800 truncate">{file.name}</span>
                              </div>
                              <span className="text-xs text-gray-500">{formatSize(file.size)}</span>
                          </div>

                          <div className="flex-1 w-full md:w-auto">
                              <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Categoria</label>
                              <select 
                                className="w-full text-sm border-gray-300 rounded px-2 py-1.5 border"
                                value={file.category}
                                onChange={(e) => updateFileCategory(idx, e.target.value)}
                              >
                                  {DOCUMENT_CATEGORIES.map(cat => (
                                      <option key={cat} value={cat}>{cat}</option>
                                  ))}
                              </select>
                          </div>

                          <div className="w-full md:w-40">
                              <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Vencimento</label>
                              <div className="relative">
                                <Calendar className="w-3 h-3 absolute left-2 top-1/2 -translate-y-1/2 text-gray-400" />
                                <input 
                                    type="text" 
                                    className="w-full text-sm border-gray-300 rounded pl-7 px-2 py-1.5 border"
                                    value={file.dueDate}
                                    placeholder="DD/MM/AAAA"
                                    onChange={(e) => {
                                        const newFiles = [...files];
                                        newFiles[idx].dueDate = e.target.value;
                                        setFiles(newFiles);
                                    }}
                                />
                              </div>
                          </div>

                          <button 
                            onClick={() => removeFile(idx)}
                            className="text-gray-400 hover:text-red-500 p-2"
                          >
                              <X className="w-5 h-5" />
                          </button>
                      </div>
                  ))}
              </div>
              <div className="p-4 border-t border-gray-100 flex justify-end">
                  <button 
                    onClick={handleUploadClick}
                    className="bg-green-600 text-white px-8 py-3 rounded-lg hover:bg-green-700 shadow-lg shadow-green-900/20 font-medium flex items-center gap-2"
                  >
                      <UploadIcon className="w-5 h-5" /> Enviar Todos
                  </button>
              </div>
          </div>
      )}
    </div>
  );
};

export default Upload;

import React, { useState, useEffect } from 'react';
import { Mail, MessageCircle, Calendar, Send, CheckSquare, Square, ArrowLeft, Loader2 } from 'lucide-react';
import { Company } from '../types';
import { api } from '../services/api';

const BulkSend: React.FC = () => {
  const [companyType, setCompanyType] = useState<'normal' | 'mei'>('normal');
  const [schedule, setSchedule] = useState(false);

  // Real Data
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedCompanies, setSelectedCompanies] = useState<number[]>([]);

  useEffect(() => {
    setLoading(true);
    api.getCompanies()
        .then(data => {
            setCompanies(data);
            // Default select all matches current type logic if needed, but safer to start clean
            // Or select all of the default type
            const defaultTypeIds = data.filter(c => c.type !== 'MEI').map(c => c.id);
            setSelectedCompanies(defaultTypeIds);
        })
        .catch(err => console.error(err))
        .finally(() => setLoading(false));
  }, []);

  const filteredCompanies = companies.filter(c => {
      if (companyType === 'normal') return c.type !== 'MEI';
      return c.type === 'MEI';
  });

  const toggleSelectAll = () => {
      const filteredIds = filteredCompanies.map(c => c.id);
      const allSelected = filteredIds.every(id => selectedCompanies.includes(id));

      if (allSelected) {
          // Deselect only the visible ones
          setSelectedCompanies(prev => prev.filter(id => !filteredIds.includes(id)));
      } else {
          // Add missing visible ones
          const newSelection = [...new Set([...selectedCompanies, ...filteredIds])];
          setSelectedCompanies(newSelection);
      }
  };

  const toggleCompany = (id: number) => {
      if (selectedCompanies.includes(id)) {
          setSelectedCompanies(prev => prev.filter(cid => cid !== id));
      } else {
          setSelectedCompanies(prev => [...prev, id]);
      }
  };

  // Check if all filtered are selected
  const areAllFilteredSelected = filteredCompanies.length > 0 && filteredCompanies.every(c => selectedCompanies.includes(c.id));

  if (loading) return <div className="flex justify-center p-10"><Loader2 className="w-8 h-8 animate-spin text-blue-600" /></div>;

  return (
    <div className="space-y-6">
       <div>
        <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
            <Send className="w-6 h-6 text-blue-600" /> Envio em Massa
        </h1>
        <p className="text-gray-500">Envie comunicados ou documentos para múltiplas empresas.</p>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <div className="mb-6">
              <label className="block text-sm font-semibold text-gray-700 mb-2">Tipo de Empresa</label>
              <div className="flex gap-4">
                  <label className={`flex-1 border rounded-lg p-3 cursor-pointer transition-colors ${companyType === 'normal' ? 'bg-blue-50 border-blue-500 text-blue-700' : 'hover:bg-gray-50'}`}>
                      <input type="radio" name="type" className="hidden" checked={companyType === 'normal'} onChange={() => setCompanyType('normal')} />
                      <div className="font-semibold">Empresas Normais</div>
                      <div className="text-xs opacity-75">LTDA, S.A, Lucro Real/Presumido</div>
                  </label>
                  <label className={`flex-1 border rounded-lg p-3 cursor-pointer transition-colors ${companyType === 'mei' ? 'bg-purple-50 border-purple-500 text-purple-700' : 'hover:bg-gray-50'}`}>
                      <input type="radio" name="type" className="hidden" checked={companyType === 'mei'} onChange={() => setCompanyType('mei')} />
                      <div className="font-semibold">Empresas MEI</div>
                      <div className="text-xs opacity-75">Microempreendedor Individual</div>
                  </label>
              </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
              <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Assunto do E-mail</label>
                  <input type="text" className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" defaultValue="Comunicado Importante" />
              </div>
              <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Opções de Envio</label>
                  <div className="flex gap-4 pt-2">
                      <label className="flex items-center gap-2 cursor-pointer">
                          <input type="checkbox" className="rounded text-blue-600 w-4 h-4" defaultChecked />
                          <span className="flex items-center gap-1 text-sm"><Mail className="w-4 h-4" /> E-mail</span>
                      </label>
                      <label className="flex items-center gap-2 cursor-pointer">
                          <input type="checkbox" className="rounded text-green-600 w-4 h-4" />
                          <span className="flex items-center gap-1 text-sm"><MessageCircle className="w-4 h-4" /> WhatsApp</span>
                      </label>
                  </div>
              </div>
          </div>

          <div className="mb-6">
              <label className="block text-sm font-semibold text-gray-700 mb-1">Mensagem</label>
              <textarea 
                className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 h-32"
                defaultValue={`Prezados,\n\nGostaríamos de informar que...\n\nAtenciosamente,\nEquipe Contábil`}
              ></textarea>
          </div>

          <div className="mb-6">
              <div className="flex justify-between items-center mb-2 bg-gray-100 p-2 rounded-t-lg border-b border-gray-200">
                  <h3 className="font-bold text-gray-700 px-2">Empresas Destinatárias ({selectedCompanies.filter(id => filteredCompanies.some(c => c.id === id)).length})</h3>
                  <button onClick={toggleSelectAll} className="text-sm text-blue-600 hover:underline px-2 font-medium">
                      {areAllFilteredSelected ? 'Desmarcar Todas' : 'Selecionar Todas'}
                  </button>
              </div>
              <div className="border border-gray-200 rounded-b-lg max-h-60 overflow-y-auto">
                  {filteredCompanies.length === 0 ? (
                      <div className="p-4 text-center text-gray-500">Nenhuma empresa encontrada para este tipo.</div>
                  ) : filteredCompanies.map(company => (
                      <div key={company.id} className="flex items-center p-3 border-b last:border-0 hover:bg-gray-50">
                          <input 
                            type="checkbox" 
                            checked={selectedCompanies.includes(company.id)}
                            onChange={() => toggleCompany(company.id)}
                            className="w-4 h-4 rounded text-blue-600 mr-3"
                          />
                          <div className="flex-1">
                              <div className="font-medium text-sm text-gray-900">{company.name}</div>
                              <div className="text-xs text-gray-500">{company.email} • {company.whatsapp}</div>
                          </div>
                          <div className="text-xs text-gray-400 font-mono">{company.docNumber}</div>
                      </div>
                  ))}
              </div>
          </div>

          <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-6">
              <label className="flex items-center gap-2 cursor-pointer mb-2">
                  <input 
                    type="checkbox" 
                    checked={schedule} 
                    onChange={(e) => setSchedule(e.target.checked)}
                    className="w-4 h-4 rounded text-blue-600" 
                  />
                  <span className="font-semibold text-gray-700 flex items-center gap-1">
                      <Calendar className="w-4 h-4" /> Agendar Envio
                  </span>
              </label>
              {schedule && (
                  <div className="mt-3 pl-6">
                      <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Data e Hora</label>
                      <input type="datetime-local" className="border border-gray-300 rounded-lg px-3 py-2 outline-none text-sm bg-white" />
                  </div>
              )}
          </div>

          <div className="flex justify-end gap-3">
              <button className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg flex items-center gap-2">
                  <ArrowLeft className="w-4 h-4" /> Voltar
              </button>
              <button className="px-6 py-2 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 shadow-lg shadow-blue-500/20 flex items-center gap-2">
                  {schedule ? 'Agendar Envio' : 'Enviar Agora'} <Send className="w-4 h-4" />
              </button>
          </div>
      </div>
    </div>
  );
};

