    const { companyId, category, competence, status } = req.body;
    db.run(`INSERT INTO document_status (companyId, category, competence, status) VALUES (?, ?, ?, ?) ON CONFLICT(companyId, category, competence) DO UPDATE SET status = excluded.status`, [companyId, category, competence, status], (err) => res.json({ success: !err }));
});

// WA Status
app.get('/api/whatsapp/status', (req, res) => { res.json({ status: clientReady ? 'connected' : 'disconnected', qr: qrCodeData, info: client.info }); });
app.post('/api/whatsapp/disconnect', async (req, res) => { try { await client.logout(); await client.initialize(); res.json({ success: true }); } catch (e) { res.status(500).json({ error: e.message }); } });

app.get(/.*/, (req, res) => {
    if (!req.path.startsWith('/api')) res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

app.listen(port, () => console.log(`Server running at http://localhost:${port}`));

import React, { useState, useEffect } from 'react';
import { Send as SendIcon, Mail, MessageCircle, FileText, Trash, Clock, Check, Info, ArrowLeft, X, CheckSquare, Calendar, Loader2 } from 'lucide-react';
import { Document, Company } from '../types';
import { api } from '../services/api';

interface SendProps {
  documents: Document[];
  onSendDocuments: (ids: number[]) => void;
  onNavigateToDocuments: () => void;
}

const Send: React.FC<SendProps> = ({ documents, onSendDocuments, onNavigateToDocuments }) => {
  const getCurrentCompetence = () => {
    const now = new Date();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const yyyy = now.getFullYear();
    return `${mm}/${yyyy}`;
  };

  const [competence, setCompetence] = useState(getCurrentCompetence());
  const [subject, setSubject] = useState('Folha de Pagamento');
  const [message, setMessage] = useState('Segue em anexo os seguintes documentos:');
  const [sendEmail, setSendEmail] = useState(true);
  const [sendWhatsapp, setSendWhatsapp] = useState(false);
  const [selectedDocs, setSelectedDocs] = useState<number[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');
  const [scheduleChannels, setScheduleChannels] = useState({ email: true, whatsapp: false });
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loadingCompanies, setLoadingCompanies] = useState(false);

  useEffect(() => {
    setLoadingCompanies(true);
    api.getCompanies()
        .then(data => setCompanies(data))
        .catch(err => console.error(err))
        .finally(() => setLoadingCompanies(false));
  }, []);

  const pendingDocs = documents.filter(doc => doc.status === 'pending' && doc.competence === competence);

  const docsByCompany = pendingDocs.reduce((acc, doc) => {
    if (!acc[doc.companyId]) acc[doc.companyId] = [];
    acc[doc.companyId].push(doc);
    return acc;
  }, {} as Record<number, Document[]>);

  const getCompanyDetails = (id: number) => companies.find(c => c.id === id);

  const toggleDocSelection = (id: number) => {
    setSelectedDocs(prev => prev.includes(id) ? prev.filter(d => d !== id) : [...prev, id]);
  };

  const toggleCompanySelection = (companyId: number, companyDocs: Document[]) => {
    const allSelected = companyDocs.every(d => selectedDocs.includes(d.id));
    if (allSelected) {
      const idsToRemove = companyDocs.map(d => d.id);
      setSelectedDocs(prev => prev.filter(id => !idsToRemove.includes(id)));
    } else {
      const idsToAdd = companyDocs.map(d => d.id);
      setSelectedDocs(prev => [...new Set([...prev, ...idsToAdd])]);
    }
  };

  const toggleSelectGlobal = () => {
      const allPendingIds = pendingDocs.map(d => d.id);
      const allSelected = allPendingIds.length > 0 && allPendingIds.every(id => selectedDocs.includes(id));
      if (allSelected) setSelectedDocs([]);
      else setSelectedDocs(allPendingIds);
  };

  const handleSend = async () => {
    if (selectedDocs.length === 0) {
      alert('Selecione pelo menos um documento para enviar.');
      return;
    }
    if (!sendEmail && !sendWhatsapp) {
      alert('Selecione pelo menos um método de envio (E-mail ou WhatsApp).');
      return;
    }

    setIsProcessing(true);

    // Prepare payload for API
    const docsToSend = documents
        .filter(d => selectedDocs.includes(d.id))
        .map(d => ({
            id: d.id, // Enviar ID para o servidor retornar em caso de sucesso
            companyId: d.companyId,
            companyName: d.companyName,
            serverFilename: d.serverFilename || d.name, // Deve existir se foi feito upload correto
            docName: d.name,
            category: d.category,
            competence: d.competence
        }));

    try {
        const result = await api.sendDocuments({
            documents: docsToSend,
            subject,
            messageBody: message,
            channels: { email: sendEmail, whatsapp: sendWhatsapp }
        });

        if (result.success) {
            // Remove apenas os que o servidor confirmou que enviou (ou tentou processar com sucesso parcial)
            const successIds = result.sentIds || [];

            if (successIds.length > 0) {
                onSendDocuments(successIds);
                // Atualiza seleção removendo os enviados
                setSelectedDocs(prev => prev.filter(id => !successIds.includes(id)));
            }

            alert(`Processamento finalizado!\nSucessos: ${result.sent}\nErros: ${result.errors.length}\n${result.errors.length > 0 ? 'Verifique os logs no servidor para detalhes.' : ''}`);

            if (result.errors.length > 0) {
                console.warn("Erros detalhados:", result.errors);
            }
        } else {
            alert("Erro ao processar envio no servidor.");
        }

    } catch (e) {
        console.error(e);
        alert("Erro de comunicação com o servidor.");
    } finally {
        setIsProcessing(false);
    }
  };

  const handleOpenSchedule = () => {
     if (selectedDocs.length === 0) { alert('Selecione pelo menos um documento.'); return; }
     setScheduleChannels({ email: sendEmail, whatsapp: sendWhatsapp });
     setShowScheduleModal(true);
  };

  const confirmSchedule = () => {
      if (!scheduleDate) { alert("Selecione data e hora."); return; }
      alert(`Agendamento simulado para ${scheduleDate}. Backend precisa de implementação cron.`);
      setShowScheduleModal(false);
  }

  const allPendingIds = pendingDocs.map(d => d.id);
  const isGlobalSelected = allPendingIds.length > 0 && allPendingIds.every(id => selectedDocs.includes(id));

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
            <SendIcon className="w-6 h-6 text-blue-600" /> Envio de Documentos
            <span className="text-base font-normal text-gray-500">- Competência: {competence}</span>
        </h2>
      </div>

      <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-lg flex items-center gap-2">
         <MessageCircle className="w-5 h-5" /> 
         Status WhatsApp: <span className="text-green-600 font-bold">Conectado</span>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
         <div className="bg-gray-50 p-4 border-b border-gray-100">
             <h5 className="font-bold text-gray-700 flex items-center gap-2">
                 <Mail className="w-5 h-5" /> Configuração do Envio
             </h5>
         </div>
         <div className="p-6">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-4">
                 <div>
                     <label className="block text-sm font-semibold text-gray-700 mb-1">Assunto do E-mail*</label>
                     <div className="flex">
                         <span className="px-3 bg-gray-100 border border-r-0 border-gray-300 rounded-l-lg flex items-center text-gray-500"><Check className="w-4 h-4" /></span>
                         <input type="text" className="w-full border border-gray-300 rounded-r-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" value={subject} onChange={(e) => setSubject(e.target.value)} />
                     </div>
                 </div>
                 <div>
                     <label className="block text-sm font-semibold text-gray-700 mb-1">Competência</label>
                     <div className="flex">
                         <span className="px-3 bg-gray-100 border border-r-0 border-gray-300 rounded-l-lg flex items-center text-gray-500"><Clock className="w-4 h-4" /></span>
                         <input type="text" className="w-full border border-gray-300 rounded-r-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" value={competence} onChange={(e) => { let val = e.target.value.replace(/\D/g, ''); if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6); setCompetence(val); }} />
                     </div>
                 </div>
             </div>
             <div>
                 <label className="block text-sm font-semibold text-gray-700 mb-1">Mensagem*</label>
                 <textarea className="w-full border border-gray-300 rounded-lg px-3 py-2 h-24 outline-none focus:ring-2 focus:ring-blue-500" value={message} onChange={(e) => setMessage(e.target.value)} />
             </div>
         </div>
      </div>

      <div className="mb-4">
          <div className="flex justify-between items-center border-b pb-2 mb-4">
              <h4 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                  <FileText className="w-6 h-6 text-blue-600" /> Documentos Pendentes
                  {loadingCompanies && <Loader2 className="w-4 h-4 animate-spin text-gray-400" />}
              </h4>
              {pendingDocs.length > 0 && (
                  <button onClick={toggleSelectGlobal} className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${isGlobalSelected ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}>
                      <CheckSquare className="w-4 h-4" /> {isGlobalSelected ? 'Desmarcar Todos' : 'Selecionar Todos (Geral)'}
                  </button>
              )}
          </div>

          {Object.keys(docsByCompany).length === 0 ? (
              <div className="bg-blue-50 text-blue-700 p-4 rounded-lg flex items-center gap-2">
                  <Info className="w-5 h-5" /> Não há documentos pendentes para envio nesta competência.
                  <button onClick={onNavigateToDocuments} className="font-bold hover:underline">Voltar</button>
              </div>
          ) : (
              Object.entries(docsByCompany).map(([companyIdStr, companyDocsRaw]) => {
                  const companyId = Number(companyIdStr);
                  const companyDocs = companyDocsRaw as Document[];
                  const company = getCompanyDetails(companyId);
                  const allSelected = companyDocs.every(d => selectedDocs.includes(d.id));

                  return (
                      <div key={companyId} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden mb-4">
                          <div className="bg-blue-600 text-white p-4 flex justify-between items-center">
                              <div>
                                  <h5 className="font-bold text-lg">{company?.name || `Empresa ID: ${companyId}`}</h5>
                                  <div className="text-sm opacity-90 flex gap-3">
                                      <span className="flex items-center gap-1"><Mail className="w-3 h-3" /> {company?.email || 'N/A'}</span>
                                      <span className="flex items-center gap-1"><MessageCircle className="w-3 h-3" /> {company?.whatsapp || 'N/A'}</span>
                                  </div>
                              </div>
                              <label className="flex items-center gap-2 cursor-pointer bg-blue-700 px-3 py-1 rounded hover:bg-blue-800 transition-colors">
                                  <input type="checkbox" className="rounded text-blue-600 w-4 h-4" checked={allSelected} onChange={() => toggleCompanySelection(companyId, companyDocs)} />
                                  <span className="text-sm font-medium">Selecionar todos</span>
                              </label>
                          </div>
                          <div className="p-0">
                              <table className="w-full text-sm">
                                  <thead className="bg-gray-50 text-gray-600">
                                      <tr><th className="px-4 py-3 w-10"></th><th className="px-4 py-3 text-left">Documento</th><th className="px-4 py-3 text-left">Categoria</th><th className="px-4 py-3 text-left">Vencimento</th><th className="px-4 py-3 text-center">Status</th><th className="px-4 py-3 text-center">Ações</th></tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100">
                                      {companyDocs.map(doc => (
                                          <tr key={doc.id} className="hover:bg-gray-50 transition-colors">
                                              <td className="px-4 py-3 text-center"><input type="checkbox" className="rounded text-blue-600 w-4 h-4" checked={selectedDocs.includes(doc.id)} onChange={() => toggleDocSelection(doc.id)} /></td>
                                              <td className="px-4 py-3 font-medium text-gray-800 flex items-center gap-2"><FileText className="w-4 h-4 text-blue-500" /> {doc.name || 'Sem nome'}</td>
                                              <td className="px-4 py-3"><span className="px-2 py-1 bg-gray-100 rounded text-xs text-gray-600 font-medium">{doc.category}</span></td>
                                              <td className="px-4 py-3 text-gray-600">{doc.dueDate || <span className="text-gray-400">Não informado</span>}</td>
                                              <td className="px-4 py-3 text-center"><span className="bg-yellow-100 text-yellow-700 px-2 py-1 rounded text-xs font-bold uppercase">Pendente</span></td>
                                              <td className="px-4 py-3 text-center"><button className="text-red-500 hover:bg-red-50 p-1 rounded transition-colors"><Trash className="w-4 h-4" /></button></td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      </div>
                  );
              })
          )}
      </div>

      {Object.keys(docsByCompany).length > 0 && (
          <>
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden mb-4">
                <div className="bg-gray-50 p-4 border-b border-gray-100"><h5 className="font-bold text-gray-700 flex items-center gap-2"><SendIcon className="w-5 h-5" /> Opções de Envio Imediato</h5></div>
                <div className="p-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <label className="flex items-center gap-3 p-3 border rounded-lg cursor-pointer hover:bg-gray-50 transition-colors">
                            <input type="checkbox" className="w-5 h-5 rounded text-blue-600" checked={sendEmail} onChange={(e) => setSendEmail(e.target.checked)} />
                            <div className="flex flex-col"><span className="font-bold text-gray-800 flex items-center gap-2"><Mail className="w-4 h-4 text-blue-500" /> Enviar por E-mail</span></div>
                        </label>
                        <label className="flex items-center gap-3 p-3 border rounded-lg cursor-pointer hover:bg-gray-50 transition-colors">
                            <input type="checkbox" className="w-5 h-5 rounded text-green-600" checked={sendWhatsapp} onChange={(e) => setSendWhatsapp(e.target.checked)} />
                            <div className="flex flex-col"><span className="font-bold text-gray-800 flex items-center gap-2"><MessageCircle className="w-4 h-4 text-green-500" /> Enviar por WhatsApp</span></div>
                        </label>
                    </div>
                </div>
            </div>

            <div className="flex justify-between items-center pt-4 border-t">
                <button onClick={onNavigateToDocuments} className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 flex items-center gap-2 font-medium"><ArrowLeft className="w-4 h-4" /> Voltar</button>
                <div className="flex gap-3">
                    <button onClick={handleOpenSchedule} className="px-6 py-2 border-2 border-blue-600 text-blue-600 rounded-lg hover:bg-blue-50 flex items-center gap-2 font-bold"><Clock className="w-5 h-5" /> Agendar Envio</button>
                    <button onClick={handleSend} disabled={isProcessing} className="px-8 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg shadow-blue-500/20 flex items-center gap-2 font-bold disabled:opacity-70">
                        {isProcessing ? <><div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div> Enviando...</> : <><SendIcon className="w-5 h-5" /> Enviar Agora</>}
                    </button>
                </div>
            </div>
          </>
      )}

      {showScheduleModal && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200">
                  <div className="bg-blue-600 text-white p-4 flex justify-between items-center"><h5 className="font-bold flex items-center gap-2"><Clock className="w-5 h-5" /> Agendar Envio de Documentos</h5><button onClick={() => setShowScheduleModal(false)} className="hover:bg-blue-700 p-1 rounded"><X className="w-5 h-5" /></button></div>
                  <div className="p-6 space-y-4">
                      <div className="bg-gray-50 p-4 rounded-lg border border-gray-200"><h6 className="text-sm font-bold text-gray-700 mb-2 flex items-center gap-2"><FileText className="w-4 h-4" /> Resumo da Seleção</h6><div className="text-sm text-gray-600">Você está agendando o envio de <strong>{selectedDocs.length} documentos</strong>.</div></div>
                      <div><label className="block text-sm font-semibold text-gray-700 mb-1">Data e Hora do Envio*</label><div className="relative"><Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" /><input type="datetime-local" className="w-full border border-gray-300 rounded-lg pl-10 pr-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} /></div></div>
                  </div>
                  <div className="p-4 border-t flex justify-end gap-3 bg-gray-50"><button onClick={() => setShowScheduleModal(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-medium">Cancelar</button><button onClick={confirmSchedule} className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold">Confirmar Agendamento</button></div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Send;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Kanban from './components/Kanban';
import Companies from './components/Companies';
import WhatsAppConnect from './components/WhatsAppConnect';
import Documents from './components/Documents';
import Upload from './components/Upload';
import BulkSend from './components/BulkSend';
import ScheduledMessages from './components/ScheduledMessages';
import Settings from './components/Settings';
import Send from './components/Send'; 
import { DEFAULT_USER_SETTINGS, MOCK_DOCUMENTS } from './constants';
import { UserSettings, Document, UploadedFile } from './types';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Lifted state for User Settings
  const [userSettings, setUserSettings] = useState<UserSettings>(DEFAULT_USER_SETTINGS);

  // Lifted state for Documents (Shared between Documents, Upload, and Send)
  const [documents, setDocuments] = useState<Document[]>(MOCK_DOCUMENTS);

  // State for pre-filling Upload form
  const [uploadPreFill, setUploadPreFill] = useState<{companyId: number, competence: string} | null>(null);

  const handleNavigateToUpload = (companyId: number, competence: string) => {
    setUploadPreFill({ companyId, competence });
    setActivePage('upload');
  };

  const handleNavigateToDocuments = () => {
    setActivePage('documents');
  }

  // Handle new file upload from Upload tab
  const handleUploadSuccess = (files: UploadedFile[], companyId: number, competence: string) => {
      const newDocs: Document[] = files.map(f => ({
          id: Date.now() + Math.random(),
          name: f.name,
          category: f.category,
          competence: competence,
          dueDate: f.dueDate,
          status: 'pending', 
          companyId: companyId,
          companyName: 'Loading...', // Should be resolved locally or via api fetch if critical
          file: f.file,
          serverFilename: f.serverFilename // Crucial for sending
      }));
      setDocuments(prev => [...prev, ...newDocs]);
  };

  // Toggle status in Matrix (Visual manual override)
  const handleToggleStatus = (companyId: number, category: string, competence: string) => {
      setDocuments(prev => {
          const existingIndex = prev.findIndex(d => 
              d.companyId === companyId && 
              d.category === category && 
              d.competence === competence
          );

          if (existingIndex >= 0) {
              // Toggle existing
              const newDocs = [...prev];
              newDocs[existingIndex] = {
                  ...newDocs[existingIndex],
                  status: newDocs[existingIndex].status === 'sent' ? 'pending' : 'sent'
              };
              return newDocs;
          } else {
              // Create manual entry
              const newDoc: Document = {
                  id: Date.now(),
                  name: `Manual - ${category}`,
                  category: category,
                  competence: competence,
                  dueDate: '',
                  status: 'sent', 
                  companyId: companyId,
                  companyName: 'Manual Entry',
                  isManual: true
              };
              return [...prev, newDoc];
          }
      });
  };

  // Handle Sending from Send Tab
  const handleSendDocuments = (docIds: number[]) => {
      // Aqui só atualizamos status, não removemos se falhar.
      setDocuments(prev => prev.map(doc => {
          if (docIds.includes(doc.id)) {
              return { ...doc, status: 'sent' };
          }
          return doc;
      }));
  };

  const renderContent = () => {
    switch (activePage) {
      case 'dashboard':
        return <Dashboard />;
      case 'companies':
        return <Companies />;
      case 'whatsapp':
        return <WhatsAppConnect />;
      case 'documents':
        return <Documents 
                  userSettings={userSettings} 
                  onNavigateToUpload={handleNavigateToUpload}
                  documents={documents}
                  onToggleStatus={handleToggleStatus}
                  onUploadSuccess={handleUploadSuccess}
               />;
      case 'upload':
        return <Upload 
                  preFillData={uploadPreFill} 
                  onUploadSuccess={handleUploadSuccess}
               />;
      case 'send':
        return <Send 
                  documents={documents}
                  onSendDocuments={handleSendDocuments}
                  onNavigateToDocuments={handleNavigateToDocuments}
               />;
      case 'bulksend':
        return <BulkSend />;
      case 'scheduled':
        return <ScheduledMessages />;
      case 'settings':
        return <Settings settings={userSettings} onSave={setUserSettings} />;
      default:
        return (
          <div className="flex flex-col items-center justify-center h-[50vh] text-gray-400">
            <h2 className="text-xl font-semibold mb-2">Em Construção</h2>
            <p>A página {activePage} será implementada em breve.</p>
          </div>
        );
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <Sidebar 
        activePage={activePage} 
        setActivePage={setActivePage} 
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
      />

      <main className="flex-1 overflow-auto w-full relative">
        <header className="bg-white border-b border-gray-200 px-6 py-4 flex justify-between items-center sticky top-0 z-30">
          <h2 className="text-lg font-semibold text-gray-700 capitalize">
            {activePage === 'bulksend' ? 'Envio em Massa' : activePage === 'settings' ? 'Usuário' : activePage === 'send' ? 'Envio' : activePage}
          </h2>
          <div className="flex items-center gap-4">
             <div className="text-sm text-right hidden sm:block">
                <p className="font-bold text-gray-700">Lucas Araújo</p>
                <p className="text-gray-500 text-xs">Contador | CRC-BA 046968/O</p>
             </div>
             <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-700 font-bold border-2 border-white shadow-sm">
                LA
             </div>
          </div>
        </header>

        <div className="p-6 max-w-7xl mx-auto pb-20">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Upload, CalendarCheck, Search, FileText, Check, X, Play, Settings as SettingsIcon, Filter, FolderArchive, Loader2, FilePlus } from 'lucide-react';
import { DOCUMENT_CATEGORIES } from '../constants';
import { UserSettings, Document, Company, UploadedFile } from '../types';
import { identifyCategory, identifyCompany } from '../utils/documentProcessor';
import { api } from '../services/api';
import { calcularTodosVencimentos } from '../utils/dateHelpers';
import JSZip from 'jszip';

interface DocumentsProps {
  userSettings: UserSettings;
  onNavigateToUpload: (companyId: number, competence: string) => void;
  documents: Document[];
  onToggleStatus: (companyId: number, category: string, competence: string) => void;
  onUploadSuccess: (files: UploadedFile[], companyId: number, competence: string) => void;
}

const Documents: React.FC<DocumentsProps> = ({ 
  userSettings, 
  onNavigateToUpload, 
  documents: initialDocuments,
  onToggleStatus,
  onUploadSuccess
}) => {
  // Helper to get current competence formatted MM/YYYY
  const getCurrentCompetence = () => {
    const now = new Date();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const yyyy = now.getFullYear();
    return `${mm}/${yyyy}`;
  };

  const [competence, setCompetence] = useState(getCurrentCompetence());
  const [activeCompetence, setActiveCompetence] = useState(getCurrentCompetence()); // Drives the matrix

  // Real Data State
  const [companies, setCompanies] = useState<Company[]>([]);
  const [dbStatuses, setDbStatuses] = useState<any[]>([]); // Statuses from DB
  const [loading, setLoading] = useState(true);

  // Processing State
  const [localPath, setLocalPath] = useState('');
  const [processingCompetence, setProcessingCompetence] = useState(getCurrentCompetence());
  const [processing, setProcessing] = useState(false);
  const [processingResults, setProcessingResults] = useState<{total: number, processed: number, filtered: number} | null>(null);

  // Matrix Filters
  const [matrixSearch, setMatrixSearch] = useState('');
  const [matrixStatusFilter, setMatrixStatusFilter] = useState<'all' | 'pending' | 'sent'>('all');
  const [matrixCategoryFilter, setMatrixCategoryFilter] = useState<string>('all');

  // Processing Filters
  const [selectedCompanies, setSelectedCompanies] = useState<string[]>([]);
  const [selectedCategories, setSelectedCategories] = useState<string[]>([]);

  // Ref for the hidden file input
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Fetch Data
  const fetchData = async () => {
      setLoading(true);
      try {
          const [comps, statuses] = await Promise.all([
              api.getCompanies(),
              api.getDocumentStatuses(activeCompetence)
          ]);
          setCompanies(comps);
          setDbStatuses(statuses);
      } catch (error) {
          console.error("Error fetching documents data", error);
      } finally {
          setLoading(false);
      }
  };

  useEffect(() => {
      fetchData();
  }, [activeCompetence]);

  // Use visible categories from settings for the Matrix Columns
  const visibleMatrixCategories = userSettings.visibleDocumentCategories.length > 0 
    ? userSettings.visibleDocumentCategories 
    : DOCUMENT_CATEGORIES.slice(0, 8);

  const handleProcessClick = () => {
    // Trigger hidden file input
    if (fileInputRef.current) {
        fileInputRef.current.click();
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
        const files = Array.from(e.target.files);

        // Update display text
        if (files.length === 1) {
            setLocalPath(files[0].name);
        } else {
            setLocalPath(`${files.length} arquivos selecionados`);
        }

        // Check if user selected a ZIP file
        const zipFile = files.find(f => f.name.endsWith('.zip') || f.name.endsWith('.rar'));

        if (zipFile) {
             if (files.length > 1) {
                 alert("Ao selecionar um arquivo ZIP, selecione apenas ele.");
                 return;
             }
             await processZipFile(zipFile);
        } else {
             // Process regular files (PDFs, Images, etc.)
             await processMultipleFiles(files);
        }
    }
  };

  // Process a list of standard files
  const processMultipleFiles = async (fileList: File[]) => {
      setProcessing(true);
      setProcessingResults(null);

      const calculatedDates = calcularTodosVencimentos(processingCompetence);
      let processedCount = 0;
      let filteredCount = 0;

      try {
          for (const file of fileList) {
             const textContent = file.name; // Use filename for categorization
             const category = identifyCategory(textContent, userSettings.categoryKeywords);
             const company = identifyCompany(textContent, companies);

             const categoryFilter = selectedCategories.length > 0 ? selectedCategories : [];
             const companyFilter = selectedCompanies.length > 0 ? selectedCompanies : [];

             if (!category || (categoryFilter.length > 0 && !categoryFilter.includes(category))) {
                 filteredCount++;
                 continue;
             }

             if (!company || (companyFilter.length > 0 && !companyFilter.includes(String(company.id)))) {
                 filteredCount++;
                 continue;
             }

             // Real Upload
             try {
                const uploadRes = await api.uploadFile(file);

                const uploadedFile: UploadedFile = {
                    name: file.name,
                    size: file.size,
                    category: category,
                    dueDate: calculatedDates[category] || '',
                    file: file,
                    serverFilename: uploadRes.filename
                };

                // Add to App state
                onUploadSuccess([uploadedFile], company.id, processingCompetence);
                processedCount++;
             } catch (err) {
                 console.error(`Falha ao enviar arquivo ${file.name}`, err);
                 filteredCount++; // Consider upload fail as filtered/error
             }
          }

          setProcessingResults({
              total: fileList.length,
              processed: processedCount,
              filtered: filteredCount
          });

      } catch (e) {
          console.error("Erro processando arquivos", e);
          alert("Erro ao processar arquivos.");
      } finally {
          setProcessing(false);
          if (fileInputRef.current) fileInputRef.current.value = '';
      }
  };

  const processZipFile = async (zipFile: File) => {
      setProcessing(true);
      setProcessingResults(null);
      const calculatedDates = calcularTodosVencimentos(processingCompetence);

      try {
        const zip = await JSZip.loadAsync(zipFile);
        const entries: {name: string, obj: any}[] = [];

        zip.forEach((relativePath, zipEntry) => {
            if (!zipEntry.dir) {
                entries.push({ name: zipEntry.name, obj: zipEntry });
            }
        });

        let processedCount = 0;
        let filteredCount = 0;

        for (const entry of entries) {
            const fileName = entry.name;
            // Clean filename from path if needed
            const simpleName = fileName.split('/').pop() || fileName;

            const category = identifyCategory(simpleName, userSettings.categoryKeywords);
            const company = identifyCompany(simpleName, companies);

            const categoryFilter = selectedCategories.length > 0 ? selectedCategories : [];
            const companyFilter = selectedCompanies.length > 0 ? selectedCompanies : [];

            if (!category || (categoryFilter.length > 0 && !categoryFilter.includes(category))) {
                filteredCount++;
                continue;
            }

            if (!company || (companyFilter.length > 0 && !companyFilter.includes(String(company.id)))) {
                filteredCount++;
                continue;
            }

            // Convert ZipObject to Blob/File for upload
            const blob = await entry.obj.async("blob");
            const file = new File([blob], simpleName, { type: blob.type || 'application/pdf' });

            try {
                const uploadRes = await api.uploadFile(file);

                const uploadedFile: UploadedFile = {
                    name: simpleName,
                    size: file.size,
                    category: category,
                    dueDate: calculatedDates[category] || '',
                    file: file,
                    serverFilename: uploadRes.filename
                };

                onUploadSuccess([uploadedFile], company.id, processingCompetence);
                processedCount++;
            } catch (err) {
                 console.error(`Falha ao enviar arquivo extraído ${simpleName}`, err);
                 filteredCount++;
            }
        }

        setProcessingResults({
            total: entries.length,
            processed: processedCount,
            filtered: filteredCount
        });

      } catch (error) {
          console.error("Error reading zip", error);
          alert("Erro ao ler o arquivo ZIP.");
      } finally {
          setProcessing(false);
          if (fileInputRef.current) fileInputRef.current.value = '';
      }
  };

  // Company Filter Logic
  const toggleCompanySelection = (id: string) => {
    setSelectedCompanies(prev => 
      prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]
    );
  };
  const toggleSelectAllCompanies = () => {
    if (selectedCompanies.length === companies.length) {
      setSelectedCompanies([]);
    } else {
      setSelectedCompanies(companies.map(c => String(c.id)));
    }
  };

  // Category Filter Logic
  const toggleCategorySelection = (cat: string) => {
    setSelectedCategories(prev => 
      prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]
    );
  };
  const toggleSelectAllCategories = () => {
    if (selectedCategories.length === DOCUMENT_CATEGORIES.length) {
      setSelectedCategories([]);
    } else {
      setSelectedCategories(DOCUMENT_CATEGORIES);
    }
  };

  // --- Matrix Helpers ---

  // 1. Get Status from DB State
  const getStatus = (companyId: number, category: string) => {
      // Check DB statuses first
      const dbStatus = dbStatuses.find(s => 
          s.companyId === companyId && 
          s.category === category && 
          s.competence === activeCompetence
      );

      if (dbStatus) return dbStatus.status;

      // Fallback to Documents passed via props (local state for upload session)
      const doc = initialDocuments.find(d => 
        d.companyId === companyId && 
        d.category === category && 
        d.competence === activeCompetence
      );
      return doc ? doc.status : 'pending';
  };

  const handleToggleStatusLocal = async (companyId: number, category: string) => {
      const currentStatus = getStatus(companyId, category);
      const newStatus = currentStatus === 'sent' ? 'pending' : 'sent';

      // Optimistic update locally
      const updatedDbStatuses = [...dbStatuses];
      const existingIdx = updatedDbStatuses.findIndex(s => s.companyId === companyId && s.category === category);

      if (existingIdx >= 0) {
          updatedDbStatuses[existingIdx].status = newStatus;
      } else {
          updatedDbStatuses.push({ companyId, category, competence: activeCompetence, status: newStatus });
      }
      setDbStatuses(updatedDbStatuses);

      // Persist to API
      try {
          await api.updateDocumentStatus(companyId, category, activeCompetence, newStatus);
          // Also call parent handler to keep sync if needed
          onToggleStatus(companyId, category, activeCompetence);
      } catch (e) {
          console.error("Failed to update status");
          // Revert optimistic update? For now we just log.
      }
  };

  // 2. Determine Columns (Categories) based on Matrix Filter
  const getMatrixCategories = () => {
      if (matrixCategoryFilter !== 'all') {
          return [matrixCategoryFilter];
      }
      return visibleMatrixCategories;
  };

  // 3. Filter Rows (Companies) based on Matrix Filters
  const getMatrixCompanies = () => {
      return companies.filter(company => {
          // Name Filter
          const matchesName = company.name.toLowerCase().includes(matrixSearch.toLowerCase());
          if (!matchesName) return false;

          // Status Filter
          if (matrixStatusFilter !== 'all') {
              const visibleCategories = getMatrixCategories();
              const hasMatchingStatus = visibleCategories.some(cat => {
                  const status = getStatus(company.id, cat);
                  return status === matrixStatusFilter;
              });
              if (!hasMatchingStatus) return false;
          }

          return true;
      });
  };

  const handleSearchCompetence = (e: React.FormEvent) => {
      e.preventDefault();
      setActiveCompetence(competence);
  };

  if (loading && companies.length === 0) {
     return <div className="flex justify-center p-10"><Loader2 className="w-8 h-8 animate-spin text-blue-600" /></div>;
  }

  return (
    <div className="space-y-6">

      {/* Competence Selection Card */}
      <div className="bg-white rounded-xl shadow-sm border-0 overflow-hidden mb-4">
        <div className="bg-blue-600 text-white py-3 px-6">
            <h5 className="mb-0 flex items-center gap-2 font-bold">
                <CalendarCheck className="w-5 h-5" /> Verificar Documentos por Competência (Normal)
            </h5>
        </div>
        <div className="p-6">
            <form onSubmit={handleSearchCompetence}>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1">
                        <label htmlFor="competencia" className="block text-sm font-semibold text-gray-700 mb-2">Digite a competência (MM/AAAA)</label>
                        <div className="relative">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">
                                <CalendarCheck className="w-5 h-5" />
                            </span>
                            <input 
                                type="text" 
                                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500" 
                                id="competencia" 
                                placeholder="Ex: 05/2023" 
                                value={competence}
                                onChange={(e) => {
                                    let val = e.target.value.replace(/\D/g, '');
                                    if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                                    setCompetence(val);
                                }}
                                required 
                            />
                        </div>
                    </div>
                    <div className="flex-1 md:flex-none md:w-48">
                        <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition-colors flex items-center justify-center gap-2 font-medium">
                            <Search className="w-4 h-4" /> Verificar
                        </button>
                    </div>
                </div>
            </form>
        </div>
      </div>

      {/* Automatic Processing Card */}
      <div className="bg-white rounded-xl shadow-sm border border-blue-100 overflow-hidden">
         <div className="bg-blue-50 p-4 border-b border-blue-100 flex items-center gap-2 text-blue-800">
            <SettingsIcon className="w-5 h-5" />
            <h3 className="font-bold">Processamento Automático</h3>
        </div>
        <div className="p-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">

                {/* Path Input */}
                <div className="lg:col-span-1">
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Arquivos (ZIP ou Múltiplos)</label>
                    <div className="input-group flex items-center border border-gray-300 rounded-lg overflow-hidden bg-white cursor-pointer hover:bg-gray-50" onClick={handleProcessClick}>
                         <span className="px-3 text-gray-400 bg-gray-50 border-r py-2"><FolderArchive className="w-4 h-4" /></span>
                         <input 
                            type="text" 
                            className="flex-1 px-3 py-2 outline-none text-sm cursor-pointer"
                            placeholder="Selecione arquivos ou ZIP..."
                            value={localPath}
                            readOnly
                         />
                         <input 
                            type="file" 
                            multiple
                            accept=".zip,.rar,.pdf,.png,.jpg,.jpeg,.doc,.docx"
                            ref={fileInputRef} 
                            className="hidden" 
                            onChange={handleFileSelect} 
                        />
                    </div>
                </div>

                {/* Processing Competence */}
                <div>
                   <label className="block text-sm font-semibold text-gray-700 mb-1">Competência do Processamento</label>
                   <input 
                        type="text" 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                        placeholder="MM/AAAA"
                        value={processingCompetence}
                        onChange={(e) => {
                            let val = e.target.value.replace(/\D/g, '');
                            if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                            setProcessingCompetence(val);
                        }}
                    />
                </div>

                {/* Company Filter */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Filtrar Empresas</label>
                  <div className="relative group">
                    <button className="w-full text-left border border-gray-300 rounded-lg px-3 py-2 text-sm bg-white flex justify-between items-center">
                      <span className="truncate">
                        {selectedCompanies.length === 0 ? 'Todas as Empresas' : `${selectedCompanies.length} selecionadas`}
                      </span>
                    </button>
                    <div className="absolute top-full left-0 w-full mt-1 bg-white border border-gray-200 rounded-lg shadow-lg z-20 hidden group-hover:block hover:block p-2 max-h-96 overflow-y-auto">
                        <label className="flex items-center gap-2 p-1 hover:bg-gray-50 rounded cursor-pointer border-b mb-1 pb-1">
                          <input 
                            type="checkbox" 
                            className="rounded text-blue-600"
                            checked={selectedCompanies.length === companies.length}
                            onChange={toggleSelectAllCompanies}
                          />
                          <span className="text-sm font-bold text-gray-700">Selecionar Todas</span>
                        </label>
                        {companies.map(c => (
                          <label key={c.id} className="flex items-center gap-2 p-1 hover:bg-gray-50 rounded cursor-pointer">
                            <input 
                              type="checkbox" 
                              className="rounded text-blue-600"
                              checked={selectedCompanies.includes(String(c.id))}
                              onChange={() => toggleCompanySelection(String(c.id))}
                            />
                            <span className="text-sm text-gray-600 truncate">{c.name}</span>
                          </label>
                        ))}
                    </div>
                  </div>
                </div>

                {/* Category Filter */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Filtrar Categorias</label>
                  <div className="relative group">
                    <button className="w-full text-left border border-gray-300 rounded-lg px-3 py-2 text-sm bg-white flex justify-between items-center">
                      <span className="truncate">
                        {selectedCategories.length === 0 ? 'Todas as Categorias' : `${selectedCategories.length} selecionadas`}
                      </span>
                    </button>
                    <div className="absolute top-full left-0 w-full mt-1 bg-white border border-gray-200 rounded-lg shadow-lg z-20 hidden group-hover:block hover:block p-2 max-h-96 overflow-y-auto">
                        <label className="flex items-center gap-2 p-1 hover:bg-gray-50 rounded cursor-pointer border-b mb-1 pb-1">
                          <input 
                            type="checkbox" 
                            className="rounded text-blue-600"
                            checked={selectedCategories.length === DOCUMENT_CATEGORIES.length}
                            onChange={toggleSelectAllCategories}
                          />
                          <span className="text-sm font-bold text-gray-700">Todas</span>
                        </label>
                        {DOCUMENT_CATEGORIES.map(cat => (
                          <label key={cat} className="flex items-center gap-2 p-1 hover:bg-gray-50 rounded cursor-pointer">
                            <input 
                              type="checkbox" 
                              className="rounded text-blue-600"
                              checked={selectedCategories.includes(cat)}
                              onChange={() => toggleCategorySelection(cat)}
                            />
                            <span className="text-sm text-gray-600 truncate">{cat}</span>
                          </label>
                        ))}
                    </div>
                  </div>
                </div>
            </div>

            <div className="mt-6 flex flex-col items-center">
                 <button 
                    onClick={handleProcessClick}
                    disabled={processing}
                    className="bg-blue-600 text-white px-8 py-3 rounded-lg hover:bg-blue-700 shadow-lg shadow-blue-500/20 font-bold flex items-center gap-2 disabled:opacity-70 transition-all"
                 >
                    {processing ? (
                        <><Loader2 className="animate-spin rounded-full h-4 w-4" /> Processando e Enviando...</>
                    ) : (
                        <><Play className="w-5 h-5" /> Iniciar Processamento Automático</>
                    )}
                 </button>
                 {processingResults && (
                   <div className="mt-4 text-sm text-gray-600 bg-gray-50 p-2 rounded border border-gray-200 text-center">
                      <p><strong>Resultado do Processamento:</strong> {processingResults.total} arquivos analisados.</p>
                      <div className="flex gap-4 justify-center mt-1">
                          <span className="text-green-600 font-bold">{processingResults.processed} aceitos e enviados</span>
                          <span className="text-red-500 font-bold">{processingResults.filtered} filtrados/erros</span>
                      </div>
                      <p className="text-xs text-gray-400 mt-1">Os arquivos aceitos já estão disponíveis na aba "Envio".</p>
                   </div>
                 )}
            </div>
        </div>
      </div>

      {/* Document Matrix Section */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">

        <div className="p-4 border-b border-gray-100 bg-gray-50">
           {/* Filters Bar */}
           <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold text-gray-700">
                Matriz de Status - <span className="text-blue-600">{activeCompetence}</span>
              </h3>
              <div className="flex gap-3 text-sm">
                <span className="flex items-center gap-1 text-green-600"><Check className="w-4 h-4" /> Enviado</span>
                <span className="flex items-center gap-1 text-red-500"><X className="w-4 h-4" /> Pendente</span>
              </div>
           </div>

           <div className="flex flex-col md:flex-row gap-4 p-3 bg-white border border-gray-200 rounded-lg">
              <div className="flex-1">
                 <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Buscar Empresa</label>
                 <div className="relative">
                    <Search className="w-4 h-4 absolute left-2 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input 
                      type="text" 
                      className="w-full pl-8 pr-3 py-1.5 border border-gray-300 rounded text-sm outline-none focus:ring-1 focus:ring-blue-500"
                      placeholder="Nome da empresa..."
                      value={matrixSearch}
                      onChange={(e) => setMatrixSearch(e.target.value)}
                    />
                 </div>
              </div>
              <div className="flex-1">
                 <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Filtrar Categoria</label>
                 <select 
                   className="w-full border border-gray-300 rounded px-2 py-1.5 text-sm outline-none"
                   value={matrixCategoryFilter}
                   onChange={(e) => setMatrixCategoryFilter(e.target.value)}
                 >
                   <option value="all">Todas as Categorias</option>
                   {visibleMatrixCategories.map(cat => (
                     <option key={cat} value={cat}>{cat}</option>
                   ))}
                 </select>
              </div>
              <div className="flex-1">
                 <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Filtrar Status</label>
                 <select 
                   className="w-full border border-gray-300 rounded px-2 py-1.5 text-sm outline-none"
                   value={matrixStatusFilter}
                   onChange={(e) => setMatrixStatusFilter(e.target.value as any)}
                 >
                   <option value="all">Todos</option>
                   <option value="pending">Pendente (Exibir se houver)</option>
                   <option value="sent">Enviado (Exibir se houver)</option>
                 </select>
              </div>
           </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-200">
                <th className="px-6 py-4 text-left font-semibold text-gray-600 bg-gray-50 min-w-[200px] sticky left-0 shadow-sm z-10">Empresa</th>
                {getMatrixCategories().map(cat => (
                  <th key={cat} className="px-4 py-4 text-center font-semibold text-gray-600 min-w-[100px]">{cat}</th>
                ))}
                <th className="px-4 py-4 text-center font-semibold text-gray-600 bg-gray-50 min-w-[100px] sticky right-0 shadow-sm z-10 border-l">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {getMatrixCompanies().map((company) => (
                <tr key={company.id} className="hover:bg-gray-50 group">
                  <td className="px-6 py-4 font-medium text-gray-900 bg-white group-hover:bg-gray-50 sticky left-0 shadow-sm">
                    {company.name}
                  </td>
                  {getMatrixCategories().map((cat) => {
                     const status = getStatus(company.id, cat);
                     const isSent = status === 'sent';
                     return (
                      <td key={cat} className="px-4 py-4 text-center">
                        <button 
                            onClick={() => handleToggleStatusLocal(company.id, cat)}
                            className={`w-8 h-8 rounded-full inline-flex items-center justify-center transition-all duration-200 cursor-pointer
                            ${isSent 
                                ? 'bg-green-100 text-green-600 hover:bg-green-200 hover:scale-110' 
                                : 'bg-red-50 text-red-500 hover:bg-red-100 hover:scale-110'}`}
                            title={isSent ? 'Clique para marcar como Pendente' : 'Clique para marcar como Enviado'}
                        >
                            {isSent ? <Check className="w-4 h-4" /> : <X className="w-4 h-4" />}
                        </button>
                      </td>
                     );
                  })}
                  <td className="px-4 py-4 text-center bg-white group-hover:bg-gray-50 sticky right-0 shadow-sm border-l">
                      <button 
                        onClick={() => onNavigateToUpload(company.id, activeCompetence)}
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                        title="Fazer Upload para esta empresa"
                      >
                          <Upload className="w-5 h-5" />
                      </button>
                  </td>
                </tr>
              ))}
              {getMatrixCompanies().length === 0 && (
                <tr>
                   <td colSpan={getMatrixCategories().length + 2} className="px-6 py-8 text-center text-gray-500">
                      Nenhuma empresa encontrada com os filtros selecionados.
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Documents;

// Fixed holidays list (Day-Month)
// (1, 1) -> "01-01"
const FIXED_HOLIDAYS = [
  '01-01', // Ano Novo
  '04-21', // Tiradentes
  '05-01', // Dia do Trabalho
  '09-07', // Independência
  '10-12', // Nossa Senhora Aparecida
  '11-02', // Finados
