import { Company } from '../types';
import * as pdfjsLib from 'pdfjs-dist';

// Define worker URL explicitly using the same version as the library to avoid version mismatch errors
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://esm.sh/pdfjs-dist@3.11.174/build/pdf.worker.min.mjs';

/**
 * Normalizes text to remove accents and special chars for better matching
 */
export const removeAccents = (text: string): string => {
  if (!text) return "";
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
};

/**
 * Extracts text content from a PDF file
 */
export const extractTextFromPDF = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
    const pdf = await loadingTask.promise;
    let fullText = "";

    // Read up to 5 pages to save performance but get enough context
    const maxPages = Math.min(pdf.numPages, 5);

    for (let i = 1; i <= maxPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      // Join items with space, but also handle cases where letters are split
      const pageText = textContent.items.map((item: any) => item.str).join(" ");
      fullText += pageText + " ";
    }

    return fullText;
  } catch (error) {
    console.error("Erro ao ler PDF:", error);
    return "";
  }
};

/**
 * Identifies the category based on text content and keywords map.
 */
export const identifyCategory = (text: string, keywordMap: Record<string, string[]>): string | null => {
  const textNormalized = removeAccents(text);

  // Priority 1: Exclusive rules (Hardcoded overrides)
  if (textNormalized.includes('cora.com.br')) return 'Honorários';
  if (textNormalized.includes('nota fiscal')) return 'Notas Fiscais';

  // Priority 2: Combinations
  if (textNormalized.includes('folha mensal') && textNormalized.includes('extrato mensal')) {
    return 'Folha de Pagamento';
  }

  // Priority 3: Specific single keywords
  if (textNormalized.includes('folha mensal')) {
    return 'Contracheque';
  }

  // Priority 4: Dynamic User Settings (The most important part for custom bindings)
  for (const [category, keywords] of Object.entries(keywordMap)) {
    if (!keywords || !Array.isArray(keywords)) continue;

    for (const keyword of keywords) {
      if (!keyword) continue;
      const kwNormalized = removeAccents(keyword);
      // Check if the normalized text contains the normalized keyword
      if (textNormalized.includes(kwNormalized)) {
        return category;
      }
    }
  }

  return null;
};

/**
 * Identifies the company based on text content using flexible Regex logic.
 */
export const identifyCompany = (text: string, companies: Company[]): Company | null => {
  const textNormalized = removeAccents(text);

  // Clean text for pure digit search as well (removing all non-digits)
  const textDigitsOnly = text.replace(/\D/g, '');

  // 1. Regex Search for CNPJ/CPF (Flexible with spaces)
  // Allows optional spaces \s* between separators and digits to catch PDF scanning issues
  // Example: 12 . 345 . 678 / 0001 - 99
  const pattern = /(\d{2}\s*\.\s*\d{3}\s*\.\s*\d{3}\s*\/\s*\d{4}\s*-\s*\d{2})|(\d{3}\s*\.\s*\d{3}\s*\.\s*\d{3}\s*-\s*\d{2})/g;

  const matches = [...text.matchAll(pattern)];

  const foundDocs: {type: 'CNPJ' | 'CPF', val: string}[] = [];

  // Method A: Check Regex Matches
  for (const match of matches) {
      const [full] = match;
      const clean = full.replace(/\D/g, ''); // Remove spaces and symbols

      if (clean.length === 14) { // CNPJ
          foundDocs.push({ type: 'CNPJ', val: clean.substring(0, 8) }); // Root
      } else if (clean.length === 11) { // CPF
          foundDocs.push({ type: 'CPF', val: clean });
      }
  }

  // Method B: Brute Force check against Company DB
  // If regex failed (due to weird formatting), checking if the company's clean doc number exists in the text's digit stream
  for (const company of companies) {
      const companyDocClean = company.docNumber.replace(/\D/g, '');
      if (companyDocClean.length > 5 && textDigitsOnly.includes(companyDocClean)) {
           return company;
      }
  }

  // Check found regex docs against DB
  for (const item of foundDocs) {
      for (const company of companies) {
          const companyDocClean = company.docNumber.replace(/\D/g, '');

          if (item.type === 'CNPJ') {
              // Compare first 8 digits (Root)
              if (companyDocClean.length >= 8 && companyDocClean.startsWith(item.val)) {
                  return company;
              }
          } else {
              // CPF Exact match
              if (companyDocClean === item.val) {
                  return company;
              }
          }
      }
  }

  // 2. Fallback: Search by Name (removing accents)
  for (const company of companies) {
    const nameNormalized = removeAccents(company.name);
    // Split name into parts to avoid matching common words, match only if significant part matches
    // But for full name search:
    if (nameNormalized.length > 4 && textNormalized.includes(nameNormalized)) {
        return company;
    }
  }

  return null;
};

import React, { useState, useRef, useEffect } from 'react';
import { Upload, CalendarCheck, Search, FileText, Check, X, Play, Settings as SettingsIcon, Filter, FolderArchive, Loader2, FilePlus, AlertTriangle, Trash } from 'lucide-react';
import { DOCUMENT_CATEGORIES } from '../constants';
import { UserSettings, Document, Company, UploadedFile } from '../types';
import { identifyCategory, identifyCompany, extractTextFromPDF } from '../utils/documentProcessor';
import { api } from '../services/api';
import { calcularTodosVencimentos } from '../utils/dateHelpers';
import JSZip from 'jszip';

interface DocumentsProps {
  userSettings: UserSettings;
  onNavigateToUpload: (companyId: number, competence: string) => void;
  documents: Document[];
  onToggleStatus: (companyId: number, category: string, competence: string) => void;
  onUploadSuccess: (files: UploadedFile[], companyId: number, competence: string) => void;
}

interface PreviewFile {
  id: string; // Temp ID
  file: File;
  fileName: string;
  detectedCompanyId: number | null; // null if not found
  detectedCategory: string | ''; // empty if not found
  status: 'ready' | 'error' | 'ignored';
  size: number;
}

const Documents: React.FC<DocumentsProps> = ({ 
  userSettings, 
  onNavigateToUpload, 
  documents: initialDocuments,
  onToggleStatus,
  onUploadSuccess
}) => {
  const getCurrentCompetence = () => {
    const now = new Date();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const yyyy = now.getFullYear();
    return `${mm}/${yyyy}`;
  };

  const [competence, setCompetence] = useState(getCurrentCompetence());
  const [activeCompetence, setActiveCompetence] = useState(getCurrentCompetence());

  const [companies, setCompanies] = useState<Company[]>([]);
  const [dbStatuses, setDbStatuses] = useState<any[]>([]); 
  const [loading, setLoading] = useState(true);

  // Processing State
  const [localPath, setLocalPath] = useState('');
  const [processingCompetence, setProcessingCompetence] = useState(getCurrentCompetence());
  const [processing, setProcessing] = useState(false);
  const [isUploadingConfirmed, setIsUploadingConfirmed] = useState(false);

  // Processing Filters
  const [processingCompanyId, setProcessingCompanyId] = useState<string>('');
  const [processingCategoryFilter, setProcessingCategoryFilter] = useState<string>('');

  // Modal Preview State
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);

  const [matrixSearch, setMatrixSearch] = useState('');
  const [matrixStatusFilter, setMatrixStatusFilter] = useState<'all' | 'pending' | 'sent'>('all');
  const [matrixCategoryFilter, setMatrixCategoryFilter] = useState<string>('all');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchData = async () => {
      setLoading(true);
      try {
          const [comps, statuses] = await Promise.all([
              api.getCompanies(),
              api.getDocumentStatuses(activeCompetence)
          ]);
          setCompanies(comps);
          setDbStatuses(statuses);
      } catch (error) {
          console.error("Error fetching documents data", error);
      } finally {
          setLoading(false);
      }
  };

  useEffect(() => {
      fetchData();
  }, [activeCompetence]);

  const visibleMatrixCategories = userSettings.visibleDocumentCategories.length > 0 
    ? userSettings.visibleDocumentCategories 
    : DOCUMENT_CATEGORIES.slice(0, 8);

  const handleProcessClick = () => {
    if (fileInputRef.current) {
        fileInputRef.current.click();
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
        const files: File[] = Array.from(e.target.files);

        if (files.length === 1) {
            setLocalPath(files[0].name);
        } else {
            setLocalPath(`${files.length} arquivos selecionados`);
        }

        const zipFile = files.find(f => f.name.toLowerCase().endsWith('.zip') || f.name.toLowerCase().endsWith('.rar'));

        if (zipFile) {
             if (files.length > 1) {
                 alert("Ao selecionar um arquivo ZIP, selecione apenas ele.");
                 return;
             }
             await prepareZipFile(zipFile);
        } else {
             await prepareMultipleFiles(files);
        }
    }
  };

  const prepareMultipleFiles = async (fileList: File[]) => {
      setProcessing(true);
      const tempFiles: PreviewFile[] = [];

      for (const file of fileList) {
          // Default: use filename
          let textContent = file.name;

          // Force PDF extraction if extension is .pdf (ignore mime type which can be flaky)
          if (file.name.toLowerCase().endsWith('.pdf')) {
              try {
                const extracted = await extractTextFromPDF(file);
                // Concatenate extracted text to filename to give detection maximum context
                if (extracted && extracted.length > 5) {
                    textContent += " " + extracted;
                }
              } catch(e) { console.warn("PDF Read error", e); }
          }

          // Logic: If filter is selected, force it. Else, detect.
          let detectedCompanyId: number | null = null;
          if (processingCompanyId) {
              detectedCompanyId = Number(processingCompanyId);
          } else {
              const company = identifyCompany(textContent, companies);
              detectedCompanyId = company ? company.id : null;
          }

          let detectedCategory = '';
          if (processingCategoryFilter) {
              detectedCategory = processingCategoryFilter;
          } else {
              // Pass userSettings keywords to identifier
              detectedCategory = identifyCategory(textContent, userSettings.categoryKeywords) || '';
          }

          tempFiles.push({
              id: Math.random().toString(36).substr(2, 9),
              file: file,
              fileName: file.name,
              detectedCompanyId: detectedCompanyId,
              detectedCategory: detectedCategory, 
              status: 'ready',
              size: file.size
          });
      }

      setPreviewFiles(tempFiles);
      setProcessing(false);
      setShowPreviewModal(true);
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const prepareZipFile = async (zipFile: File) => {
      setProcessing(true);
      try {
        const zip = await JSZip.loadAsync(zipFile);
        const entries: {name: string, obj: any}[] = [];

        zip.forEach((relativePath, zipEntry) => {
            if (!zipEntry.dir && !zipEntry.name.startsWith('__MACOSX') && !zipEntry.name.endsWith('.DS_Store')) {
                entries.push({ name: zipEntry.name, obj: zipEntry });
            }
        });

        const tempFiles: PreviewFile[] = [];

        for (const entry of entries) {
            const fileName = entry.name;
            const simpleName = fileName.split('/').pop() || fileName;
            const blob = await entry.obj.async("blob");

            // Force type for PDF
            const type = simpleName.toLowerCase().endsWith('.pdf') ? 'application/pdf' : blob.type;
            const file = new File([blob], simpleName, { type });

            let textContent = simpleName; 

            if (simpleName.toLowerCase().endsWith('.pdf')) {
                 try {
                     const extracted = await extractTextFromPDF(file);
                     if (extracted && extracted.length > 5) {
                         textContent += " " + extracted;
                     }
                 } catch(e) {}
            }

            // Logic: Filter vs Detection
            let detectedCompanyId: number | null = null;
            if (processingCompanyId) {
                detectedCompanyId = Number(processingCompanyId);
            } else {
                const company = identifyCompany(textContent, companies);
                detectedCompanyId = company ? company.id : null;
            }

            let detectedCategory = '';
            if (processingCategoryFilter) {
                detectedCategory = processingCategoryFilter;
            } else {
                detectedCategory = identifyCategory(textContent, userSettings.categoryKeywords) || '';
            }

            tempFiles.push({
                id: Math.random().toString(36).substr(2, 9),
                file: file,
                fileName: simpleName,
                detectedCompanyId: detectedCompanyId,
                detectedCategory: detectedCategory,
                status: 'ready',
                size: file.size
            });
        }

        setPreviewFiles(tempFiles);
        setShowPreviewModal(true);

      } catch (error) {
          console.error("Error reading zip", error);
          alert("Erro ao ler o arquivo ZIP.");
      } finally {
          setProcessing(false);
          if (fileInputRef.current) fileInputRef.current.value = '';
      }
  };

  // Update preview file data
  const updatePreview = (id: string, field: 'detectedCompanyId' | 'detectedCategory', value: any) => {
      setPreviewFiles(prev => prev.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  const removePreview = (id: string) => {
      setPreviewFiles(prev => prev.filter(f => f.id !== id));
  };

  const confirmProcessing = async () => {
      setIsUploadingConfirmed(true);
      const calculatedDates = calcularTodosVencimentos(processingCompetence, userSettings.categoryRules);

      let processedCount = 0;

      for (const item of previewFiles) {
          if (!item.detectedCompanyId || !item.detectedCategory) continue;

          try {
              const uploadRes = await api.uploadFile(item.file);

              const uploadedFile: UploadedFile = {
                  name: item.fileName,
                  size: item.size,
                  category: item.detectedCategory,
                  dueDate: calculatedDates[item.detectedCategory] || '',
                  file: item.file,
                  serverFilename: uploadRes.filename
              };

              onUploadSuccess([uploadedFile], item.detectedCompanyId, processingCompetence);
              processedCount++;
          } catch (e) {
              console.error(`Falha upload ${item.fileName}`, e);
          }
      }

      setIsUploadingConfirmed(false);
      setShowPreviewModal(false);
      setPreviewFiles([]);
      alert(`${processedCount} arquivos processados e enviados para a aba de Envio.`);
      setLocalPath('');
  };


  // --- Matrix Logic & Filters ---
  const getStatus = (companyId: number, category: string) => {
      const dbStatus = dbStatuses.find(s => 
          s.companyId === companyId && 
          s.category === category && 
          s.competence === activeCompetence
      );
      if (dbStatus) return dbStatus.status;
      const doc = initialDocuments.find(d => 
        d.companyId === companyId && 
        d.category === category && 
        d.competence === activeCompetence
      );
      return doc ? doc.status : 'pending';
  };

  const handleToggleStatusLocal = async (companyId: number, category: string) => {
      const currentStatus = getStatus(companyId, category);
      const newStatus = currentStatus === 'sent' ? 'pending' : 'sent';
      const updatedDbStatuses = [...dbStatuses];
      const existingIdx = updatedDbStatuses.findIndex(s => s.companyId === companyId && s.category === category);
      if (existingIdx >= 0) {
