                    <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Categoria Alvo</label>
                    <select 
                      className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none"
                      value={selectedCategoryForKeyword}
                      onChange={(e) => setSelectedCategoryForKeyword(e.target.value)}
                    >
                      {DOCUMENT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="flex-[2] w-full">
                     <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Adicionar Nova Palavra-chave</label>
                     <input 
                        type="text" 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none"
                        placeholder="Ex: extrato mensal, das, nota fiscal..."
                        value={newKeyword}
                        onChange={(e) => setNewKeyword(e.target.value)}
                     />
                  </div>
                  <button 
                    onClick={addKeyword}
                    className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2"
                  >
                    <Plus className="w-4 h-4" /> Adicionar
                  </button>
               </div>

               {/* List Categories with Keywords Only */}
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 {DOCUMENT_CATEGORIES.map(category => {
                   const keywords = formData.categoryKeywords[category] || [];
                   const isPriority = (formData.priorityCategories || []).includes(category);

                   return (
                     <div key={category} className={`border rounded-lg overflow-hidden bg-white shadow-sm transition-all ${isPriority ? 'border-yellow-400 ring-1 ring-yellow-400' : 'border-gray-200'}`}>
                        <div className="bg-gray-50 px-4 py-3 border-b border-gray-200 font-bold text-gray-700 flex justify-between items-center">
                           <span>{category}</span>
                           <button 
                             onClick={() => togglePriority(category)}
                             className={`p-1 rounded hover:bg-gray-200 transition-colors ${isPriority ? 'text-yellow-500' : 'text-gray-300'}`}
                             title={isPriority ? "Remover Prioridade" : "Marcar como Prioridade"}
                           >
                               <Star className={`w-5 h-5 ${isPriority ? 'fill-yellow-500' : ''}`} />
                           </button>
                        </div>

                        <div className="p-4">
                           <div className="bg-gray-50 rounded border border-gray-200 p-2 min-h-[80px] space-y-2">
                            {keywords.length === 0 ? (
                                <p className="text-xs text-gray-400 italic p-2">Nenhuma palavra-chave definida.</p>
                            ) : (
                                keywords.map((kw, idx) => (
                                    <div key={idx} className="flex justify-between items-center bg-white border border-gray-200 rounded px-2 py-1">
                                    <span className="text-sm text-gray-700">{kw}</span>
                                    <button 
                                        onClick={() => removeKeyword(category, kw)}
                                        className="text-gray-400 hover:text-red-500 p-1"
                                        title="Remover palavra-chave"
                                    >
                                        <Trash className="w-3 h-3" />
                                    </button>
                                    </div>
                                ))
                            )}
                           </div>
                        </div>
                     </div>
                   );
                 })}
               </div>
            </div>
          )}

          {activeTab === 'due_dates' && (
              <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 space-y-8">
                  <div className="mb-6">
                    <h3 className="font-semibold text-gray-800">Regras de Vencimento</h3>
                    <p className="text-sm text-gray-500">Configure como o sistema calcula a data de vencimento para cada categoria de documento.</p>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {DOCUMENT_CATEGORIES.map(category => {
                       const rule = formData.categoryRules[category] || { day: 10, rule: 'fixo' };
                       return (
                          <div key={category} className="border border-gray-200 rounded-lg overflow-hidden bg-white shadow-sm">
                              <div className="bg-blue-50 px-4 py-3 border-b border-blue-100 font-bold text-blue-800 flex justify-between items-center">
                                  <span>{category}</span>
                                  <Clock className="w-4 h-4 text-blue-400" />
                              </div>
                              <div className="p-4 space-y-4">
                                  <div>
                                    <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Regra</label>
                                    <select 
                                      className="w-full text-sm border border-gray-300 rounded px-2 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                                      value={rule.rule}
                                      onChange={(e) => updateRule(category, 'rule', e.target.value)}
                                    >
                                      <option value="fixo">Dia Fixo</option>
                                      <option value="antecipado">Antecipar se Feriado/FDS</option>
                                      <option value="postergado">Postergar se Feriado/FDS</option>
                                      <option value="quinto_dia_util">Quinto Dia Útil</option>
                                      <option value="ultimo_dia_util">Último Dia Útil</option>
                                    </select>
                                  </div>

                                  {(rule.rule === 'fixo' || rule.rule === 'antecipado' || rule.rule === 'postergado') && (
                                    <div>
                                        <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Dia do Vencimento</label>
                                        <input 
                                          type="number" 
                                          min="1" 
                                          max="31" 
                                          className="w-full text-sm border border-gray-300 rounded px-2 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                                          value={rule.day}
                                          onChange={(e) => updateRule(category, 'day', parseInt(e.target.value))}
                                        />
                                    </div>
                                  )}

                                  <div className="bg-gray-50 p-2 rounded text-xs text-gray-500 border border-gray-100 min-h-[40px]">
                                    {rule.rule === 'quinto_dia_util' && "Vence no 5º dia útil do mês seguinte."}
                                    {rule.rule === 'ultimo_dia_util' && "Vence no último dia útil do mês seguinte."}
                                    {rule.rule === 'antecipado' && `Vence dia ${rule.day}. Se cair em feriado/FDS, antecipa.`}
                                    {rule.rule === 'postergado' && `Vence dia ${rule.day}. Se cair em feriado/FDS, posterga.`}
                                    {rule.rule === 'fixo' && `Vence dia ${rule.day}, independente de ser útil.`}
                                  </div>
                              </div>
                          </div>
                       );
                    })}
                  </div>
              </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useRef, useEffect } from 'react';
import { Upload, CalendarCheck, Search, FileText, Check, X, Play, Settings as SettingsIcon, Filter, FolderArchive, Loader2, FilePlus, AlertTriangle, Trash } from 'lucide-react';
import { DOCUMENT_CATEGORIES } from '../constants';
import { UserSettings, Document, Company, UploadedFile } from '../types';
import { identifyCategory, identifyCompany, extractTextFromPDF } from '../utils/documentProcessor';
import { api } from '../services/api';
import { calcularTodosVencimentos } from '../utils/dateHelpers';
import JSZip from 'jszip';

interface DocumentsProps {
  userSettings: UserSettings;
  onNavigateToUpload: (companyId: number, competence: string) => void;
  documents: Document[];
  onToggleStatus: (companyId: number, category: string, competence: string) => void;
  onUploadSuccess: (files: UploadedFile[], companyId: number, competence: string) => void;
}

interface PreviewFile {
  id: string; // Temp ID
  file: File;
  fileName: string;
  detectedCompanyId: number | null; // null if not found
  detectedCategory: string | ''; // empty if not found
  status: 'ready' | 'error' | 'ignored';
  size: number;
}

const Documents: React.FC<DocumentsProps> = ({ 
  userSettings, 
  onNavigateToUpload, 
  documents: initialDocuments,
  onToggleStatus,
  onUploadSuccess
}) => {
  const getCurrentCompetence = () => {
    const now = new Date();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const yyyy = now.getFullYear();
    return `${mm}/${yyyy}`;
  };

  const [competence, setCompetence] = useState(getCurrentCompetence());
  const [activeCompetence, setActiveCompetence] = useState(getCurrentCompetence());

  const [companies, setCompanies] = useState<Company[]>([]);
  const [dbStatuses, setDbStatuses] = useState<any[]>([]); 
  const [loading, setLoading] = useState(true);

  // Processing State
  const [localPath, setLocalPath] = useState('');
  const [processingCompetence, setProcessingCompetence] = useState(getCurrentCompetence());
  const [processing, setProcessing] = useState(false);
  const [isUploadingConfirmed, setIsUploadingConfirmed] = useState(false);

  // Processing Filters
  const [processingCompanyId, setProcessingCompanyId] = useState<string>('');
  const [processingCategoryFilter, setProcessingCategoryFilter] = useState<string>('');

  // Modal Preview State
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);

  const [matrixSearch, setMatrixSearch] = useState('');
  const [matrixStatusFilter, setMatrixStatusFilter] = useState<'all' | 'pending' | 'sent'>('all');
  const [matrixCategoryFilter, setMatrixCategoryFilter] = useState<string>('all');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchData = async () => {
      setLoading(true);
      try {
          const [comps, statuses] = await Promise.all([
              api.getCompanies(),
              api.getDocumentStatuses(activeCompetence)
          ]);
          setCompanies(comps);
          setDbStatuses(statuses);
      } catch (error) {
          console.error("Error fetching documents data", error);
      } finally {
          setLoading(false);
      }
  };

  useEffect(() => {
      fetchData();
  }, [activeCompetence]);

  const visibleMatrixCategories = userSettings.visibleDocumentCategories.length > 0 
    ? userSettings.visibleDocumentCategories 
    : DOCUMENT_CATEGORIES.slice(0, 8);

  const handleProcessClick = () => {
    if (fileInputRef.current) {
        fileInputRef.current.click();
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
        const files: File[] = Array.from(e.target.files);

        if (files.length === 1) {
            setLocalPath(files[0].name);
        } else {
            setLocalPath(`${files.length} arquivos selecionados`);
        }

        const zipFile = files.find(f => f.name.toLowerCase().endsWith('.zip') || f.name.toLowerCase().endsWith('.rar'));

        if (zipFile) {
             if (files.length > 1) {
                 alert("Ao selecionar um arquivo ZIP, selecione apenas ele.");
                 return;
             }
             await prepareZipFile(zipFile);
        } else {
             await prepareMultipleFiles(files);
        }
    }
  };

  const prepareMultipleFiles = async (fileList: File[]) => {
      setProcessing(true);
      const tempFiles: PreviewFile[] = [];

      for (const file of fileList) {
          // Default: use filename
          let textContent = file.name;

          // Force PDF extraction if extension is .pdf (ignore mime type which can be flaky)
          if (file.name.toLowerCase().endsWith('.pdf')) {
              try {
                const extracted = await extractTextFromPDF(file);
                // Concatenate extracted text to filename to give detection maximum context
                if (extracted && extracted.length > 5) {
                    textContent += " " + extracted;
                }
              } catch(e) { console.warn("PDF Read error", e); }
          }

          // Logic: If filter is selected, force it. Else, detect.
          let detectedCompanyId: number | null = null;
          if (processingCompanyId) {
              detectedCompanyId = Number(processingCompanyId);
          } else {
              const company = identifyCompany(textContent, companies);
              detectedCompanyId = company ? company.id : null;
          }

          let detectedCategory = '';
          if (processingCategoryFilter) {
              detectedCategory = processingCategoryFilter;
          } else {
              // Pass userSettings keywords to identifier, INCLUDING PRIORITY
              detectedCategory = identifyCategory(textContent, userSettings.categoryKeywords, userSettings.priorityCategories) || '';
          }

          tempFiles.push({
              id: Math.random().toString(36).substr(2, 9),
              file: file,
              fileName: file.name,
              detectedCompanyId: detectedCompanyId,
              detectedCategory: detectedCategory, 
              status: 'ready',
              size: file.size
          });
      }

      setPreviewFiles(tempFiles);
      setProcessing(false);
      setShowPreviewModal(true);
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const prepareZipFile = async (zipFile: File) => {
      setProcessing(true);
      try {
        const zip = await JSZip.loadAsync(zipFile);
        const entries: {name: string, obj: any}[] = [];

        zip.forEach((relativePath, zipEntry) => {
            if (!zipEntry.dir && !zipEntry.name.startsWith('__MACOSX') && !zipEntry.name.endsWith('.DS_Store')) {
                entries.push({ name: zipEntry.name, obj: zipEntry });
            }
        });

        const tempFiles: PreviewFile[] = [];

        for (const entry of entries) {
            const fileName = entry.name;
            const simpleName = fileName.split('/').pop() || fileName;
            const blob = await entry.obj.async("blob");

            // Force type for PDF
            const type = simpleName.toLowerCase().endsWith('.pdf') ? 'application/pdf' : blob.type;
            const file = new File([blob], simpleName, { type });

            let textContent = simpleName; 

            if (simpleName.toLowerCase().endsWith('.pdf')) {
                 try {
                     const extracted = await extractTextFromPDF(file);
                     if (extracted && extracted.length > 5) {
                         textContent += " " + extracted;
                     }
                 } catch(e) {}
            }

            // Logic: Filter vs Detection
            let detectedCompanyId: number | null = null;
            if (processingCompanyId) {
                detectedCompanyId = Number(processingCompanyId);
            } else {
                const company = identifyCompany(textContent, companies);
                detectedCompanyId = company ? company.id : null;
            }

            let detectedCategory = '';
            if (processingCategoryFilter) {
                detectedCategory = processingCategoryFilter;
            } else {
                detectedCategory = identifyCategory(textContent, userSettings.categoryKeywords, userSettings.priorityCategories) || '';
            }

            tempFiles.push({
                id: Math.random().toString(36).substr(2, 9),
                file: file,
                fileName: simpleName,
                detectedCompanyId: detectedCompanyId,
                detectedCategory: detectedCategory,
                status: 'ready',
                size: file.size
            });
        }

        setPreviewFiles(tempFiles);
        setShowPreviewModal(true);

      } catch (error) {
          console.error("Error reading zip", error);
          alert("Erro ao ler o arquivo ZIP.");
      } finally {
          setProcessing(false);
          if (fileInputRef.current) fileInputRef.current.value = '';
      }
  };

  // Update preview file data
  const updatePreview = (id: string, field: 'detectedCompanyId' | 'detectedCategory', value: any) => {
      setPreviewFiles(prev => prev.map(f => f.id === id ? { ...f, [field]: value } : f));
  };

  const removePreview = (id: string) => {
      setPreviewFiles(prev => prev.filter(f => f.id !== id));
  };

  const confirmProcessing = async () => {
      setIsUploadingConfirmed(true);
      const calculatedDates = calcularTodosVencimentos(processingCompetence, userSettings.categoryRules);

      let processedCount = 0;

      for (const item of previewFiles) {
          if (!item.detectedCompanyId || !item.detectedCategory) continue;

          try {
              const uploadRes = await api.uploadFile(item.file);

              const uploadedFile: UploadedFile = {
                  name: item.fileName,
                  size: item.size,
                  category: item.detectedCategory,
                  dueDate: calculatedDates[item.detectedCategory] || '',
                  file: item.file,
                  serverFilename: uploadRes.filename
              };

              onUploadSuccess([uploadedFile], item.detectedCompanyId, processingCompetence);
              processedCount++;
          } catch (e) {
              console.error(`Falha upload ${item.fileName}`, e);
          }
      }

      setIsUploadingConfirmed(false);
      setShowPreviewModal(false);
      setPreviewFiles([]);
      alert(`${processedCount} arquivos processados e enviados para a aba de Envio.`);
      setLocalPath('');
  };


  // --- Matrix Logic & Filters ---
  const getStatus = (companyId: number, category: string) => {
      const dbStatus = dbStatuses.find(s => 
          s.companyId === companyId && 
          s.category === category && 
          s.competence === activeCompetence
      );
      if (dbStatus) return dbStatus.status;
      const doc = initialDocuments.find(d => 
        d.companyId === companyId && 
        d.category === category && 
        d.competence === activeCompetence
      );
      return doc ? doc.status : 'pending';
  };

  const handleToggleStatusLocal = async (companyId: number, category: string) => {
      const currentStatus = getStatus(companyId, category);
      const newStatus = currentStatus === 'sent' ? 'pending' : 'sent';
      const updatedDbStatuses = [...dbStatuses];
      const existingIdx = updatedDbStatuses.findIndex(s => s.companyId === companyId && s.category === category);
      if (existingIdx >= 0) {
          updatedDbStatuses[existingIdx].status = newStatus;
      } else {
          updatedDbStatuses.push({ companyId, category, competence: activeCompetence, status: newStatus });
      }
      setDbStatuses(updatedDbStatuses);
      try {
          await api.updateDocumentStatus(companyId, category, activeCompetence, newStatus);
          onToggleStatus(companyId, category, activeCompetence);
      } catch (e) {
          console.error("Failed to update status");
      }
  };

  const getMatrixCategories = () => {
      if (matrixCategoryFilter !== 'all') {
          return [matrixCategoryFilter];
      }
      return visibleMatrixCategories;
  };

  const getMatrixCompanies = () => {
      return companies.filter(company => {
          const matchesName = company.name.toLowerCase().includes(matrixSearch.toLowerCase());
          if (!matchesName) return false;
          if (matrixStatusFilter !== 'all') {
              const visibleCategories = getMatrixCategories();
              const hasMatchingStatus = visibleCategories.some(cat => {
                  const status = getStatus(company.id, cat);
                  return status === matrixStatusFilter;
              });
              if (!hasMatchingStatus) return false;
          }
          return true;
      });
  };

  const handleSearchCompetence = (e: React.FormEvent) => {
      e.preventDefault();
      setActiveCompetence(competence);
  };

  if (loading && companies.length === 0) {
     return <div className="flex justify-center p-10"><Loader2 className="w-8 h-8 animate-spin text-blue-600" /></div>;
  }

  return (
    <div className="space-y-6">

      {/* Competence Selection Card */}
      <div className="bg-white rounded-xl shadow-sm border-0 overflow-hidden mb-4">
        <div className="bg-blue-600 text-white py-3 px-6">
            <h5 className="mb-0 flex items-center gap-2 font-bold">
                <CalendarCheck className="w-5 h-5" /> Verificar Documentos por Competência (Normal)
            </h5>
        </div>
        <div className="p-6">
            <form onSubmit={handleSearchCompetence}>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1">
                        <label htmlFor="competencia" className="block text-sm font-semibold text-gray-700 mb-2">Digite a competência (MM/AAAA)</label>
                        <div className="relative">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">
                                <CalendarCheck className="w-5 h-5" />
                            </span>
                            <input 
                                type="text" 
                                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500" 
                                id="competencia" 
                                placeholder="Ex: 05/2023" 
                                value={competence}
                                onChange={(e) => {
                                    let val = e.target.value.replace(/\D/g, '');
                                    if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                                    setCompetence(val);
                                }}
                                required 
                            />
                        </div>
                    </div>
                    <div className="flex-1 md:flex-none md:w-48">
                        <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition-colors flex items-center justify-center gap-2 font-medium">
                            <Search className="w-4 h-4" /> Verificar
                        </button>
                    </div>
                </div>
            </form>
        </div>
      </div>

      {/* Automatic Processing Card */}
      <div className="bg-white rounded-xl shadow-sm border border-blue-100 overflow-hidden">
         <div className="bg-blue-50 p-4 border-b border-blue-100 flex items-center gap-2 text-blue-800">
            <SettingsIcon className="w-5 h-5" />
            <h3 className="font-bold">Processamento Automático</h3>
        </div>
        <div className="p-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">

                {/* Path Input */}
                <div className="lg:col-span-1">
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Arquivos (ZIP ou Múltiplos)</label>
                    <div className="input-group flex items-center border border-gray-300 rounded-lg overflow-hidden bg-white cursor-pointer hover:bg-gray-50" onClick={handleProcessClick}>
                         <span className="px-3 text-gray-400 bg-gray-50 border-r py-2"><FolderArchive className="w-4 h-4" /></span>
                         <input 
                            type="text" 
                            className="flex-1 px-3 py-2 outline-none text-sm cursor-pointer"
                            placeholder="Selecione arquivos ou ZIP..."
                            value={localPath}
                            readOnly
                         />
                         <input 
                            type="file" 
                            multiple
                            accept=".zip,.rar,.pdf,.png,.jpg,.jpeg,.doc,.docx"
                            ref={fileInputRef} 
                            className="hidden" 
                            onChange={handleFileSelect} 
                        />
                    </div>
                </div>

                {/* Processing Competence */}
                <div>
                   <label className="block text-sm font-semibold text-gray-700 mb-1">Competência do Processamento</label>
                   <input 
                        type="text" 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                        placeholder="MM/AAAA"
                        value={processingCompetence}
                        onChange={(e) => {
                            let val = e.target.value.replace(/\D/g, '');
                            if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                            setProcessingCompetence(val);
                        }}
                    />
                </div>

                {/* Filter Company */}
                <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Filtrar por Empresa</label>
                    <select 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                        value={processingCompanyId}
                        onChange={(e) => setProcessingCompanyId(e.target.value)}
                    >
                        <option value="">Automático (Identificar no PDF)</option>
                        {companies.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                    </select>
                </div>

                {/* Filter Category */}
                <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Filtrar por Categoria</label>
                    <select 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                        value={processingCategoryFilter}
                        onChange={(e) => setProcessingCategoryFilter(e.target.value)}
                    >
                        <option value="">Automático (Identificar no PDF)</option>
                        {DOCUMENT_CATEGORIES.map(cat => (
                            <option key={cat} value={cat}>{cat}</option>
                        ))}
                    </select>
                </div>
            </div>

            <div className="flex flex-col items-center">
                 <button 
                    onClick={handleProcessClick}
                    disabled={processing}
                    className="bg-blue-600 text-white px-8 py-3 rounded-lg hover:bg-blue-700 shadow-lg shadow-blue-500/20 font-bold flex items-center gap-2 disabled:opacity-70 transition-all"
                 >
                    {processing ? (
                        <><Loader2 className="animate-spin rounded-full h-4 w-4" /> Lendo e Analisando...</>
                    ) : (
                        <><Play className="w-5 h-5" /> Iniciar Processamento Automático</>
                    )}
                 </button>
            </div>
        </div>
      </div>

      {/* Preview Modal */}
      {showPreviewModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl w-full max-w-5xl max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl">
                    <h3 className="font-bold text-gray-800 flex items-center gap-2">
                        <FilePlus className="w-5 h-5 text-blue-600" />
                        Pré-visualização do Processamento
                    </h3>
