import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Kanban from './components/Kanban';
import Companies from './components/Companies';
import WhatsAppConnect from './components/WhatsAppConnect';
import Documents from './components/Documents';
import Upload from './components/Upload';
import BulkSend from './components/BulkSend';
import ScheduledMessages from './components/ScheduledMessages';
import Settings from './components/Settings';
import Send from './components/Send'; 
import Login from './components/Login';
import { DEFAULT_USER_SETTINGS, MOCK_DOCUMENTS } from './constants';
import { UserSettings, Document, UploadedFile } from './types';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activePage, setActivePage] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Lifted state for User Settings
  const [userSettings, setUserSettings] = useState<UserSettings>(DEFAULT_USER_SETTINGS);

  // Lifted state for Documents (Shared between Documents, Upload, and Send)
  const [documents, setDocuments] = useState<Document[]>(MOCK_DOCUMENTS);

  // State for pre-filling Upload form
  const [uploadPreFill, setUploadPreFill] = useState<{companyId: number, competence: string} | null>(null);

  // Check for stored token on mount
  useEffect(() => {
    const token = localStorage.getItem('cm_auth_token');
    if (token) {
        setIsAuthenticated(true);
    }
  }, []);

  const handleLoginSuccess = (token?: string, remember?: boolean) => {
      if (remember && token) {
          localStorage.setItem('cm_auth_token', token);
      }
      setIsAuthenticated(true);
  };

  const handleLogout = () => {
      localStorage.removeItem('cm_auth_token');
      setIsAuthenticated(false);
      setActivePage('dashboard');
  };

  if (!isAuthenticated) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  const handleNavigateToUpload = (companyId: number, competence: string) => {
    setUploadPreFill({ companyId, competence });
    setActivePage('upload');
  };

  const handleNavigateToDocuments = () => {
    setActivePage('documents');
  }

  // Handle new file upload from Upload tab
  const handleUploadSuccess = (files: UploadedFile[], companyId: number, competence: string) => {
      const newDocs: Document[] = files.map(f => ({
          id: Date.now() + Math.random(),
          name: f.name,
          category: f.category,
          competence: competence,
          dueDate: f.dueDate,
          status: 'pending', 
          companyId: companyId,
          companyName: 'Loading...', // Should be resolved locally or via api fetch if critical
          file: f.file,
          serverFilename: f.serverFilename // Crucial for sending
      }));
      setDocuments(prev => [...prev, ...newDocs]);
  };

  // Toggle status in Matrix (Visual manual override)
  const handleToggleStatus = (companyId: number, category: string, competence: string) => {
      setDocuments(prev => {
          const existingIndex = prev.findIndex(d => 
              d.companyId === companyId && 
              d.category === category && 
              d.competence === competence
          );

          if (existingIndex >= 0) {
              // Toggle existing
              const newDocs = [...prev];
              newDocs[existingIndex] = {
                  ...newDocs[existingIndex],
                  status: newDocs[existingIndex].status === 'sent' ? 'pending' : 'sent'
              };
              return newDocs;
          } else {
              // Create manual entry
              const newDoc: Document = {
                  id: Date.now(),
                  name: `Manual - ${category}`,
                  category: category,
                  competence: competence,
                  dueDate: '',
                  status: 'sent', 
                  companyId: companyId,
                  companyName: 'Manual Entry',
                  isManual: true
              };
              return [...prev, newDoc];
          }
      });
  };

  // Handle Sending from Send Tab
  const handleSendDocuments = (docIds: number[]) => {
      // Aqui só atualizamos status, não removemos se falhar.
      setDocuments(prev => prev.map(doc => {
          if (docIds.includes(doc.id)) {
              return { ...doc, status: 'sent' };
          }
          return doc;
      }));
  };

  // Handle Delete Single Document
  const handleDeleteDocument = (id: number) => {
      if(window.confirm("Tem certeza que deseja remover este arquivo da lista de envio?")) {
          setDocuments(prev => prev.filter(d => d.id !== id));
      }
  };

  // Handle Clear All Pending Documents (for current view usually, but here clears all pending)
  const handleClearPendingDocuments = (competenceFilter: string) => {
      if(window.confirm(`Tem certeza que deseja excluir TODOS os arquivos pendentes da competência ${competenceFilter}?`)) {
          setDocuments(prev => prev.filter(d => !(d.status === 'pending' && d.competence === competenceFilter)));
      }
  };

  const renderContent = () => {
    switch (activePage) {
      case 'dashboard':
        return <Dashboard />;
      case 'companies':
        return <Companies />;
      case 'whatsapp':
        return <WhatsAppConnect />;
      case 'documents':
        return <Documents 
                  userSettings={userSettings} 
                  onNavigateToUpload={handleNavigateToUpload}
                  documents={documents}
                  onToggleStatus={handleToggleStatus}
                  onUploadSuccess={handleUploadSuccess}
               />;
      case 'upload':
        return <Upload 
                  preFillData={uploadPreFill} 
                  onUploadSuccess={handleUploadSuccess}
                  userSettings={userSettings}
               />;
      case 'send':
        return <Send 
                  documents={documents}
                  onSendDocuments={handleSendDocuments}
                  onNavigateToDocuments={handleNavigateToDocuments}
                  userSettings={userSettings}
                  onDeleteDocument={handleDeleteDocument}
                  onClearPendingDocuments={handleClearPendingDocuments}
               />;
      case 'bulksend':
        return <BulkSend />;
      case 'scheduled':
        return <ScheduledMessages />;
      case 'settings':
        return <Settings settings={userSettings} onSave={setUserSettings} />;
      default:
        return (
          <div className="flex flex-col items-center justify-center h-[50vh] text-gray-400">
            <h2 className="text-xl font-semibold mb-2">Em Construção</h2>
            <p>A página {activePage} será implementada em breve.</p>
          </div>
        );
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <Sidebar 
        activePage={activePage} 
        setActivePage={setActivePage} 
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
        onLogout={handleLogout}
      />

      <main className="flex-1 overflow-auto w-full relative">
        <header className="bg-white border-b border-gray-200 px-6 py-4 flex justify-between items-center sticky top-0 z-30">
          <h2 className="text-lg font-semibold text-gray-700 capitalize">
            {activePage === 'bulksend' ? 'Envio em Massa' : activePage === 'settings' ? 'Usuário' : activePage === 'send' ? 'Envio' : activePage}
          </h2>
          <div className="flex items-center gap-4">
             <div className="text-sm text-right hidden sm:block">
                <p className="font-bold text-gray-700">Lucas Araújo</p>
                <p className="text-gray-500 text-xs">Contador | CRC-BA 046968/O</p>
             </div>
             <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-700 font-bold border-2 border-white shadow-sm">
                LA
             </div>
          </div>
        </header>

        <div className="p-6 max-w-7xl mx-auto pb-20">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Send as SendIcon, Mail, MessageCircle, FileText, Trash, Clock, Check, Info, ArrowLeft, X, CheckSquare, Calendar, Loader2 } from 'lucide-react';
import { Document, Company, UserSettings } from '../types';
import { api } from '../services/api';

interface SendProps {
  documents: Document[];
  onSendDocuments: (ids: number[]) => void;
  onNavigateToDocuments: () => void;
  userSettings: UserSettings;
  onDeleteDocument: (id: number) => void;
  onClearPendingDocuments: (competence: string) => void;
}

const Send: React.FC<SendProps> = ({ documents, onSendDocuments, onNavigateToDocuments, userSettings, onDeleteDocument, onClearPendingDocuments }) => {
  const getCurrentCompetence = () => {
    const now = new Date();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const yyyy = now.getFullYear();
    return `${mm}/${yyyy}`;
  };

  const [competence, setCompetence] = useState(getCurrentCompetence());
  const [subject, setSubject] = useState('Folha de Pagamento');
  // Mensagem padrão fixa conforme solicitado
  const [message, setMessage] = useState('Segue em anexo os seguintes documentos:');
  const [sendEmail, setSendEmail] = useState(true);
  const [sendWhatsapp, setSendWhatsapp] = useState(false);
  const [selectedDocs, setSelectedDocs] = useState<number[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleDate, setScheduleDate] = useState('');
  const [scheduleChannels, setScheduleChannels] = useState({ email: true, whatsapp: false });
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loadingCompanies, setLoadingCompanies] = useState(false);

  useEffect(() => {
    setLoadingCompanies(true);
    api.getCompanies()
        .then(data => setCompanies(data))
        .catch(err => console.error(err))
        .finally(() => setLoadingCompanies(false));
  }, []);

  const pendingDocs = documents.filter(doc => doc.status === 'pending' && doc.competence === competence);

  const docsByCompany = pendingDocs.reduce((acc, doc) => {
    if (!acc[doc.companyId]) acc[doc.companyId] = [];
    acc[doc.companyId].push(doc);
    return acc;
  }, {} as Record<number, Document[]>);

  const getCompanyDetails = (id: number) => companies.find(c => c.id === id);

  const toggleDocSelection = (id: number) => {
    setSelectedDocs(prev => prev.includes(id) ? prev.filter(d => d !== id) : [...prev, id]);
  };

  const toggleCompanySelection = (companyId: number, companyDocs: Document[]) => {
    const allSelected = companyDocs.every(d => selectedDocs.includes(d.id));
    if (allSelected) {
      const idsToRemove = companyDocs.map(d => d.id);
      setSelectedDocs(prev => prev.filter(id => !idsToRemove.includes(id)));
    } else {
      const idsToAdd = companyDocs.map(d => d.id);
      setSelectedDocs(prev => [...new Set([...prev, ...idsToAdd])]);
    }
  };

  const toggleSelectGlobal = () => {
      const allPendingIds = pendingDocs.map(d => d.id);
      const allSelected = allPendingIds.length > 0 && allPendingIds.every(id => selectedDocs.includes(id));
      if (allSelected) setSelectedDocs([]);
      else setSelectedDocs(allPendingIds);
  };

  const handleSend = async () => {
    if (selectedDocs.length === 0) {
      alert('Selecione pelo menos um documento para enviar.');
      return;
    }
    if (!sendEmail && !sendWhatsapp) {
      alert('Selecione pelo menos um método de envio (E-mail ou WhatsApp).');
      return;
    }

    setIsProcessing(true);

    // Prepare payload for API
    const docsToSend = documents
        .filter(d => selectedDocs.includes(d.id))
        .map(d => ({
            id: d.id, // Enviar ID para o servidor retornar em caso de sucesso
            companyId: d.companyId,
            companyName: d.companyName,
            serverFilename: d.serverFilename || d.name, // Deve existir se foi feito upload correto
            docName: d.name,
            category: d.category,
            competence: d.competence,
            dueDate: d.dueDate // Importante para a tabela do e-mail
        }));

    try {
        const result = await api.sendDocuments({
            documents: docsToSend,
            subject,
            messageBody: message,
            channels: { email: sendEmail, whatsapp: sendWhatsapp },
            emailSignature: userSettings.emailSignature,
            whatsappTemplate: userSettings.whatsappTemplate // Passamos a assinatura configurada como template
        });

        if (result.success) {
            // Remove apenas os que o servidor confirmou que enviou (ou tentou processar com sucesso parcial)
            const successIds = result.sentIds || [];

            if (successIds.length > 0) {
                onSendDocuments(successIds);
                // Atualiza seleção removendo os enviados
                setSelectedDocs(prev => prev.filter(id => !successIds.includes(id)));
            }

            alert(`Processamento finalizado!\nSucessos: ${result.sent}\nErros: ${result.errors.length}\n${result.errors.length > 0 ? 'Verifique os logs no servidor para detalhes.' : ''}`);

            if (result.errors.length > 0) {
                console.warn("Erros detalhados:", result.errors);
            }
        } else {
            alert("Erro ao processar envio no servidor.");
        }

    } catch (e) {
        console.error(e);
        alert("Erro de comunicação com o servidor.");
    } finally {
        setIsProcessing(false);
    }
  };

  const handleOpenSchedule = () => {
     if (selectedDocs.length === 0) { alert('Selecione pelo menos um documento.'); return; }
     setScheduleChannels({ email: sendEmail, whatsapp: sendWhatsapp });
     setShowScheduleModal(true);
  };

  const confirmSchedule = () => {
      if (!scheduleDate) { alert("Selecione data e hora."); return; }
      alert(`Agendamento simulado para ${scheduleDate}. Backend precisa de implementação cron.`);
      setShowScheduleModal(false);
  }

  const allPendingIds = pendingDocs.map(d => d.id);
  const isGlobalSelected = allPendingIds.length > 0 && allPendingIds.every(id => selectedDocs.includes(id));

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
            <SendIcon className="w-6 h-6 text-blue-600" /> Envio de Documentos
            <span className="text-base font-normal text-gray-500">- Competência: {competence}</span>
        </h2>
      </div>

      <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-lg flex items-center gap-2">
         <MessageCircle className="w-5 h-5" /> 
         Status WhatsApp: <span className="text-green-600 font-bold">Conectado</span>
