                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                        placeholder="MM/AAAA"
                        value={processingCompetence}
                        onChange={(e) => {
                            let val = e.target.value.replace(/\D/g, '');
                            if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                            setProcessingCompetence(val);
                        }}
                    />
                </div>

                {/* Filter Company */}
                <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Filtrar por Empresa</label>
                    <select 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                        value={processingCompanyId}
                        onChange={(e) => setProcessingCompanyId(e.target.value)}
                    >
                        <option value="">Automático (Identificar no PDF)</option>
                        {companies.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                    </select>
                </div>

                {/* Filter Category */}
                <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Filtrar por Categoria</label>
                    <select 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                        value={processingCategoryFilter}
                        onChange={(e) => setProcessingCategoryFilter(e.target.value)}
                    >
                        <option value="">Automático (Identificar no PDF)</option>
                        {DOCUMENT_CATEGORIES.map(cat => (
                            <option key={cat} value={cat}>{cat}</option>
                        ))}
                    </select>
                </div>
            </div>

            <div className="flex flex-col items-center">
                 <button 
                    onClick={handleProcessClick}
                    disabled={processing}
                    className="bg-blue-600 text-white px-8 py-3 rounded-lg hover:bg-blue-700 shadow-lg shadow-blue-500/20 font-bold flex items-center gap-2 disabled:opacity-70 transition-all"
                 >
                    {processing ? (
                        <><Loader2 className="animate-spin rounded-full h-4 w-4" /> Lendo e Analisando...</>
                    ) : (
                        <><Play className="w-5 h-5" /> Iniciar Processamento Automático</>
                    )}
                 </button>
            </div>
        </div>
      </div>

      {/* Preview Modal */}
      {showPreviewModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl w-full max-w-5xl max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl">
                    <h3 className="font-bold text-gray-800 flex items-center gap-2">
                        <FilePlus className="w-5 h-5 text-blue-600" />
                        Pré-visualização do Processamento
                    </h3>
                    <button onClick={() => { setShowPreviewModal(false); setPreviewFiles([]); }} className="text-gray-400 hover:text-gray-600">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <div className="p-4 bg-yellow-50 border-b border-yellow-100 text-sm text-yellow-800 flex items-start gap-2">
                    <AlertTriangle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                    <div>
                        Verifique se a Empresa e a Categoria foram identificadas corretamente. 
                        Arquivos sem Empresa <strong>não serão processados</strong>.
                    </div>
                </div>

                <div className="flex-1 overflow-auto p-0">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-50 text-gray-600 sticky top-0 z-10 shadow-sm">
                            <tr>
                                <th className="px-4 py-3">Arquivo</th>
                                <th className="px-4 py-3 w-1/3">Empresa Vinculada</th>
                                <th className="px-4 py-3 w-1/4">Categoria</th>
                                <th className="px-4 py-3 w-10 text-center">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {previewFiles.map((item) => (
                                <tr key={item.id} className="hover:bg-gray-50 group">
                                    <td className="px-4 py-3 font-medium text-gray-700 truncate max-w-[200px]" title={item.fileName}>
                                        {item.fileName}
                                    </td>
                                    <td className="px-4 py-3">
                                        <select 
                                            className={`w-full border rounded px-2 py-1 text-sm outline-none focus:ring-1 focus:ring-blue-500
                                                ${!item.detectedCompanyId ? 'border-red-300 bg-red-50' : 'border-gray-300'}`}
                                            value={item.detectedCompanyId || ''}
                                            onChange={(e) => updatePreview(item.id, 'detectedCompanyId', Number(e.target.value) || null)}
                                        >
                                            <option value="">-- Selecione a Empresa --</option>
                                            {companies.map(c => (
                                                <option key={c.id} value={c.id}>{c.name} ({c.docNumber})</option>
                                            ))}
                                        </select>
                                    </td>
                                    <td className="px-4 py-3">
                                        <select 
                                            className={`w-full border rounded px-2 py-1 text-sm outline-none focus:ring-1 focus:ring-blue-500
                                                ${!item.detectedCategory ? 'border-yellow-300 bg-yellow-50' : 'border-gray-300'}`}
                                            value={item.detectedCategory}
                                            onChange={(e) => updatePreview(item.id, 'detectedCategory', e.target.value)}
                                        >
                                            {/* Se estiver vazio, exibe como "Outros" implícito ou selecionável */}
                                            <option value="Outros">Outros</option>
                                            {DOCUMENT_CATEGORIES.map(cat => (
                                                <option key={cat} value={cat}>{cat}</option>
                                            ))}
                                        </select>
                                    </td>
                                    <td className="px-4 py-3 text-center">
                                        <button 
                                            onClick={() => removePreview(item.id)}
                                            className="text-red-400 hover:text-red-600 p-1 rounded hover:bg-red-50"
                                            title="Remover arquivo"
                                        >
                                            <Trash className="w-4 h-4" />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                            {previewFiles.length === 0 && (
                                <tr><td colSpan={4} className="text-center py-8 text-gray-500">Nenhum arquivo válido encontrado.</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>

                <div className="p-4 border-t border-gray-100 bg-gray-50 rounded-b-xl flex justify-between items-center">
                    <div className="text-sm text-gray-600">
                        Total: <strong>{previewFiles.length}</strong> arquivos.
                    </div>
                    <div className="flex gap-3">
                        <button 
                            onClick={() => { setShowPreviewModal(false); setPreviewFiles([]); }} 
                            className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-100 font-medium"
                        >
                            Cancelar
                        </button>
                        <button 
                            onClick={confirmProcessing}
                            disabled={isUploadingConfirmed || previewFiles.length === 0}
                            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold flex items-center gap-2 disabled:opacity-70"
                        >
                            {isUploadingConfirmed ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
                            Confirmar e Processar
                        </button>
                    </div>
                </div>
            </div>
        </div>
      )}

      {/* Document Matrix Section */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">

        <div className="p-4 border-b border-gray-100 bg-gray-50">
           {/* Filters Bar */}
           <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold text-gray-700">
                Matriz de Status - <span className="text-blue-600">{activeCompetence}</span>
              </h3>
              <div className="flex gap-3 text-sm">
                <span className="flex items-center gap-1 text-green-600"><Check className="w-4 h-4" /> Enviado</span>
                <span className="flex items-center gap-1 text-red-500"><X className="w-4 h-4" /> Pendente</span>
              </div>
           </div>

           <div className="flex flex-col md:flex-row gap-4 p-3 bg-white border border-gray-200 rounded-lg">
              <div className="flex-1">
                 <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Buscar Empresa</label>
                 <div className="relative">
                    <Search className="w-4 h-4 absolute left-2 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input 
                      type="text" 
                      className="w-full pl-8 pr-3 py-1.5 border border-gray-300 rounded text-sm outline-none focus:ring-1 focus:ring-blue-500"
                      placeholder="Nome da empresa..."
                      value={matrixSearch}
                      onChange={(e) => setMatrixSearch(e.target.value)}
                    />
                 </div>
              </div>
              <div className="flex-1">
                 <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Filtrar Categoria</label>
                 <select 
                   className="w-full border border-gray-300 rounded px-2 py-1.5 text-sm outline-none"
                   value={matrixCategoryFilter}
                   onChange={(e) => setMatrixCategoryFilter(e.target.value)}
                 >
                   <option value="all">Todas as Categorias</option>
                   {visibleMatrixCategories.map(cat => (
                     <option key={cat} value={cat}>{cat}</option>
                   ))}
                 </select>
              </div>
              <div className="flex-1">
                 <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">Filtrar Status</label>
                 <select 
                   className="w-full border border-gray-300 rounded px-2 py-1.5 text-sm outline-none"
                   value={matrixStatusFilter}
                   onChange={(e) => setMatrixStatusFilter(e.target.value as any)}
                 >
                   <option value="all">Todos</option>
                   <option value="pending">Pendente (Exibir se houver)</option>
                   <option value="sent">Enviado (Exibir se houver)</option>
                 </select>
              </div>
           </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-200">
                <th className="px-6 py-4 text-left font-semibold text-gray-600 bg-gray-50 min-w-[200px] sticky left-0 shadow-sm z-10">Empresa</th>
                {getMatrixCategories().map(cat => (
                  <th key={cat} className="px-4 py-4 text-center font-semibold text-gray-600 min-w-[100px]">{cat}</th>
                ))}
                <th className="px-4 py-4 text-center font-semibold text-gray-600 bg-gray-50 min-w-[100px] sticky right-0 shadow-sm z-10 border-l">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {getMatrixCompanies().map((company) => (
                <tr key={company.id} className="hover:bg-gray-50 group">
                  <td className="px-6 py-4 font-medium text-gray-900 bg-white group-hover:bg-gray-50 sticky left-0 shadow-sm">
                    {company.name}
                  </td>
                  {getMatrixCategories().map((cat) => {
                     const status = getStatus(company.id, cat);
                     const isSent = status === 'sent';
                     return (
                      <td key={cat} className="px-4 py-4 text-center">
                        <button 
                            onClick={() => handleToggleStatusLocal(company.id, cat)}
                            className={`w-8 h-8 rounded-full inline-flex items-center justify-center transition-all duration-200 cursor-pointer
                            ${isSent 
                                ? 'bg-green-100 text-green-600 hover:bg-green-200 hover:scale-110' 
                                : 'bg-red-50 text-red-500 hover:bg-red-100 hover:scale-110'}`}
                            title={isSent ? 'Clique para marcar como Pendente' : 'Clique para marcar como Enviado'}
                        >
                            {isSent ? <Check className="w-4 h-4" /> : <X className="w-4 h-4" />}
                        </button>
                      </td>
                     );
                  })}
                  <td className="px-4 py-4 text-center bg-white group-hover:bg-gray-50 sticky right-0 shadow-sm border-l">
                      <button 
                        onClick={() => onNavigateToUpload(company.id, activeCompetence)}
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                        title="Fazer Upload para esta empresa"
                      >
                          <Upload className="w-5 h-5" />
                      </button>
                  </td>
                </tr>
              ))}
              {getMatrixCompanies().length === 0 && (
                <tr>
                   <td colSpan={getMatrixCategories().length + 2} className="px-6 py-8 text-center text-gray-500">
                      Nenhuma empresa encontrada com os filtros selecionados.
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Documents;

import React, { useState, useEffect } from 'react';
import { Upload as UploadIcon, X, FileText, Calendar, AlertCircle, Loader2 } from 'lucide-react';
import { DOCUMENT_CATEGORIES } from '../constants';
import { calcularTodosVencimentos } from '../utils/dateHelpers';
import { UploadedFile, Company, UserSettings } from '../types';
import { api } from '../services/api';
import { identifyCategory, extractTextFromPDF, removeAccents } from '../utils/documentProcessor'; 
import { DEFAULT_USER_SETTINGS } from '../constants';

interface UploadProps {
  preFillData?: {
    companyId: number;
    competence: string;
  } | null;
  onUploadSuccess: (files: UploadedFile[], companyId: number, competence: string) => void;
  userSettings?: UserSettings; 
}

const Upload: React.FC<UploadProps> = ({ preFillData, onUploadSuccess, userSettings = DEFAULT_USER_SETTINGS }) => {
  const [competence, setCompetence] = useState('');
  const [selectedCompanyId, setSelectedCompanyId] = useState<number | string>('');
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [calculatedDates, setCalculatedDates] = useState<Record<string, string>>({});
  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const [companies, setCompanies] = useState<Company[]>([]);
  const [loadingCompanies, setLoadingCompanies] = useState(false);

  useEffect(() => {
    setLoadingCompanies(true);
    api.getCompanies()
        .then(data => setCompanies(data))
        .catch(err => console.error("Erro ao buscar empresas", err))
        .finally(() => setLoadingCompanies(false));

    if (preFillData) {
      setCompetence(preFillData.competence);
      setSelectedCompanyId(preFillData.companyId);
    } else {
      const now = new Date();
      const mm = String(now.getMonth() + 1).padStart(2, '0');
      const yyyy = now.getFullYear();
      setCompetence(`${mm}/${yyyy}`);
    }
  }, [preFillData]);

  useEffect(() => {
    if (competence.match(/^\d{2}\/\d{4}$/)) {
        const dates = calcularTodosVencimentos(competence, userSettings.categoryRules);
        setCalculatedDates(dates);
        setFiles(prev => prev.map(f => {
            if (dates[f.category]) {
                return { ...f, dueDate: dates[f.category] };
            }
            return f;
        }));
    }
  }, [competence, userSettings]);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    processFiles(Array.from(e.dataTransfer.files));
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      processFiles(Array.from(e.target.files));
    }
  };

  const processFiles = async (fileList: File[]) => {
    setIsProcessing(true);

    // Process files sequentially or in parallel, but await text extraction
    const newFiles: UploadedFile[] = [];

    for (const file of fileList) {
        let pdfText = "";

        // Se for PDF, tenta extrair o texto
        if (file.type === 'application/pdf') {
            try {
                pdfText = await extractTextFromPDF(file);
            } catch (err) {
                console.warn(`Erro lendo PDF ${file.name}`, err);
            }
        }

        // NORMALIZAÇÃO UNIFICADA
        const textForAnalysis = removeAccents((pdfText + " " + file.name).toLowerCase());

        // Pass user settings priority
        // Assume normalized text input now
        const identified = identifyCategory(textForAnalysis, userSettings.categoryKeywords, userSettings.priorityCategories);

        let category = identified ?? 'Outros';

        let dueDate = '';
        if (category && calculatedDates[category]) {
            dueDate = calculatedDates[category];
        }

        newFiles.push({
            name: file.name,
            size: file.size,
            category: category,
            dueDate: dueDate,
            file: file
        });
    }

    setFiles(prev => [...prev, ...newFiles]);
    setIsProcessing(false);
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const updateFileCategory = (index: number, newCategory: string) => {
    setFiles(prev => prev.map((f, i) => {
        if (i === index) {
            const newDate = calculatedDates[newCategory] || f.dueDate;
            return { ...f, category: newCategory, dueDate: newDate };
        }
        return f;
    }));
  };

  const handleUploadClick = async () => {
    if (!selectedCompanyId || !competence) {
        alert('Selecione uma empresa e uma competência');
        return;
    }

    setIsUploading(true);
    try {
        const uploadedFilesWithServerNames = await Promise.all(files.map(async (f) => {
            const res = await api.uploadFile(f.file);
            return {
                ...f,
                serverFilename: res.filename
            };
        }));

        onUploadSuccess(uploadedFilesWithServerNames, Number(selectedCompanyId), competence);

        setFiles([]);
        setIsSuccess(true);
        setTimeout(() => setIsSuccess(false), 3000);
    } catch (error) {
        console.error("Erro no upload", error);
        alert("Erro ao enviar arquivos para o servidor.");
    } finally {
        setIsUploading(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Upload de Documentos</h1>
          <p className="text-gray-500">Envie arquivos e o sistema calculará os vencimentos automaticamente.</p>
        </div>
      </div>

      {isSuccess && (
        <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded relative" role="alert">
            <strong className="font-bold">Sucesso!</strong>
            <span className="block sm:inline"> Arquivos enviados com sucesso para a aba de Envio.</span>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-fit">
            <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2">
                <AlertCircle className="w-5 h-5 text-blue-500" /> Informações Básicas
            </h3>
            <div className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2">
                        Empresa {loadingCompanies && <Loader2 className="w-3 h-3 animate-spin" />}
                    </label>
                    <select 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-100"
                        value={selectedCompanyId}
                        onChange={e => setSelectedCompanyId(e.target.value)}
                        disabled={loadingCompanies}
                    >
                        <option value="">Selecione uma empresa...</option>
                        {companies.map(c => (
                            <option key={c.id} value={c.id}>{c.name} ({c.docNumber})</option>
                        ))}
                    </select>
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Competência (MM/AAAA)</label>
                    <input 
                        type="text"
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
                        placeholder="MM/AAAA"
                        value={competence}
                        onChange={e => {
                            let val = e.target.value.replace(/\D/g, '');
                            if (val.length > 2) val = val.substring(0, 2) + '/' + val.substring(2, 6);
                            setCompetence(val);
                        }}
                    />
                </div>
            </div>
        </div>

        <div 
            className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center transition-colors
                ${isDragging ? 'border-blue-500 bg-blue-50' : 'border-gray-300 hover:border-blue-400 bg-gray-50'}`}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
        >
            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mb-4">
                <UploadIcon className="w-8 h-8 text-blue-600" />
            </div>
            <h3 className="text-lg font-semibold text-gray-800">Arraste arquivos aqui</h3>
            <p className="text-gray-500 mb-4">ou clique para selecionar do computador</p>
            <input type="file" multiple className="hidden" id="file-input" onChange={handleFileSelect} />
            <label htmlFor="file-input" className="bg-blue-600 text-white px-6 py-2 rounded-lg cursor-pointer hover:bg-blue-700 transition-colors">
                Selecionar Arquivos
            </label>
        </div>
      </div>

      {isProcessing && (
          <div className="text-center p-4">
              <Loader2 className="w-8 h-8 animate-spin mx-auto text-blue-500" />
              <p className="text-sm text-gray-500 mt-2">Lendo arquivos e identificando categorias...</p>
          </div>
      )}

      {files.length > 0 && !isProcessing && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-4 border-b border-gray-100 bg-gray-50">
                  <h3 className="font-bold text-gray-700">Arquivos Selecionados ({files.length})</h3>
              </div>
              <div className="p-4 space-y-3">
                  {files.map((file, idx) => (
                      <div key={idx} className="flex flex-col md:flex-row gap-4 p-4 border border-gray-200 rounded-lg bg-white items-start md:items-center">
                          <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2 mb-1">
                                  <FileText className="w-4 h-4 text-gray-400" />
                                  <span className="font-medium text-gray-800 truncate">{file.name}</span>
                              </div>
                              <span className="text-xs text-gray-500">{formatSize(file.size)}</span>
                          </div>
                          <div className="flex-1 w-full md:w-auto">
                              <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Categoria</label>
                              <select className="w-full text-sm border-gray-300 rounded px-2 py-1.5 border" value={file.category} onChange={(e) => updateFileCategory(idx, e.target.value)}>
                                  {DOCUMENT_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                              </select>
                          </div>
                          <div className="w-full md:w-40">
                              <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Vencimento</label>
                              <input type="text" className="w-full text-sm border-gray-300 rounded px-2 py-1.5 border" value={file.dueDate} placeholder="DD/MM/AAAA" onChange={(e) => { const newFiles = [...files]; newFiles[idx].dueDate = e.target.value; setFiles(newFiles); }} />
                          </div>
                          <button onClick={() => removeFile(idx)} className="text-gray-400 hover:text-red-500 p-2"><X className="w-5 h-5" /></button>
                      </div>
                  ))}
              </div>
              <div className="p-4 border-t border-gray-100 flex justify-end">
                  <button 
                    onClick={handleUploadClick}
                    disabled={isUploading}
                    className="bg-green-600 text-white px-8 py-3 rounded-lg hover:bg-green-700 shadow-lg shadow-green-900/20 font-medium flex items-center gap-2 disabled:opacity-70"
                  >
                      {isUploading ? <Loader2 className="w-5 h-5 animate-spin" /> : <UploadIcon className="w-5 h-5" />}
                      {isUploading ? 'Enviando...' : 'Enviar Todos'}
                  </button>
              </div>
          </div>
      )}
    </div>
  );
};

