                            <tr><th className="px-4 py-3">Arquivo</th><th className="px-4 py-3 w-1/3">Empresa Vinculada</th><th className="px-4 py-3 w-1/4">Categoria</th><th className="px-4 py-3 w-10 text-center">Ações</th></tr>
