              ))}
              {getMatrixCompanies().length === 0 && (
                <tr><td colSpan={getMatrixCategories().length + 2} className="px-6 py-8 text-center text-gray-500">Nenhuma empresa encontrada com os filtros selecionados.</td></tr>
