import { Company } from '../types';
import * as pdfjsLib from 'pdfjs-dist';

// Configura o Worker usando CDNJS que é mais estável para cross-origin e decoding
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

/**
 * Normaliza o texto: remove acentos, converte para minúsculo e limpa espaços extras.
 */
export const removeAccents = (text: string): string => {
  if (!text) return "";
  return text
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
};

/**
 * Verifica se uma palavra-chave existe no texto como uma "palavra isolada" 
 * ou termo significativo, evitando matches dentro de outras palavras (ex: 'das' em 'vendas').
 */
const containsKeyword = (text: string, keyword: string): boolean => {
  if (!keyword || keyword.length < 2) return false;

  // Para palavras curtas (<= 3 letras), exigimos que sejam palavras isoladas
  if (keyword.length <= 3) {
    const regex = new RegExp(`(^|[^a-z0-9])${keyword}([^a-z0-9]|$)`, 'i');
    return regex.test(text);
  }

  // Para termos mais longos, a inclusão simples costuma ser segura o suficiente
  return text.includes(keyword);
};

/**
 * Extrai texto de um PDF de forma robusta.
 */
export const extractTextFromPDF = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const loadingTask = pdfjsLib.getDocument({
      data: arrayBuffer,
      cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/cmaps/',
      cMapPacked: true,
      verbosity: 0
    });

    const pdf = await loadingTask.promise;
    let fullText = '';
    const maxPages = Math.min(pdf.numPages, 5); // Lê até 5 páginas para maior precisão

    for (let i = 1; i <= maxPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items
        .map((item: any) => item.str)
        .join(' ')
        .trim();
      fullText += pageText + ' ';
    }

    return fullText.trim(); 
  } catch (error) {
    console.error(`❌ Erro ao extrair texto do PDF: ${file.name}`, error);
    return '';
  }
};

/**
 * Identifica a categoria baseada em um sistema de pontuação e pesos.
 * Obedece estritamente as configurações de prioridade do usuário.
 */
export const identifyCategory = (
    textNormalized: string, 
    keywordMap: Record<string, string[]>, 
    priorityCategories: string[] = []
): string | null => {

  const scores: Record<string, number> = {};

  // 1. Calcular pontuação para cada categoria
  for (const [category, keywords] of Object.entries(keywordMap)) {
    if (!keywords || !Array.isArray(keywords)) continue;

    let categoryScore = 0;

    for (const keyword of keywords) {
      if (!keyword) continue;
      const kwNormalized = removeAccents(keyword);

      if (containsKeyword(textNormalized, kwNormalized)) {
        // Pontuação baseada no tamanho da keyword (palavras maiores = mais certeza)
        // Adicionamos um multiplicador para dar peso a termos compostos
        categoryScore += (kwNormalized.length * 2);
      }
    }

    if (categoryScore > 0) {
      // 2. Aplicar bônus massivo se a categoria for PRIORIDADE (Estrela nas configurações)
      if (priorityCategories.includes(category)) {
        categoryScore += 1000; // Garante que prioridades vençam quase qualquer conflito
      }
      scores[category] = categoryScore;
    }
  }

  // 3. Encontrar a categoria com maior pontuação
  const sortedCategories = Object.entries(scores).sort((a, b) => b[1] - a[1]);

  if (sortedCategories.length > 0) {
    const [bestCategory, bestScore] = sortedCategories[0];
    console.log(`[Processor] Scores:`, scores, `-> Escolhido: ${bestCategory}`);
    return bestCategory;
  }

  return null;
};

/**
 * Identifica a empresa usando match numérico (CNPJ/CPF) ou nome inteligente.
 */
export const identifyCompany = (textNormalized: string, companies: Company[]): Company | null => {
  if (!textNormalized) return null;

  const textOnlyNumbers = textNormalized.replace(/\D/g, '');

  // 1. Prioridade Total: Match Numérico
  for (const company of companies) {
    const companyDocClean = company.docNumber.replace(/\D/g, '');
    if (companyDocClean.length < 5) continue;

    // Match exato ou Raiz CNPJ (8 dígitos)
    if (textOnlyNumbers.includes(companyDocClean) || 
       (companyDocClean.length >= 8 && textOnlyNumbers.includes(companyDocClean.substring(0, 8)))) {
        return company;
    }
  }

  // 2. Match por Nome (Lógica aprimorada)
  const commonTerms = ['ltda', 's.a', 'me', 'epp', 'eireli', 'limitada', 'sa', 'cnpj', 'cpf'];

  let bestMatch: Company | null = null;
  let maxNameScore = 0;

  for (const company of companies) {
    let nameClean = removeAccents(company.name);
    commonTerms.forEach(term => {
        nameClean = nameClean.replace(new RegExp(`\\b${term}\\b`, 'g'), '').trim();
    });

    if (nameClean.length < 3) continue;

    // Se o nome completo limpo está no texto
    if (textNormalized.includes(nameClean)) {
      const score = nameClean.length;
      if (score > maxNameScore) {
        maxNameScore = score;
        bestMatch = company;
      }
    }
  }

  return bestMatch;
};

import React, { useState, useEffect } from 'react';
import { Upload as UploadIcon, X, FileText, Calendar, AlertCircle, Loader2, ChevronLeft, ChevronRight } from 'lucide-react';
import { DOCUMENT_CATEGORIES } from '../constants';
import { calcularTodosVencimentos } from '../utils/dateHelpers';
import { UploadedFile, Company, UserSettings } from '../types';
import { api } from '../services/api';
import { identifyCategory, extractTextFromPDF, removeAccents } from '../utils/documentProcessor'; 
import { DEFAULT_USER_SETTINGS } from '../constants';

interface UploadProps {
  preFillData?: {
    companyId: number;
    competence: string;
  } | null;
  onUploadSuccess: (files: UploadedFile[], companyId: number, competence: string) => void;
  userSettings?: UserSettings; 
}

const Upload: React.FC<UploadProps> = ({ preFillData, onUploadSuccess, userSettings = DEFAULT_USER_SETTINGS }) => {
  const getInitialCompetence = () => {
    const now = new Date();
    if (now.getDate() <= 15) {
        now.setMonth(now.getMonth() - 1);
    }
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const yyyy = now.getFullYear();
    return `${mm}/${yyyy}`;
  };

  const [competence, setCompetence] = useState('');
  const [selectedCompanyId, setSelectedCompanyId] = useState<number | string>('');
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [calculatedDates, setCalculatedDates] = useState<Record<string, string>>({});
  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const [companies, setCompanies] = useState<Company[]>([]);
  const [loadingCompanies, setLoadingCompanies] = useState(false);

  // Combine Default + Custom Categories
  const allCategories = [...DOCUMENT_CATEGORIES, ...(userSettings.customCategories || [])];

  useEffect(() => {
    setLoadingCompanies(true);
    api.getCompanies()
        .then(data => setCompanies(data))
        .catch(err => console.error("Erro ao buscar empresas", err))
        .finally(() => setLoadingCompanies(false));

    if (preFillData) {
      setCompetence(preFillData.competence);
      setSelectedCompanyId(preFillData.companyId);
    } else {
      setCompetence(getInitialCompetence());
    }
  }, [preFillData]);

  useEffect(() => {
    if (competence.match(/^\d{2}\/\d{4}$/)) {
        const dates = calcularTodosVencimentos(competence, userSettings.categoryRules);
        setCalculatedDates(dates);
        setFiles(prev => prev.map(f => {
            if (dates[f.category]) {
                return { ...f, dueDate: dates[f.category] };
            }
            return f;
        }));
    }
  }, [competence, userSettings]);

  const changeCompetence = (delta: number) => {
      if (!competence.includes('/')) return;
      const [m, y] = competence.split('/').map(Number);
      const date = new Date(y, m - 1 + delta, 1);
      const newM = String(date.getMonth() + 1).padStart(2, '0');
      const newY = date.getFullYear();
      setCompetence(`${newM}/${newY}`);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    processFiles(Array.from(e.dataTransfer.files));
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      processFiles(Array.from(e.target.files));
    }
  };

  const processFiles = async (fileList: File[]) => {
    setIsProcessing(true);

    const newFiles: UploadedFile[] = [];

    for (const file of fileList) {
        let pdfText = "";

        if (file.type === 'application/pdf') {
            try {
                pdfText = await extractTextFromPDF(file);
            } catch (err) {
                console.warn(`Erro lendo PDF ${file.name}`, err);
            }
        }

        // Normaliza o texto extraído E o nome do arquivo para busca
        const combinedText = removeAccents(pdfText + " " + file.name);

        // Chama a identificação aprimorada com pontuação e prioridades
        const identified = identifyCategory(
            combinedText, 
            userSettings.categoryKeywords, 
            userSettings.priorityCategories
        );

        let category = identified ?? 'Outros';

        let dueDate = '';
        if (category && calculatedDates[category]) {
            dueDate = calculatedDates[category];
        }

        newFiles.push({
            name: file.name,
            size: file.size,
            category: category,
            dueDate: dueDate,
            file: file
        });
    }

    setFiles(prev => [...prev, ...newFiles]);
    setIsProcessing(false);
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const updateFileCategory = (index: number, newCategory: string) => {
    setFiles(prev => prev.map((f, i) => {
        if (i === index) {
            const newDate = calculatedDates[newCategory] || f.dueDate;
            return { ...f, category: newCategory, dueDate: newDate };
        }
        return f;
    }));
  };

  const handleUploadClick = async () => {
    if (!selectedCompanyId || !competence) {
        alert('Selecione uma empresa e uma competência');
        return;
    }

    if (files.length === 0) return;

    setIsUploading(true);
    try {
        const uploadedFilesWithServerNames = await Promise.all(files.map(async (f) => {
            const res = await api.uploadFile(f.file);
            return {
                ...f,
                serverFilename: res.filename
            };
        }));

        onUploadSuccess(uploadedFilesWithServerNames, Number(selectedCompanyId), competence);

        setFiles([]);
        setIsSuccess(true);
        setTimeout(() => setIsSuccess(false), 3000);
    } catch (error) {
        console.error("Erro no upload", error);
        alert("Erro ao enviar arquivos para o servidor.");
    } finally {
        setIsUploading(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Upload de Documentos</h1>
          <p className="text-gray-500">Envie arquivos e o sistema calculará os vencimentos automaticamente.</p>
        </div>
      </div>

      {isSuccess && (
        <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded relative animate-in slide-in-from-top-2" role="alert">
            <strong className="font-bold">Sucesso!</strong>
            <span className="block sm:inline"> Arquivos enviados com sucesso para a aba de Envio.</span>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-fit">
            <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2">
                <AlertCircle className="w-5 h-5 text-blue-500" /> Informações Básicas
            </h3>
            <div className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2">
                        Empresa {loadingCompanies && <Loader2 className="w-3 h-3 animate-spin" />}
                    </label>
                    <select 
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-100 transition-all"
                        value={selectedCompanyId}
                        onChange={e => setSelectedCompanyId(e.target.value)}
                        disabled={loadingCompanies}
                    >
                        <option value="">Selecione uma empresa...</option>
                        {companies.map(c => (
                            <option key={c.id} value={c.id}>{c.name} ({c.docNumber})</option>
                        ))}
                    </select>
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Competência (MM/AAAA)</label>
                    <div className="flex gap-1">
                        <button 
