  if (!textNormalized || !companies) return null;

  const textOnlyNumbers = textNormalized.replace(/\D/g, '');

  // 1. Prioridade Máxima: Match Numérico Exato ou Raiz CNPJ
  for (const company of companies) {
    const companyDocClean = (company.docNumber || '').replace(/\D/g, '');
    if (companyDocClean.length < 5) continue;

    if (textOnlyNumbers.includes(companyDocClean) || 
       (companyDocClean.length >= 8 && textOnlyNumbers.includes(companyDocClean.substring(0, 8)))) {
        return company;
    }
  }

  // 2. Match por Nome (Lógica aprimorada eliminando termos comuns)
  const commonTerms = ['ltda', 's.a', 'me', 'epp', 'eireli', 'limitada', 'sa', 'cnpj', 'cpf'];
  let bestMatch: Company | null = null;
  let maxNameScore = 0;

  for (const company of companies) {
    let nameClean = removeAccents(company.name || '');
    commonTerms.forEach(term => {
        nameClean = nameClean.replace(new RegExp(`\\b${term}\\b`, 'g'), '').trim();
    });

    if (nameClean.length < 3) continue;

    if (textNormalized.includes(nameClean)) {
      const score = nameClean.length;
      if (score > maxNameScore) {
        maxNameScore = score;
        bestMatch = company;
      }
    }
  }

  return bestMatch;
};

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Kanban from './components/Kanban';
import Companies from './components/Companies';
import WhatsAppConnect from './components/WhatsAppConnect';
import Documents from './components/Documents';
import Upload from './components/Upload';
import BulkSend from './components/BulkSend';
import ScheduledMessages from './components/ScheduledMessages';
import Settings from './components/Settings';
import Send from './components/Send'; 
import Login from './components/Login';
import { DEFAULT_USER_SETTINGS, MOCK_DOCUMENTS } from './constants';
import { UserSettings, Document, UploadedFile } from './types';
import { api } from './services/api';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activePage, setActivePage] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Inicia com os padrões completos para evitar erros de undefined
  const [userSettings, setUserSettings] = useState<UserSettings>(DEFAULT_USER_SETTINGS);
  const [documents, setDocuments] = useState<Document[]>(MOCK_DOCUMENTS);
  const [uploadPreFill, setUploadPreFill] = useState<{companyId: number, competence: string} | null>(null);

  useEffect(() => {
    const token = localStorage.getItem('cm_auth_token');
    if (token) {
        setIsAuthenticated(true);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
        api.getSettings().then(settings => {
            if (settings && typeof settings === 'object') {
                setUserSettings(prev => ({
                    ...prev,
                    ...settings,
                    // Garante que sub-objetos críticos nunca sejam sobrescritos por nulo
                    categoryKeywords: settings.categoryKeywords || prev.categoryKeywords || {},
                    categoryRules: settings.categoryRules || prev.categoryRules || {},
                    priorityCategories: settings.priorityCategories || prev.priorityCategories || [],
                    visibleDocumentCategories: settings.visibleDocumentCategories || prev.visibleDocumentCategories || []
                }));
            }
        }).catch(err => {
            console.error("Erro ao carregar configurações:", err);
            // Mantém os padrões em caso de erro
        });
    }
  }, [isAuthenticated]);

  const handleLoginSuccess = (token?: string, remember?: boolean) => {
      if (remember && token) {
          localStorage.setItem('cm_auth_token', token);
      }
      setIsAuthenticated(true);
  };

  const handleLogout = () => {
      localStorage.removeItem('cm_auth_token');
      setIsAuthenticated(false);
      setActivePage('dashboard');
  };

  if (!isAuthenticated) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  const handleNavigateToUpload = (companyId: number, competence: string) => {
    setUploadPreFill({ companyId, competence });
    setActivePage('upload');
  };

  const handleNavigateToDocuments = () => {
    setActivePage('documents');
  }

  const handleUploadSuccess = (files: UploadedFile[], companyId: number, competence: string) => {
      const newDocs: Document[] = files.map(f => ({
          id: Date.now() + Math.random(),
          name: f.name,
          category: f.category,
          competence: competence,
          dueDate: f.dueDate,
          status: 'pending', 
          companyId: companyId,
          companyName: 'Loading...', 
          file: f.file,
          serverFilename: f.serverFilename
      }));
      setDocuments(prev => [...prev, ...newDocs]);
  };

  const handleToggleStatus = (companyId: number, category: string, competence: string) => {
      setDocuments(prev => {
          const existingIndex = prev.findIndex(d => 
              d.companyId === companyId && 
              d.category === category && 
              d.competence === competence
          );

          if (existingIndex >= 0) {
              const newDocs = [...prev];
              newDocs[existingIndex] = {
                  ...newDocs[existingIndex],
                  status: newDocs[existingIndex].status === 'sent' ? 'pending' : 'sent'
              };
              return newDocs;
          } else {
              const newDoc: Document = {
                  id: Date.now(),
                  name: `Manual - ${category}`,
                  category: category,
                  competence: competence,
                  dueDate: '',
                  status: 'sent', 
                  companyId: companyId,
                  companyName: 'Manual Entry',
                  isManual: true
              };
              return [...prev, newDoc];
          }
      });
  };

  const handleSendDocuments = (docIds: number[]) => {
      setDocuments(prev => prev.map(doc => {
          if (docIds.includes(doc.id)) {
              return { ...doc, status: 'sent' };
          }
          return doc;
      }));
  };

  const handleDeleteDocument = (id: number) => {
      if(window.confirm("Remover este arquivo da lista de envio?")) {
          setDocuments(prev => prev.filter(d => d.id !== id));
      }
  };

  const handleClearPendingDocuments = (competenceFilter: string) => {
      if(window.confirm(`Excluir TODOS os pendentes da competência ${competenceFilter}?`)) {
          setDocuments(prev => prev.filter(d => !(d.status === 'pending' && d.competence === competenceFilter)));
      }
  };

  const renderContent = () => {
    switch (activePage) {
      case 'dashboard':
        return <Dashboard />;
      case 'companies':
        return <Companies />;
      case 'whatsapp':
        return <WhatsAppConnect />;
      case 'documents':
        return <Documents 
                  userSettings={userSettings} 
                  onNavigateToUpload={handleNavigateToUpload}
                  documents={documents}
                  onToggleStatus={handleToggleStatus}
                  onUploadSuccess={handleUploadSuccess}
               />;
      case 'upload':
        return <Upload 
                  preFillData={uploadPreFill} 
                  onUploadSuccess={handleUploadSuccess}
                  userSettings={userSettings}
               />;
      case 'send':
        return <Send 
                  documents={documents}
                  onSendDocuments={handleSendDocuments}
                  onNavigateToDocuments={handleNavigateToDocuments}
                  userSettings={userSettings}
                  onDeleteDocument={handleDeleteDocument}
                  onClearPendingDocuments={handleClearPendingDocuments}
               />;
      case 'bulksend':
        return <BulkSend />;
      case 'scheduled':
        return <ScheduledMessages />;
      case 'settings':
        return <Settings settings={userSettings} onSave={setUserSettings} />;
      default:
        return (
          <div className="flex flex-col items-center justify-center h-[50vh] text-gray-400">
            <h2 className="text-xl font-semibold mb-2">Página em desenvolvimento</h2>
          </div>
        );
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <Sidebar 
        activePage={activePage} 
        setActivePage={setActivePage} 
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
        onLogout={handleLogout}
      />

      <main className="flex-1 overflow-auto w-full relative">
        <header className="bg-white border-b border-gray-200 px-6 py-4 flex justify-between items-center sticky top-0 z-30">
          <h2 className="text-lg font-semibold text-gray-700 capitalize">
            {activePage === 'bulksend' ? 'Envio em Massa' : activePage === 'settings' ? 'Usuário' : activePage === 'send' ? 'Envio' : activePage}
          </h2>
          <div className="flex items-center gap-4">
             <div className="text-sm text-right hidden sm:block">
                <p className="font-bold text-gray-700">Lucas Araújo</p>
                <p className="text-gray-500 text-xs">Contador | CRC-BA 046968/O</p>
             </div>
             <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-700 font-bold border-2 border-white shadow-sm">
                LA
             </div>
          </div>
        </header>

        <div className="p-6 max-w-7xl mx-auto pb-20">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

