                console.log(`Removed lock file: ${defaultFilePath}`);
            }
        });
    } catch (error) {
        console.error('Error cleaning Puppeteer locks:', error);
    }
};

// ...

const getWaClientWrapper = async (username, authPath) => {
    const sessionDir = path.join(authPath, 'session-' + username);
    cleanPuppeteerLocks(sessionDir); // Clean locks before creating client
    const client = new Client({
      authStrategy: new LocalAuth({
        clientId: username,
        dataPath: authPath,
      }),
      puppeteer: {
          headless: true,
