            // Busca tarefas pendentes e faz JOIN com empresas para pegar o nome
            const sql = `
                SELECT t.*, c.name as companyName 
                FROM tasks t 
                LEFT JOIN companies c ON t.companyId = c.id 
                WHERE t.status != 'concluida'
            `;

