        }
        if (args.action === "search") {
            return new Promise(resolve => {
                const term = args.content || args.topic || "";
                db.all("SELECT topic, content FROM personal_notes WHERE topic LIKE ? OR content LIKE ? LIMIT 3", [`%${term}%`, `%${term}%`], (err, rows) => resolve(JSON.stringify(rows)));
            });
        }
    }
    return "Ferramenta desconhecida.";
};

const runWithRetry = async (fn, retries = 3, delay = 2000) => {
    for (let i = 0; i < retries; i++) {
        try { return await fn(); } catch (error) {
            const isRateLimit = error.message?.includes('429') || error.status === 429;
            if (!isRateLimit || i === retries - 1) throw error;
            await new Promise(resolve => setTimeout(resolve, delay * Math.pow(2, i)));
        }
    }
};

const processAI = async (username, userMessage, mediaPart = null) => {
    const db = getDb(username);
    if (!db || !ai) return "Sistema de IA indisponível.";

    const history = await new Promise(resolve => {
        db.all("SELECT role, content FROM chat_history ORDER BY id DESC LIMIT 6", (err, rows) => {
            resolve(rows ? rows.reverse().map(r => ({ role: r.role === 'user' ? 'user' : 'model', parts: [{ text: r.content }] })) : []);
        });
    });

    const now = new Date();
    const systemInstruction = `Você é o "Contábil Bot". DATA/HORA ATUAL: ${now.toLocaleString('pt-BR')} (ISO: ${now.toISOString()}).
    REGRAS:
    1. **Tarefas:** Use 'consult_tasks' ou 'update_task_status'.
    2. **Mensagens:** Use 'send_message_to_company' para enviar.
    3. **Lembretes:** Use 'set_personal_reminder'.
    4. **Memória:** Use 'manage_memory'.
    5. **Saída:** Seja direto.`;

    const currentParts = [];
    if (mediaPart) currentParts.push(mediaPart);
    if (userMessage) currentParts.push({ text: userMessage });

    try {
        const chat = ai.chats.create({ 
            model: "gemini-3-flash-preview", 
            config: { systemInstruction, tools: [{ functionDeclarations: assistantTools }] },
            history: history
        });

        let response = await runWithRetry(() => chat.sendMessage({ message: currentParts }));
        let functionCalls = response.functionCalls;
        let loopCount = 0;

        while (functionCalls && functionCalls.length > 0 && loopCount < 5) {
            loopCount++;
            const call = functionCalls[0];
            const result = await executeTool(call.name, call.args, db, username);
            response = await runWithRetry(() => chat.sendMessage({
                message: [{ functionResponse: { name: call.name, response: { result: result } } }]
            }));
            functionCalls = response.functionCalls;
        }

        const finalText = response.text || "Comando processado.";
        db.run("INSERT INTO chat_history (role, content, timestamp) VALUES (?, ?, ?)", ['user', userMessage, now.toISOString()]);
        db.run("INSERT INTO chat_history (role, content, timestamp) VALUES (?, ?, ?)", ['model', finalText, now.toISOString()]);
        return finalText;
    } catch (e) {
        log("[AI Error]", e);
        return "Desculpe, tive um problema momentâneo.";
    }
};

// --- WHATSAPP WRAPPER ---
const waClients = {}; 
const getWaClientWrapper = (username) => {
    if (!username) return null;
    if (!waClients[username]) {
        log(`[WhatsApp Init] Inicializando cliente para usuário: ${username}`);
        waClients[username] = { client: null, qr: null, status: 'disconnected', info: null };
        const authPath = path.join(DATA_DIR, `whatsapp_auth_${username}`);
        if (!fs.existsSync(authPath)) fs.mkdirSync(authPath, { recursive: true });
        cleanPuppeteerLocks(path.join(authPath, `session-${username}`));

        const client = new Client({
            authStrategy: new LocalAuth({ clientId: username, dataPath: authPath }), 
            puppeteer: {
                headless: true,
                executablePath: process.env.PUPPETEER_EXECUTABLE_PATH || '/usr/bin/chromium-browser',
                args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-accelerated-2d-canvas', '--no-first-run', '--no-zygote', '--disable-gpu', '--disable-software-rasterizer', '--single-process'],
            }
        });

        client.on('message', async (msg) => {
            if (msg.from.includes('@g.us') || msg.isStatus) return;
            const db = getDb(username);
            const settings = await new Promise(resolve => db.get("SELECT settings FROM user_settings WHERE id = 1", (e, r) => resolve(r ? JSON.parse(r.settings) : null)));

            if (!settings?.dailySummaryNumber) return;
            const authorized = settings.dailySummaryNumber.replace(/\D/g, '');
            const sender = msg.from.replace('@c.us', '').replace(/\D/g, '');

            if (!sender.endsWith(authorized)) return;

            let mediaPart = null;
            let text = msg.body;
            if (msg.hasMedia) {
                try {
                    const media = await msg.downloadMedia();
                    if (media) mediaPart = { inlineData: { mimeType: media.mimetype, data: media.data } };
                } catch (e) { log("Erro download media", e); }
            }
            const response = await processAI(username, text, mediaPart);
            await safeSendMessage(client, msg.from, response);
        });

        client.on('qr', (qr) => { QRCode.toDataURL(qr, (err, url) => { waClients[username].qr = url; waClients[username].status = 'generating_qr'; }); });
        client.on('ready', () => { waClients[username].status = 'connected'; waClients[username].qr = null; });
        client.initialize().catch(e => { log(`[WhatsApp Init] ERRO FATAL (${username})`, e); waClients[username].status = 'error'; });
        waClients[username].client = client;
    }
    return waClients[username];
};

const sendDailySummaryToUser = async (user) => {
    const db = getDb(user);
    if (!db) return;
    const waWrapper = getWaClientWrapper(user);
    if (waWrapper.status !== 'connected') return { success: false, message: 'WhatsApp desconectado' };

    return new Promise((resolve) => {
        db.get("SELECT settings FROM user_settings WHERE id = 1", (e, r) => {
            if (!r) { resolve({ success: false }); return; }
            const settings = JSON.parse(r.settings);
            if (!settings.dailySummaryNumber) { resolve({ success: false }); return; }

            db.all("SELECT * FROM tasks WHERE status != 'concluida'", async (err, tasks) => {
                if (tasks && tasks.length > 0) {
                    let msg = `*📅 Resumo Diário*\nVocê tem *${tasks.length}* tarefas pendentes.\n\n`;
                    tasks.forEach(t => msg += `• ${t.title} (${t.priority})\n`);
                    let number = settings.dailySummaryNumber.replace(/\D/g, '');
                    if (!number.startsWith('55')) number = '55' + number;
                    await safeSendMessage(waWrapper.client, `${number}@c.us`, msg);
                    resolve({ success: true });
                } else {
                    resolve({ success: true, message: "Sem tarefas" });
                }
            });
        });
    });
};

const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; 
    if (!token) return res.status(401).json({ error: 'Token não fornecido' });
    const parts = token.split('-');
    if (parts.length < 3) return res.status(403).json({ error: 'Token inválido' });
    req.user = parts.slice(2).join('-'); 
    next();
};

