            to: to,
            subject: subject,
            html: htmlBody,
            attachments: files.map(f => ({
                filename: f.originalname,
                path: f.path
            }))
        };

        const info = await emailTransporter.sendMail(mailOptions);

        // SALVA NO BANCO LOCAL (Itens Enviados do Sistema)
        const db = getDb(req.user);
